css:
/* ══ PKG CONVERSION PAGE ══ */
.pkg-page { width:100%; min-height:100vh; background:#f4f7fb; padding-bottom:40px; font-family:Inter,Arial,sans-serif; color:#1f2937; }
.pkg-header { background:#0D2B4E; color:#fff; padding:14px 24px; }
.pkg-title { font-size:16px; font-weight:800; letter-spacing:.02em; }
.pkg-sub { font-size:10.5px; color:#b8c9d9; margin-top:4px; }
.pkg-gold-bar { height:3px; background:#B8860B; }
.navbar{display:none;}
.web-footer{display:none;}

.pkg-nav { display:flex; gap:0; border-bottom:2px solid #E5E7EB; padding:0 24px; background:#fff; }
.pkg-tab { padding:12px 20px; font-size:12.5px; font-weight:700; color:#595959; cursor:pointer; border-bottom:3px solid transparent; margin-bottom:-2px; transition:.15s; }
.pkg-tab:hover { color:#0D2B4E; }
.pkg-tab.active { color:#0D2B4E; border-bottom-color:#B8860B; }
.pkg-badge { background:#C00000; color:#fff; font-size:9px; padding:1px 6px; border-radius:10px; margin-left:4px; }

.pkg-content { max-width:1200px; margin:0 auto; padding:20px 20px 0; }

/* STEP BAR */
.pkg-step-bar { display:flex; align-items:center; justify-content:center; gap:0; margin-bottom:24px; background:#fff; border-radius:12px; padding:14px 20px; border:1px solid #E5E7EB; }
.pkg-step { display:flex; flex-direction:column; align-items:center; flex:1; position:relative; }
.pkg-step:not(:last-child)::after { content:""; position:absolute; right:0; top:16px; width:100%; height:2px; background:#E5E7EB; z-index:0; }
.pkg-step.done:not(:last-child)::after, .pkg-step.active:not(:last-child)::after { background:#1E7A34; }
.pkg-sdot { width:34px; height:34px; border-radius:50%; background:#E5E7EB; color:#595959; font-weight:800; display:flex; align-items:center; justify-content:center; font-size:13px; z-index:1; position:relative; }
.pkg-sdot.active { background:#0D2B4E; color:#fff; }
.pkg-sdot.done { background:#1E7A34; color:#fff; }
.pkg-slbl { font-size:10px; color:#8C8C8C; margin-top:5px; text-align:center; font-weight:600; }
.pkg-slbl.active { color:#0D2B4E; font-weight:700; }
.pkg-slbl.done { color:#1E7A34; }

/* CARDS */
.pkg-card-head { background:#0D2B4E; color:#fff; padding:12px 16px; border-radius:8px; font-weight:700; font-size:14px; margin-bottom:14px; }
.pkg-card { background:#fff; border:1px solid #E5E7EB; border-radius:10px; padding:18px; margin-bottom:14px; }
.pkg-client-detail-card { background:#F0F7EE; border:1.5px solid #A8D5A2; border-radius:10px; padding:18px; margin-bottom:14px; }
.pkg-client-card-head { font-weight:800; color:#1E7A34; font-size:14px; margin-bottom:14px; padding-bottom:10px; border-bottom:1px solid #A8D5A2; }
.pkg-check-icon { color:#1E7A34; font-size:16px; }
.pkg-client-grid { display:grid; grid-template-columns:repeat(6, 1fr); gap:12px; margin-bottom:16px; }
.pkg-field-block label { font-size:9px; color:#8C8C8C; text-transform:uppercase; letter-spacing:.05em; display:block; margin-bottom:3px; }
.pkg-field-val { font-size:13px; font-weight:600; color:#0D2B4E; }

/* SECTION LABEL */
.pkg-section-label { font-weight:800; font-size:11px; color:#0D2B4E; text-transform:uppercase; letter-spacing:.06em; margin:14px 0 8px; border-left:3px solid #B8860B; padding-left:8px; }

/* TABLES */
.pkg-table-wrap { overflow-x:auto; border:1px solid #E5E7EB; border-radius:8px; margin-bottom:14px; }
.pkg-table { width:100%; border-collapse:collapse; font-size:12px; }
.pkg-table th { background:#F8FAFC; color:#595959; padding:10px 12px; text-align:left; border-bottom:1px solid #E5E7EB; font-weight:700; white-space:nowrap; }
.pkg-table td { padding:10px 12px; border-bottom:1px solid #F1F5F9; color:#374151; vertical-align:middle; }
.pkg-empty { text-align:center; color:#8C8C8C; font-style:italic; }
.pkg-row-selected { background:#E8F5EC !important; }
.pkg-row-selected td { background:#E8F5EC !important; }

/* SELECT BTN */
.pkg-select-cb { width:18px; height:18px; cursor:pointer; }
.pkg-status-pill { display:inline-block; padding:2px 10px; border-radius:20px; font-size:10px; font-weight:700; }
.pkg-status-active { background:#E8F5EC; color:#1E7A34; }
.pkg-status-pending { background:#FFF8E7; color:#B8860B; }
.pkg-status-rejected { background:#FBE9E7; color:#C00000; }
.pkg-status-done { background:#E8F5EC; color:#1E7A34; }

/* SEARCH */
.pkg-search-label { font-size:10px; font-weight:800; color:#0D2B4E; text-transform:uppercase; letter-spacing:.06em; margin-bottom:6px; }
.pkg-search-input { width:100%; height:46px; border:1.5px solid #d1d5db; border-radius:8px; padding:0 14px; font-size:14px; outline:none; box-sizing:border-box; }
.pkg-search-input:focus { border-color:#0D2B4E; }
.pkg-ac-list { position:absolute; z-index:9999; left:0; right:0; background:#fff; border:1px solid #d1d5db; border-radius:8px; box-shadow:0 12px 30px rgba(0,0,0,.14); max-height:300px; overflow-y:auto; margin-top:4px; display:none; }
.pkg-ac-list.show { display:block; }
.pkg-ac-item { padding:10px 14px; cursor:pointer; border-bottom:1px solid #F1F5F9; }
.pkg-ac-item:hover { background:#F0F7EE; }
.pkg-ac-name { font-weight:700; font-size:12.5px; color:#0D2B4E; }
.pkg-ac-sub { font-size:10.5px; color:#8C8C8C; margin-top:2px; }

/* MEDICAL BOX */
.pkg-medical-box { background:#F8FAFC; border:1px solid #E5E7EB; border-radius:8px; padding:12px; font-size:12px; color:#595959; font-style:italic; margin-bottom:14px; }

/* BUTTONS */
.pkg-btn-primary { background:#0D2B4E; color:#fff; border:0; border-radius:8px; padding:11px 20px; font-weight:700; font-size:13px; cursor:pointer; }
.pkg-btn-primary:hover { background:#0a2240; }
.pkg-btn-primary:disabled { opacity:.5; cursor:not-allowed; }
.pkg-btn-success { background:#1E7A34; color:#fff; border:0; border-radius:8px; padding:11px 20px; font-weight:700; font-size:13px; cursor:pointer; }
.pkg-btn-success:hover { background:#155c27; }
.pkg-btn-outline { background:#fff; color:#0D2B4E; border:1.5px solid #0D2B4E; border-radius:8px; padding:9px 16px; font-weight:700; font-size:12px; cursor:pointer; }
.pkg-btn-outline:hover { background:#F0F7EE; }
.pkg-btn-light { background:#F0F0F0; color:#0D2B4E; border:0; border-radius:8px; padding:8px 14px; font-weight:600; font-size:12px; cursor:pointer; }
.pkg-btn-danger { background:#C00000; color:#fff; border:0; border-radius:8px; padding:8px 14px; font-weight:700; font-size:12px; cursor:pointer; }
.btn-sm { font-size:11px; padding:7px 12px; }

/* BALANCE BAR */
.pkg-balance-box { background:#FFFBF0; border:1px solid #F0E0A0; border-radius:8px; padding:12px 16px; margin-bottom:14px; font-size:13px; color:#92400E; }

/* NEW PACKAGE CARD */
.pkg-new-pkg-card { background:#FFFBF0; border:1.5px solid #F0E0A0; border-radius:10px; padding:18px; margin-bottom:14px; }
.pkg-plan-row { display:grid; grid-template-columns:1fr 100px 140px 140px 36px; gap:10px; align-items:start; margin-bottom:12px; }
.pkg-plan-row input[type="number"], .pkg-plan-row input[type="text"] { height:36px; border:1px solid #d1d5db; border-radius:6px; padding:0 10px; font-size:12.5px; width:100%; box-sizing:border-box; }
.pkg-plan-row input[type="text"] { background:#fff; }
.pkg-plan-row input[readonly] { background:#f8fafc; color:#595959; }
.pkg-row-lbl { font-size:9.5px; color:#8C8C8C; text-transform:uppercase; letter-spacing:.04em; display:block; margin-bottom:4px; }
/* Therapy type live search dropdown */
.pkg-tp-search { cursor:text; }
.pkg-tp-search:focus { border-color:#0D2B4E; outline:none; }
.pkg-tp-dropdown { display:none; position:absolute; left:0; right:0; top:calc(100% + 2px); background:#fff; border:1px solid #d1d5db; border-radius:8px; box-shadow:0 8px 24px rgba(0,0,0,.12); max-height:220px; overflow-y:auto; z-index:9999; }
.pkg-tp-dd-item { padding:9px 12px; font-size:12.5px; color:#374151; cursor:pointer; border-bottom:1px solid #f1f5f9; }
.pkg-tp-dd-item:last-child { border-bottom:0; }
.pkg-tp-dd-item:hover { background:#F0F7EE; color:#0D2B4E; font-weight:600; }
.pkg-tp-dd-empty { color:#8C8C8C; font-style:italic; cursor:default; }
.pkg-remove-row-btn { background:#FBE9E7; color:#C00000; border:0; border-radius:6px; width:32px; height:32px; cursor:pointer; font-size:16px; display:flex; align-items:center; justify-content:center; margin-top:20px; }

/* PROGRESS BAR */
.pkg-progress-bar-wrap { height:14px; background:#E5E7EB; border-radius:20px; overflow:hidden; margin-bottom:8px; }
.pkg-progress-bar { height:100%; background:#1E7A34; border-radius:20px; transition:width .3s; }
.pkg-total-row { display:flex; justify-content:space-between; font-size:12.5px; color:#374151; margin-bottom:14px; }

/* NOTE */
.pkg-note { background:#F0F7EE; border-left:3px solid #1E7A34; padding:10px 14px; border-radius:6px; font-size:11.5px; color:#374151; margin-bottom:12px; }

/* TERMS */
.pkg-terms-block { background:#fff; border:1px solid #E5E7EB; border-radius:8px; padding:12px; margin-bottom:12px; }
.pkg-checkbox-label { display:flex; align-items:flex-start; gap:10px; font-size:12px; color:#374151; cursor:pointer; }
.pkg-checkbox-label input { margin-top:2px; width:16px; height:16px; cursor:pointer; }

/* CLIENT SUMMARY BAR */
.pkg-client-summary-bar { background:#F8FAFC; border:1px solid #E5E7EB; border-radius:8px; padding:10px 14px; font-size:12px; color:#374151; margin-bottom:14px; }
.pkg-dot-green { display:inline-block; width:8px; height:8px; background:#1E7A34; border-radius:50%; margin-right:4px; }
.pkg-medical-flag { background:#E8F5EC; color:#1E7A34; padding:3px 10px; border-radius:20px; font-size:11px; font-weight:700; }

/* OTP */
.pkg-otp-note { background:#F0F7EE; border:1px solid #A8D5A2; border-radius:8px; padding:12px; font-size:12.5px; color:#374151; margin-bottom:18px; text-align:center; }
.pkg-otp-boxes { display:flex; gap:10px; justify-content:center; margin:10px 0; }
.pkg-otp-box { width:50px; height:58px; border:2px solid #d1d5db; border-radius:8px; text-align:center; font-size:22px; font-weight:800; color:#0D2B4E; outline:none; }
.pkg-otp-box:focus { border-color:#0D2B4E; }

/* SUBMITTED */
.pkg-submitted-card { max-width:560px; margin:30px auto; background:#fff; border:1px solid #E5E7EB; border-radius:16px; padding:40px; text-align:center; }
.pkg-success-icon { font-size:60px; margin-bottom:14px; }
.pkg-success-title { font-size:18px; font-weight:800; color:#1E7A34; margin-bottom:8px; }
.pkg-doc-id { font-size:24px; font-weight:900; color:#0D2B4E; margin-bottom:16px; }
.pkg-success-details { background:#F8FAFC; border-radius:8px; padding:14px; font-size:12.5px; text-align:left; line-height:2; margin-bottom:20px; }
.pkg-success-details strong { color:#0D2B4E; }

/* ALL REQUESTS LIST */
.pkg-fbar { display:flex; gap:16px; align-items:flex-end; flex-wrap:wrap; margin-bottom:16px; background:#0D2B4E; padding:14px 18px; border-radius:8px; }
.pkg-lbl { display:block; font-size:9.5px; color:#b8c9d9; text-transform:uppercase; letter-spacing:.05em; margin-bottom:4px; }
.pkg-select { height:34px; border-radius:6px; border:1px solid #d1d5db; padding:0 10px; font-size:12px; }

.pkg-request-item { background:#fff; border:1px solid #E5E7EB; border-radius:8px; padding:12px 14px; margin-bottom:8px; cursor:pointer; }
.pkg-request-item:hover { border-color:#0D2B4E; }
.pkg-request-item.active { border-color:#0D2B4E; background:#F0F7EE; }
.pkg-request-item-top { display:flex; justify-content:space-between; align-items:center; }
.pkg-request-id { font-weight:800; font-size:12px; color:#0D2B4E; }
.pkg-request-sub { font-size:10.5px; color:#595959; margin-top:3px; }

.pkg-detail-panel { background:#fff; border:1px solid #E5E7EB; border-radius:10px; padding:18px; }
.pkg-detail-head { font-weight:800; font-size:14px; color:#0D2B4E; margin-bottom:4px; }
.pkg-timeline { margin-top:12px; }
.pkg-timeline-item { display:flex; gap:12px; margin-bottom:12px; }
.pkg-timeline-dot { width:10px; height:10px; border-radius:50%; background:#0D2B4E; margin-top:4px; flex-shrink:0; }
.pkg-timeline-content { font-size:11.5px; }
.pkg-timeline-title { font-weight:700; color:#0D2B4E; }
.pkg-timeline-by { color:#1E7A34; font-size:10px; }
.pkg-timeline-time { color:#8C8C8C; font-size:10px; }
.pkg-timeline-desc { color:#595959; font-size:11px; margin-top:2px; }

/* APPROVAL DASHBOARD */
.pkg-approval-tiles { display:grid; grid-template-columns:repeat(3, 1fr); gap:12px; margin-bottom:18px; }
.pkg-tile { border-radius:8px; padding:14px 16px; border:1px solid #E5E7EB; }
.pkg-tile-label { font-size:9px; color:#8C8C8C; text-transform:uppercase; letter-spacing:.05em; }
.pkg-tile-val { font-size:24px; font-weight:900; margin-top:4px; }
.pkg-tile-n { background:#E7ECF2; border-left:3px solid #0D2B4E; }
.pkg-tile-g { background:#FFF8E7; border-left:3px solid #B8860B; }
.pkg-tile-gr { background:#E8F5EC; border-left:3px solid #1E7A34; }
.pkg-tile-n .pkg-tile-val { color:#0D2B4E; }
.pkg-tile-g .pkg-tile-val { color:#B8860B; }
.pkg-tile-gr .pkg-tile-val { color:#1E7A34; }

/* APPROVAL REMARKS */
.pkg-remarks-area { width:100%; min-height:80px; border:1px solid #d1d5db; border-radius:8px; padding:10px; font-size:12px; resize:vertical; box-sizing:border-box; margin-top:10px; }
.pkg-approve-bar { display:flex; gap:10px; margin-top:12px; }

/* RESPONSIVE */
@media(max-width:900px){
  .pkg-client-grid { grid-template-columns:repeat(3,1fr); }
  .pkg-approval-tiles { grid-template-columns:repeat(2,1fr); }
}
@media(max-width:600px){
  .pkg-client-grid { grid-template-columns:repeat(2,1fr); }
  .pkg-plan-row { grid-template-columns:1fr 80px; }
}

/* ── PACKAGE-TO-PACKAGE ALL REQUESTS COMPACT LAYOUT ── */
#pkgTab1{
  --pkg-request-panel-height:min(760px, calc(100vh - 220px));
}

.pkg-all-requests-layout{
  display:grid;
  grid-template-columns:350px minmax(0, 1fr);
  gap:16px;
  align-items:stretch;
  min-height:0;
}

.pkg-all-left{
  height:var(--pkg-request-panel-height);
  display:flex;
  flex-direction:column;
  min-height:0;
}

#pkgAllRequestsList{
  flex:1;
  min-height:0;
  overflow-y:auto;
  overflow-x:hidden;
  padding-right:4px;
}

#pkgRequestDetail{
  height:var(--pkg-request-panel-height);
  overflow-y:auto;
  overflow-x:hidden;
  padding:0 !important;
}

.pkg-detail-scroll{
  padding:18px;
}

#pkgAllRequestsList::-webkit-scrollbar,
#pkgRequestDetail::-webkit-scrollbar{
  width:7px;
}

#pkgAllRequestsList::-webkit-scrollbar-thumb,
#pkgRequestDetail::-webkit-scrollbar-thumb{
  background:#c8d0dc;
  border-radius:10px;
}

#pkgAllRequestsList::-webkit-scrollbar-track,
#pkgRequestDetail::-webkit-scrollbar-track{
  background:#f1f4f8;
}

/* Pagination */
#pkgRequestPagination,
#pkgApprovalPagination {
  flex: 0 0 auto;
  padding-top: 8px;
  margin-top: 8px;
  border-top: 1px solid #E5E7EB;
}

.pkg-approval-left {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

#pkgApprovalList {
  min-width: 0;
}

.pkg-pagination-info{
  font-size:10px;
  font-weight:800;
  color:#0D2B4E;
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-bottom:7px;
}

.pkg-pagination-info span{
  color:#8C8C8C;
  font-weight:700;
}

.pkg-pagination-actions{
  display:flex;
  gap:8px;
}

.pkg-page-btn{
  flex:1;
  height:32px;
  border:none;
  border-radius:7px;
  background:#0D2B4E;
  color:#fff;
  font-size:10.5px;
  font-weight:800;
  cursor:pointer;
}

.pkg-page-btn:disabled{
  opacity:.45;
  cursor:not-allowed;
}

/* Empty/loading states */
.pkg-empty-list,
.pkg-detail-empty,
.pkg-detail-loading{
  color:#8C8C8C;
  font-size:12px;
  text-align:center;
  padding:24px;
}

/* Right-side request detail */
.pkg-detail-shell{
  font-size:11.5px;
}

.pkg-detail-main-head{
  background:#0D2B4E;
  color:#fff;
  border-radius:12px;
  padding:16px 18px;
  display:flex;
  justify-content:space-between;
  align-items:flex-start;
  gap:12px;
  margin-bottom:14px;
}

.pkg-detail-doc{
  color:#b8c9d9;
  font-size:10px;
  font-weight:800;
  margin-bottom:4px;
}

.pkg-detail-title-row{
  color:#fff;
  font-size:18px;
  font-weight:900;
  line-height:1.25;
}

.pkg-detail-sub{
  color:#d7e2ef;
  font-size:11px;
  margin-top:4px;
}

.pkg-detail-chip-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));
  gap:10px;
  margin-bottom:14px;
}

.pkg-info-chip{
  background:#F8FAFC;
  border:1px solid #E5E7EB;
  border-radius:9px;
  padding:10px 12px;
}

.pkg-info-chip span{
  display:block;
  font-size:8.8px;
  color:#8C8C8C;
  text-transform:uppercase;
  letter-spacing:.05em;
  font-weight:900;
  margin-bottom:4px;
}

.pkg-info-chip strong{
  display:block;
  color:#0D2B4E;
  font-size:12px;
  word-break:break-word;
}

.pkg-detail-two-col{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:12px;
  margin-bottom:14px;
}

.pkg-flow-card{
  border-radius:10px;
  padding:13px;
  border:1.5px solid #E5E7EB;
}

.pkg-flow-source{
  background:#EEF2FB;
  border-color:#b5c4e0;
}

.pkg-flow-new{
  background:#F2FAF5;
  border-color:#a8d8b5;
}

.pkg-flow-card-title{
  font-size:9px;
  color:#667085;
  font-weight:900;
  text-transform:uppercase;
  letter-spacing:.05em;
  margin-bottom:5px;
}

.pkg-flow-card-value{
  color:#0D2B4E;
  font-size:12px;
  font-weight:800;
  line-height:1.5;
  word-break:break-word;
}

.pkg-settlement-card{
  background:#FFFBF0;
  border:1.5px solid #F0E0A0;
  border-radius:10px;
  padding:13px 14px;
  margin-bottom:14px;
  display:flex;
  justify-content:space-between;
  gap:12px;
  align-items:center;
}

.pkg-settlement-label{
  color:#92400E;
  font-size:9px;
  font-weight:900;
  text-transform:uppercase;
  letter-spacing:.05em;
  margin-bottom:4px;
}

.pkg-settlement-value{
  color:#0D2B4E;
  font-size:14px;
  font-weight:900;
}

.pkg-settlement-sub{
  color:#595959;
  font-size:11px;
  text-align:right;
}

.pkg-mini-table-wrap{
  border:1px solid #E5E7EB;
  border-radius:9px;
  overflow:auto;
  margin-bottom:14px;
}

.pkg-mini-table{
  width:100%;
  border-collapse:collapse;
  font-size:11px;
}

.pkg-mini-table th{
  background:#F8FAFC;
  color:#0D2B4E;
  padding:8px 10px;
  border-bottom:1px solid #E5E7EB;
  text-align:left;
  white-space:nowrap;
}

.pkg-mini-table td{
  padding:8px 10px;
  border-bottom:1px solid #F1F5F9;
}

.pkg-num{
  text-align:right;
  font-family:monospace;
}

/* Mobile */
@media(max-width:900px){
  #pkgTab1{
    --pkg-request-panel-height:auto;
  }

  .pkg-all-requests-layout{
    grid-template-columns:1fr;
  }

  .pkg-all-left,
  #pkgRequestDetail{
    height:auto;
  }

  #pkgAllRequestsList,
  #pkgRequestDetail{
    overflow:visible;
  }

  .pkg-detail-two-col{
    grid-template-columns:1fr;
  }

  .pkg-settlement-card{
    flex-direction:column;
    align-items:flex-start;
  }

  .pkg-settlement-sub{
    text-align:left;
  }
}

.pkg-plan-link{
  color:#0D2B4E;
  font-weight:800;
  text-decoration:none;
}

.pkg-plan-link:hover{
  color:#B8860B;
  text-decoration:underline;
}

.pkg-plan-link{
  color:#0D2B4E;
  font-weight:800;
  text-decoration:none;
}

.pkg-plan-link:hover{
  color:#B8860B;
  text-decoration:underline;
}

/* ── P2P LEFT CARD NEW PRIORITY LAYOUT ── */
