  border-radius: 12px;
  background: #F8FAFC;
}

.pkg-mini-approval-flow {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  align-items: start;
}

.pkg-mini-flow-stage {
  position: relative;
  min-width: 0;
  padding-right: 12px;
}

.pkg-mini-flow-top {
  display: flex;
