  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 900;
  flex-shrink: 0;
}

.pkg-mini-flow-label {
  color: #0D2B4E;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.2;
}

.pkg-mini-flow-actor {
  margin-top: 5px;
  padding-left: 32px;
  color: #5B6B80;
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1.3;
  white-space: normal;
  overflow-wrap: anywhere;
}

.pkg-mini-flow-connector {
  position: absolute;
  top: 11px;
  right: -8px;
  width: 16px;
  height: 2px;
  background: #CBD5E1;
}

.pkg-mini-flow-approved .pkg-mini-flow-icon {
  background: #DCFCE7;
  color: #166534;
  border: 1px solid #86EFAC;
}

.pkg-mini-flow-rejected .pkg-mini-flow-icon {
  background: #FEE2E2;
  color: #B91C1C;
  border: 1px solid #FCA5A5;
}

.pkg-mini-flow-pending .pkg-mini-flow-icon {
  background: #FEF3C7;
  color: #B45309;
  border: 1px solid #FCD34D;
}

.pkg-mini-flow-upcoming .pkg-mini-flow-icon {
  background: #E2E8F0;
  color: #475569;
  border: 1px solid #CBD5E1;
}

.pkg-mini-flow-approved .pkg-mini-flow-label {
  color: #166534;
}

.pkg-mini-flow-rejected .pkg-mini-flow-label {
  color: #B91C1C;
}

.pkg-mini-flow-pending .pkg-mini-flow-label {
  color: #B45309;
}

@media (max-width: 900px) {
  .pkg-mini-approval-flow {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .pkg-mini-flow-stage {
    padding-right: 0;
  }

  .pkg-mini-flow-connector {
    display: none;
  }
}

.pkg-mini-flow-actor {
  margin-top: 5px;
  padding-left: 32px;
  color: #0D2B4E;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.3;
  white-space: normal;
  overflow-wrap: anywhere;
}

.pkg-mini-flow-approved .pkg-mini-flow-actor {
  color: #166534;
}

.pkg-mini-flow-rejected .pkg-mini-flow-actor {
  color: #B91C1C;
}

.pkg-mini-flow-pending .pkg-mini-flow-actor {
  color: #B45309;
}

.pkg-mini-flow-stopped
.pkg-mini-flow-icon {
  background: #E2E8F0;
  color: #64748B;
  border: 1px solid #CBD5E1;
}

.pkg-mini-flow-stopped
.pkg-mini-flow-label {
  color: #64748B;
}

.pkg-mini-flow-stopped
