  function p2pUniqueEmails(list) {
  var out = [];
  var seen = {};

  (list || []).forEach(function (email) {
    email = String(email || "").trim();

    if (!email || email.indexOf("@") === -1) return;

    var key = email.toLowerCase();

    if (!seen[key]) {
      seen[key] = 1;
      out.push(email);
    }
  });

  return out;
}


function p2pMailCall(method, args) {
  return new Promise(function (resolve, reject) {
    frappe.call({
      method: method,
      args: args || {},
      callback: function (r) {
        resolve(r.message);
      },
      error: function (err) {
        reject(err);
      }
    });
  });
}

