  try {
    await p2pMailCall("frappe.core.doctype.communication.email.make", {
      recipients: recipients.join(","),
      subject: subject,
      content: html,
      doctype: DOCTYPE,
      name: docname,
      send_email: 1
    });

  } catch (e) {
    ("P2P mail failed:", e, void 0);
  }
}


