function getP2PUrlParam(key) {
    try {
        var params = new URLSearchParams(
            window.location.search || ""
        );

        return String(
            params.get(key) || ""
        ).trim();
    } catch (error) {
        ("Unable to read P2P URL parameter:", key, error, void 0);

        return "";
    }
}

function normalizeP2PLinkRole(value) {
    var role = String(value || "")
        .trim()
        .toLowerCase();

    /*
     * Centre Manager aliases
     */
    if (
        role === "cm" ||
        role === "centre manager" ||
        role === "center manager"
    ) {
        return "cm";
    }

    /*
     * Operations Head / Audit Team aliases
     */
    if (
        role === "ops" ||
        role === "audit" ||
        role === "audit team" ||
        role === "operations head"
    ) {
        return "ops";
    }

    /*
     * COO / Management aliases
     */
    if (
        role === "coo" ||
        role === "management" ||
        role === "coo / management" ||
        role === "operations coo / management"
    ) {
        return "coo";
    }

    return "cm";
}

