function upsertP2PRequestInState(
  request,
  placeFirst
) {
  request = request || {};

  if (!request.name) {
    return -1;
  }

  var rows = state.allRequests || [];
  var index = rows.findIndex(
    function (row) {
      return String(row.name || "") ===
        String(request.name || "");
    }
  );

  if (index >= 0) {
    rows[index] = Object.assign(
      {},
      rows[index],
      request
    );

    return index;
  }

  if (placeFirst) {
    rows.unshift(request);
    return 0;
  }

  rows.push(request);
  return rows.length - 1;
}


