function openP2PAllRequestsRequest(
  requestName
) {
  requestName = String(
    requestName || ""
  ).trim();

  if (!requestName) {
    return;
  }

  /*
   * Clear local filters so the linked request cannot
   * be hidden by a previously selected state/search.
   */
  var statusFilter =
    root.querySelector(
      "#pkgStatusFilter"
    );

  if (statusFilter) {
    statusFilter.value = "";
  }

  var searchInput =
    root.querySelector(
      "#pkgAllRequestsSearch"
    );

  if (searchInput) {
    searchInput.value = "";
  }

  var searchClear =
    root.querySelector(
      "#pkgAllRequestsSearchClear"
    );

  if (searchClear) {
    searchClear.style.display = "none";
  }

  state.selectedRequestName = requestName;
  state.currentPage = 1;

  /*
   * Open All Requests without firing its normal tab
   * click handler. This prevents an unnecessary early
   * render and removes the old timeout/click race.
   */
  activateP2PTabImmediately(1);

  var detailPanel =
    root.querySelector(
      "#pkgRequestDetail"
    );

  if (detailPanel) {
    detailPanel.innerHTML = `
      <div class="pkg-detail-scroll">
        <div class="pkg-detail-loading">
          Loading linked request...
        </div>
      </div>
    `;
  }

  /*
   * Fetch the exact request first. Historical records
   * may be outside the latest 200-row list.
   */
  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: DOCTYPE,
      name: requestName
    },

    callback: function (response) {
      var request =
        response &&
        response.message
          ? response.message
          : null;

      if (
        !request ||
        !request.name
      ) {
        showP2PLinkedRequestError(
          "Requested P2P record was not found."
        );

        return;
      }

      request.__p2p_full_loaded = true;

      upsertP2PRequestInState(
        request,
        true
      );

      state.selectedRequestName =
        requestName;

      state.currentPage = 1;

      /*
       * Start one shared linked-invoice query before the
       * detail is rendered. The detail's bill buttons,
       * Booked By line, and amount hydration will all reuse
       * this same in-flight Promise.
       */
      var linkedInvoiceReady =
        fetchP2PLinkedSalesInvoices(request)
          .catch(function (error) {
            ("Redirected P2P invoice prefetch failed:", error, void 0);

            return [];
          });

      /*
       * Render and select the exact record immediately.
       * No setTimeout and no simulated delayed lookup.
       */
      renderAllRequests({
        selectedName: requestName
      });

      /*
       * Do not compete with the critical invoice request.
       * Load the surrounding 200-record list only after the
       * invoice lookup has settled. Preserve the detail.
       */
      linkedInvoiceReady.then(function () {
        loadAllRequests(function () {
          var requestIndex =
            upsertP2PRequestInState(
              request,
              false
            );

          state.selectedRequestName =
            requestName;

          state.currentPage =
            requestIndex >= 0
              ? Math.floor(
                  requestIndex /
                  state.PER_PAGE
                ) + 1
              : 1;

          renderAllRequests({
            selectedName: requestName,
            preserveDetail: true
          });
        });
      });
    },

    error: function () {
      showP2PLinkedRequestError(
        "Unable to open the requested P2P record."
      );
    }
  });
}

