  // ══ STEP 1: Find Client ══
  // ── Signature Pad ──
  var sigState = { drawing: false, hasSignature: false, ctx: null };

  function initSignaturePad() {
    var canvas = root.querySelector("#pkgSignatureCanvas");
    if (!canvas) return;
    // Set actual pixel dimensions
    canvas.width  = canvas.offsetWidth  || 600;
    canvas.height = 120;
    var ctx = canvas.getContext("2d");
    sigState.ctx = ctx;
    ctx.strokeStyle = "#0D2B4E";
    ctx.lineWidth   = 2;
    ctx.lineCap     = "round";
    ctx.lineJoin    = "round";

    function getPos(e) {
      var rect = canvas.getBoundingClientRect();
      var src  = e.touches ? e.touches[0] : e;
      return { x: src.clientX - rect.left, y: src.clientY - rect.top };
    }
    function start(e) { e.preventDefault(); sigState.drawing = true; var p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); }
    function move(e)  { e.preventDefault(); if (!sigState.drawing) return; var p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); sigState.hasSignature = true; updateSigStatus(); }
    function stop(e)  { e.preventDefault(); sigState.drawing = false; ctx.beginPath(); }

    canvas.addEventListener("mousedown",  start);
    canvas.addEventListener("mousemove",  move);
    canvas.addEventListener("mouseup",    stop);
    canvas.addEventListener("mouseleave", stop);
    canvas.addEventListener("touchstart", start, { passive: false });
    canvas.addEventListener("touchmove",  move,  { passive: false });
    canvas.addEventListener("touchend",   stop);

    var clearBtn = root.querySelector("#pkgClearSignBtn");
    if (clearBtn) clearBtn.addEventListener("click", function () {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      sigState.hasSignature = false;
      updateSigStatus();
    });
  }

  function updateSigStatus() {
    var el = root.querySelector("#pkgSignStatus");
    if (!el) return;
    if (sigState.hasSignature) {
      el.textContent = "✓ Signature captured";
      el.style.color = "#1E7A34";
    } else {
      el.textContent = "Draw signature above";
      el.style.color = "#8C8C8C";
    }
  }

  function getSignatureDataURL() {
    var canvas = root.querySelector("#pkgSignatureCanvas");
    if (!canvas || !sigState.hasSignature) return null;
    return canvas.toDataURL("image/png");
  }

