function cleanP2PClientSearchText(value) {
  value = String(value || "");

  // Allow client name, mobile number, client id style text.
  // Allows spaces for names like "Mahesh Babu Reddy"
  value = value.replace(/[^a-zA-Z0-9\s.\-_/]/g, "");

  // Convert multiple spaces to one space, but DO NOT trim while typing
  value = value.replace(/\s{2,}/g, " ");

  // Remove starting space only
  value = value.replace(/^\s+/, "");

  // Max search length
  if (value.length > 80) {
    value = value.slice(0, 80);
  }

  return value;
}


function isValidP2PClientSearchText(value) {
  value = String(value || "").trim();

  if (!value) return false;

  // Minimum 2 chars
  if (value.length < 2) return false;

  // Maximum 80 chars
  if (value.length > 80) return false;

  // If only digits, allow search only after at least 4 digits
  if (/^\d+$/.test(value) && value.length < 4) {
    return false;
  }

  // Block same character repeated too much
  if (/(.)\1{10,}/.test(value)) {
    return false;
  }

  return true;
}

