    }
    box.innerHTML = rows.map(function (r) {
      var name = r.value || ""; var desc = stripHtml(r.description || "");
      return '<div class="pkg-ac-item" data-client="' + esc(name) + '">'
        + '<div class="pkg-ac-name">' + esc(name) + '</div>'
        + '<div class="pkg-ac-sub">' + esc(desc) + '</div></div>';
    }).join("");
