function fetchClientDetails(patientName) {
  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: "Patient",
      name: patientName
    },
    callback: function (r) {
      var p = r.message || {};

      state.clientDoc = p;
      state.clientName = p.patient_name || p.name || "";
      state.clientMobile =
        p.mobile_no ||
        p.mobile ||
        p.custom_mobile_number ||
        "";

      var si = root.querySelector("#pkgClientSearch");
      if (si) {
        si.value =
          state.clientName +
          (state.clientMobile ? " — " + state.clientMobile : "");
      }

      lockP2PClientSearch(true);

      fillClientCard(p);

      resolveClientBranch(patientName, p, function (branch) {
        setClientBranch(branch);
      });

      loadClientPackages(patientName);
      loadBreaks(patientName);
    },
    error: function () {
      frappe.msgprint("Unable to fetch client details.");
    }
  });
}


function fillClientCard(p) {
  var card = root.querySelector("#pkgClientCard");
  if (card) card.style.display = "block";

  sigState.hasSignature = false;
  setTimeout(function () {
    initSignaturePad();
    updateSigStatus();
  }, 50);

  setText("pkgClientName", p.patient_name || p.name || "—");
  setText("pkgClientMobile", p.mobile_no || p.mobile || p.custom_mobile_number || "—");
  setText("pkgClientAltMobile", p.phone || p.custom_alternative_mobile || "—");
  setText("pkgClientEmail", p.email_id || p.email || "—");
  setText("pkgClientGender", p.sex || p.gender || "—");

  var dob = p.dob || "";
  var age = dob ? Math.floor((new Date() - new Date(dob)) / 31536000000) : "—";
  setText("pkgClientAge", String(age));

  setClientBranch(getPatientBranch(p));

  var medEl = root.querySelector("#pkgMedicalHistory");
  if (medEl) {
    medEl.textContent =
      p.custom_medical_history ||
      p.medical_history ||
      "No significant medical history reported.";
  }
}


function loadClientPackages(patientName) {
  var tbody = root.querySelector("#pkgPackageRows");
  if (!tbody) return;

  tbody.innerHTML = '<tr><td colspan="8" class="pkg-empty">Loading...</td></tr>';

  Promise.all([
