function renderPackageRows(invoices, plans, tbody) {
  var planMap = {};

  (plans || []).forEach(function (pl) {
    if (pl && pl.name) planMap[pl.name] = pl;
  });

  var rows = (invoices || []).map(function (inv) {
    var planId = getInvoiceTherapyPlanReference(inv);
    var plan = planMap[planId] || {};

    var total = num(plan.total_sessions || 0);
    var used = getUsedSessions(plan);
    var paid = getP2PInvoicePaidAmount(inv);

    var therapyLabel = getTherapyTypes(plan);
    var branch = getPlanBranch(plan, [inv]);

    var planHtml = planId
      ? '<a class="pkg-plan-link" href="' + esc(getTherapyPlanDeskUrl(planId)) + '" target="_blank">' + esc(planId) + '</a>'
      : '<span style="color:#C00000;font-weight:700">No linked Therapy Plan</span>';

    return ''
      + '<tr>'
      + '<td><b>' + esc(inv.name) + '</b><br><small style="color:#8C8C8C">' + esc(fmtDate(inv.posting_date)) + '</small></td>'
      + '<td>'
      + planHtml
      + '<br><small style="color:#595959">' + esc(therapyLabel || "—") + '</small>'
      + '<br><small style="color:#8C8C8C">Branch: ' + esc(branch || "—") + '</small>'
      + '</td>'
      + '<td>' + total + '</td>'
      + '<td>' + used + '</td>'
      + '<td>' + Math.max(total - used, 0) + '</td>'
      + '<td>' + esc(fmtDate(inv.posting_date)) + '</td>'
      + '<td>₹' + round(paid).toLocaleString("en-IN") + '</td>'
      + '<td>₹' + round(num(inv.outstanding_amount || 0)).toLocaleString("en-IN") + '</td>'
      + '</tr>';
  });

  tbody.innerHTML =
    rows.join("") ||
    '<tr><td colspan="8" class="pkg-empty">No packages found</td></tr>';
}

  function loadBreaks(patientName) {
    var tbody = root.querySelector("#pkgBreakRows");
    if (!tbody) return;
    tbody.innerHTML = '<tr><td colspan="4" class="pkg-empty">Loading...</td></tr>';
    // Try to fetch break information from the Patient doctype directly
    frappe.call({
      method: "frappe.client.get",
      args: { doctype: "Patient", name: patientName },
      callback: function (r) {
        var p = r.message || {};
        var breaks = [];
        // Look for break child table in Patient doc
        Object.keys(p).forEach(function (key) {
          if (!Array.isArray(p[key])) return;
          p[key].forEach(function (child) {
            if (child.break_from || child.from_date || child.custom_break_from) {
              breaks.push({
                from: child.break_from || child.from_date || child.custom_break_from || "",
                to: child.break_to || child.to_date || child.custom_break_to || "",
                reason: child.reason || child.remarks || child.notes || "—",
                approved_by: child.approved_by || child.owner || "Centre Manager"
              });
            }
          });
        });
        if (!breaks.length) {
          tbody.innerHTML = '<tr><td colspan="4" class="pkg-empty">No break records</td></tr>';
        } else {
          tbody.innerHTML = breaks.map(function (b) {
            return '<tr><td>' + esc(fmtDate(b.from)) + '</td><td>' + esc(fmtDate(b.to)) + '</td><td>' + esc(b.reason) + '</td><td>' + esc(b.approved_by) + '</td></tr>';
          }).join("");
        }
      },
      error: function () { tbody.innerHTML = '<tr><td colspan="4" class="pkg-empty">No break records</td></tr>'; }
    });
  }

