function fetchInvoices(patientName) {
  return new Promise(function (resolve) {
    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Sales Invoice",
        filters: [
          ["Sales Invoice", "patient", "=", patientName],
          ["Sales Invoice", "docstatus", "=", 1],
          ["Sales Invoice", "is_return", "=", 0]
        ],
        fields: [
          "name",
          "grand_total",
          "rounded_total",
          "base_grand_total",
          "base_rounded_total",
          "total",
          "net_total",
          "outstanding_amount",
          "paid_amount",
          "status",
          "branch",
          "posting_date"
        ],
        order_by: "posting_date desc",
        limit_page_length: 100
      },
      callback: function (r) {
        fetchFullInvoices(r.message || []).then(function (fullInvoices) {
          resolve(fullInvoices || []);
        });
      },
      error: function () {
        resolve([]);
      }
    });
  });
}

function fetchFullInvoices(invoiceRows) {
  var calls = (invoiceRows || []).map(function (invoice) {
    return new Promise(function (resolve) {
      frappe.call({
        method: "frappe.client.get",
        args: {
          doctype: "Sales Invoice",
          name: invoice.name
        },
        callback: function (r) {
          var fullInvoice = r.message || invoice;

          // Preserve safe list fields also
          fullInvoice.grand_total = fullInvoice.grand_total || invoice.grand_total;
            fullInvoice.rounded_total = fullInvoice.rounded_total || invoice.rounded_total;
            fullInvoice.base_grand_total = fullInvoice.base_grand_total || invoice.base_grand_total;
            fullInvoice.base_rounded_total = fullInvoice.base_rounded_total || invoice.base_rounded_total;
            fullInvoice.total = fullInvoice.total || invoice.total;
            fullInvoice.net_total = fullInvoice.net_total || invoice.net_total;
            fullInvoice.outstanding_amount = fullInvoice.outstanding_amount || invoice.outstanding_amount;
            fullInvoice.paid_amount = fullInvoice.paid_amount || invoice.paid_amount;
            fullInvoice.status = fullInvoice.status || invoice.status;
            fullInvoice.branch = fullInvoice.branch || invoice.branch;
            fullInvoice.posting_date = fullInvoice.posting_date || invoice.posting_date;

            fullInvoice.therapy_plan_reference_id =
              fullInvoice.therapy_plan_reference_id ||
              invoice.therapy_plan_reference_id ||
              "";

            fullInvoice.custom_therapy_plan_reference_id =
              fullInvoice.custom_therapy_plan_reference_id ||
              invoice.custom_therapy_plan_reference_id ||
              "";

            fullInvoice.therapy_plan =
              fullInvoice.therapy_plan ||
              invoice.therapy_plan ||
              "";

          resolve(fullInvoice);
        },
        error: function () {
          resolve(invoice);
        }
      });
    });
  });

  return Promise.all(calls);
}

function getInvoiceTherapyPlanReference(invoice) {
  if (!invoice) return "";

  return (
    invoice.therapy_plan_reference_id ||
    invoice.custom_therapy_plan_reference_id ||
    invoice.therapy_plan ||
    invoice.custom_therapy_plan ||
    getInvoiceTherapyPlanFromItems(invoice.items || []) ||
    ""
  );
}

function getInvoiceTherapyPlanFromItems(items) {
  var rows = items || [];

  for (var i = 0; i < rows.length; i++) {
    var item = rows[i];

    var plan =
      item.therapy_plan_reference_id ||
      item.custom_therapy_plan_reference_id ||
      item.therapy_plan ||
      item.custom_therapy_plan ||
      "";

    if (plan) return plan;
  }

  return "";
}

function fetchPlans(patientName) {
