function getTherapyTypes(plan) {
  var types = [];

  Object.keys(plan || {}).forEach(function (key) {
    if (!Array.isArray(plan[key])) return;

    plan[key].forEach(function (row) {
      var t =
        row.therapy_type ||
        row.therapy ||
        row.service_name ||
        row.item_code ||
        row.item_name ||
        "";

      if (t && types.indexOf(t) === -1) {
        types.push(t);
      }
    });
  });

  if (!types.length && plan.therapy_plan_template) {
    types.push(plan.therapy_plan_template);
  }

  return types.length ? types.join(", ") : "—";
}

function p2pTherapyKey(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function getP2PTargetCategory() {
  var el = root.querySelector("#pkgTargetCategory");
  return el ? String(el.value || "").trim() : "";
}

function getP2PClientMedia() {
  var el = root.querySelector("#pkgClientMedia");
  return el ? String(el.value || "").trim() : "";
}

function getP2PTargetCategoryFullName() {
  var val = getP2PTargetCategory();

  if (val === "All") return "All Healthcare Service Units - LSACPL";
  if (val === "Darmat") return "Darmat - LSACPL";
  if (val === "Hair") return "Hair - LSACPL";
  if (val === "Laser") return "Laser - LSACPL";
  if (val === "Physiotherapy") return "Physiotherapy - LSACPL";
  if (val === "Skin") return "Skin - LSACPL";
  if (val === "Slimming") return "Slimming - LSACPL";
  if (val === "LifeRise") return "LifeRise - LSACPL";
  if (val === "HT") return "HT - LSACPL";

  return val;
}

function clearP2PAllowedTherapyTypes() {
  state.allowedTherapyTypeMap = {};
}

function addP2PAllowedTherapyToMap(row) {
  if (!row) return;

  var nameKey = p2pTherapyKey(row.name || "");
  var labelKey = p2pTherapyKey(row.therapy_type || "");

  if (nameKey) state.allowedTherapyTypeMap[nameKey] = true;
  if (labelKey) state.allowedTherapyTypeMap[labelKey] = true;
}

function fetchP2PAllowedTherapyTypesForCategory() {
  return new Promise(function (resolve) {
    var targetCategory = getP2PTargetCategoryFullName();

    clearP2PAllowedTherapyTypes();

    if (!targetCategory) {
      resolve({});
      return;
    }

    // For All category, no category validation is required.
    // Allow all therapy rows.
    if (targetCategory === "All Healthcare Service Units - LSACPL") {
      resolve(state.allowedTherapyTypeMap || {});
      return;
    }

    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Therapy Type",
        fields: [
          "name",
          "therapy_type",
          "healthcare_service_unit",
          "disabled"
        ],
        filters: [
          ["Therapy Type", "healthcare_service_unit", "=", targetCategory],
          ["Therapy Type", "disabled", "=", 0]
        ],
        order_by: "modified desc",
        limit_page_length: 1000
      },
      callback: function (r) {
        (r.message || []).forEach(function (row) {
          addP2PAllowedTherapyToMap(row);
        });

        resolve(state.allowedTherapyTypeMap || {});
      },
      error: function () {
        clearP2PAllowedTherapyTypes();
        resolve({});
      }
    });
  });
}


function isP2PTherapyAllowedForTargetCategory(therapyType) {
  var key = p2pTherapyKey(therapyType);
  var targetCategory = getP2PTargetCategoryFullName();

  if (!targetCategory || !key) return false;

  // IMPORTANT:
  // If user selected All Healthcare Service Units,
  // any therapy type is allowed in the new conversion table.
  if (targetCategory === "All Healthcare Service Units - LSACPL") {
    return true;
  }

  return !!(state.allowedTherapyTypeMap && state.allowedTherapyTypeMap[key]);
}


function getP2PAllowedRemainingRowsForPlan(plan) {
  var allowedRows = [];
  var therapyRows = getTherapyRowsForP2PConversion(plan);

  if (!therapyRows.length) {
    therapyRows = [{
      therapy_type: getTherapyTypes(plan) || plan.therapy_plan_template || plan.name || "—",
      current_total_sessions: num(plan.total_sessions || 0),
      completed_sessions: getUsedSessions(plan)
    }];
  }

  therapyRows.forEach(function (row) {
    var therapyType = row.therapy_type || plan.therapy_plan_template || plan.name || "";
    var oldTotal = num(row.current_total_sessions || row.no_of_sessions || row.sessions || 0);
    var oldCompleted = num(row.completed_sessions || row.sessions_completed || row.availed_quantity || 0);
    var remainingSessions = Math.max(oldTotal - oldCompleted, 0);

    if (remainingSessions <= 0) return;

    if (isP2PTherapyAllowedForTargetCategory(therapyType)) {
      allowedRows.push(row);
    }
  });

  return allowedRows;
}

function getP2PInvalidTargetCategoryTherapiesFromDom() {
  var invalid = [];

  root.querySelectorAll(".pkg-conv-row").forEach(function (row) {
    var therapyInput = row.querySelector(".pkg-conv-therapy");
    var therapy = therapyInput ? String(therapyInput.value || "").trim() : "";

    if (!therapy) return;

    if (!isP2PTherapyAllowedForTargetCategory(therapy)) {
      if (invalid.indexOf(therapy) === -1) {
        invalid.push(therapy);
      }
    }
  });

  return invalid;
}

function applyP2PTargetCategoryToDoc(doc, category) {
  var fullCategory = getP2PTargetCategoryFullName();

  // Keep old checkbox fields if they exist in the P2P DocType
  doc.skin = 0;
  doc.hair = 0;
  doc.laser = 0;
  doc.slimming = 0;
  doc.cs = 0;
  doc.ht = 0;

  if (category === "Skin") doc.skin = 1;
  if (category === "Hair") doc.hair = 1;
  if (category === "Laser") doc.laser = 1;
  if (category === "Slimming") doc.slimming = 1;
  if (category === "LifeRise") doc.cs = 1;
  if (category === "HT") doc.ht = 1;

  // Backend will read one of these if the field exists.
  // Unknown fields are ignored by Frappe during save.
  doc.shift_client_to_category = fullCategory;
  doc.conversion_category = fullCategory;
  doc.target_category = fullCategory;
}

function getDuplicateP2PTherapyName(rows) {
  var seen = {};

  for (var i = 0; i < rows.length; i++) {
    var name = rows[i].plan || rows[i].therapy_type || "";
    var key = p2pTherapyKey(name);

    if (!key) continue;

    if (seen[key]) {
      return name;
    }

    seen[key] = true;
  }

  return "";
}



function renderSourcePlanTable(plans, invoices, tbody) {
  var invoicePlanIds = [];

  (invoices || []).forEach(function (inv) {
    var planId = getInvoiceTherapyPlanReference(inv);

    if (planId && invoicePlanIds.indexOf(planId) === -1) {
      invoicePlanIds.push(planId);
    }
  });

  // Only submitted invoiced plans
  plans = (plans || []).filter(function (plan) {
    return invoicePlanIds.indexOf(plan.name) !== -1;
  });

  if (!plans.length) {
    tbody.innerHTML =
      '<tr><td colspan="8" class="pkg-empty">No submitted invoiced therapy plans found</td></tr>';
    state.selectedPlans = [];
    rebuildConversionRowsFromSelectedPlans();
    recalcBalance();
    return;
  }

  state.selectedPlans = [];

  tbody.innerHTML = plans.map(function (plan, i) {
    var sp = p2pBuildSelectedPlanObject(plan, invoices);

    var totalSessions = getP2PPlanTotalSessions(plan);
    var used = getUsedSessions(plan);
    var balQty = getP2PPlanRemainingSessions(plan);

    var status = balQty <= 0 ? "Completed" : (plan.status || "Active");
    var therapyTypes = getTherapyTypes(plan);

    var invNames = (sp.linked || []).map(function (inv) {
      return inv.name;
    }).join(", ") || "—";

    var branch = getPlanBranch(plan, sp.linked);
   var disabledReason = "";

    if (balQty <= 0 || sp.balValue <= 0) {
      disabledReason = "No Paid Pending Value";
    }

    var disabled = !!disabledReason;
    var selectLabel = disabled ? disabledReason : "Select";
    var displayStatus = status;

    return ''
      + '<tr id="pkgPlanRow' + i + '" class="pkg-source-plan-select-row ' + (disabled ? 'pkg-row-disabled' : '') + '" data-plan-idx="' + i + '">'
      + '<td>'
