    var tr = tbody.querySelector("#pkgPlanRow" + idx);
    var cb = tbody.querySelector('.pkg-select-cb[data-plan-idx="' + idx + '"]');

    if (cb) cb.checked = !!checked;
    if (tr) tr.classList.toggle("pkg-row-selected", !!checked);

    var existingIndex = -1;

    for (var i = 0; i < state.selectedPlans.length; i++) {
      if (state.selectedPlans[i].name === plan.name) {
        existingIndex = i;
        break;
      }
    }

    if (checked && existingIndex === -1) {
      state.selectedPlans.push(spObj);
