function rebuildConversionRowsFromSelectedPlans() {
  var container = root.querySelector("#pkgNewPlanRows");
  if (!container) return;

  if (!state.selectedPlans || !state.selectedPlans.length) {
    state.newPlanRows = [];

    container.innerHTML = `
      <div class="pkg-empty" style="padding:14px;text-align:center">
        Select one or more source Therapy Plans. Remaining sessions will be copied here as editable new sessions.
      </div>
    `;

    recalcTotal();
    updateGoBtn();
    return;
  }

  if (state.selectedPlans.length === 1) {
      renderSinglePlanEditRowsFromSelectedPlan(state.selectedPlans[0]);
      return;
    }

  var merged = {};

  (state.selectedPlans || []).forEach(function (sp) {
    var plan = sp.plan || {};
    var therapyRows = getTherapyRowsForP2PConversion(plan);

    if (!therapyRows.length) {
      therapyRows = [{
        therapy_type: getTherapyTypes(plan) || plan.therapy_plan_template || plan.name || sp.name || "—",
        current_total_sessions: getP2PPlanTotalSessions(plan),
        completed_sessions: getUsedSessions(plan)
      }];
    }

    var planTotalSessions = getP2PPlanTotalSessions(plan);
    var fallbackRate = planTotalSessions > 0 ? num(sp.paidAmount || 0) / planTotalSessions : 0;

    therapyRows.forEach(function (row) {
      var therapyType = row.therapy_type || plan.therapy_plan_template || plan.name || "";
      var key = p2pTherapyKey(therapyType);

      if (!key) return;

      var oldTotal = num(row.current_total_sessions || row.no_of_sessions || row.sessions || 0);
      var oldCompleted = num(row.completed_sessions || row.sessions_completed || row.availed_quantity || 0);
      var remainingSessions = Math.max(oldTotal - oldCompleted, 0);

      if (remainingSessions <= 0) return;

      var invoiceAmount = getInvoiceItemAmountForTherapy(therapyType, sp.linked || []);
      var invoiceMatched = hasP2PInvoiceItemMatch(therapyType, sp.linked || []);

      var rate = 0;

      if (invoiceMatched && oldTotal > 0) {
        rate = invoiceAmount > 0 ? invoiceAmount / oldTotal : 0;
      } else if (!hasAnyP2PInvoiceItems(sp.linked || []) && oldTotal > 0) {
        rate = fallbackRate;
      } else {
        rate = num(row.rate || 0);
      }

      if (!merged[key]) {
        merged[key] = {
          therapy_type: therapyType,
          old_total_sessions: 0,
          old_completed_sessions: 0,
          suggested_sessions: 0,
          weighted_amount: 0,
          weighted_sessions: 0,
          source_plans: []
        };
      }

      merged[key].old_total_sessions += oldTotal;
      merged[key].old_completed_sessions += oldCompleted;
      merged[key].suggested_sessions += remainingSessions;
      merged[key].weighted_amount += rate * remainingSessions;
      merged[key].weighted_sessions += remainingSessions;

      if (merged[key].source_plans.indexOf(sp.name) === -1) {
        merged[key].source_plans.push(sp.name);
      }
    });
  });

  state.newPlanRows = Object.keys(merged).map(function (key) {
    var row = merged[key];
    var rate = row.weighted_sessions > 0 ? row.weighted_amount / row.weighted_sessions : 0;

    return {
      therapy_type: row.therapy_type,
      old_total_sessions: row.old_total_sessions,
      old_completed_sessions: row.old_completed_sessions,
      suggested_sessions: row.suggested_sessions,
      new_sessions: row.suggested_sessions,
      rate: rate,
      source_plans: row.source_plans
    };
  });

  if (!state.newPlanRows.length) {
    container.innerHTML = `
      <div class="pkg-empty" style="padding:14px;text-align:center">
        Selected Therapy Plans have no remaining sessions to convert.
      </div>
    `;

    recalcTotal();
    updateGoBtn();
    return;
  }

  container.innerHTML = `
    <div class="pkg-conv-table">
      <div class="pkg-conv-head pkg-conv-head-new-session">
