                <input type="hidden" class="pkg-conv-therapy" value="${esc(row.therapy_type || "")}">
              </div>

              <div class="pkg-conv-center">
                ${esc(row.old_completed_sessions)} / ${esc(row.old_total_sessions)}
              </div>

              <div class="pkg-conv-center">
                ${esc(row.suggested_sessions)}
              </div>

              <div>
                <input
                  type="number"
                  class="pkg-conv-new-total"
                  min="0"
                  step="1"
                  value="${esc(qty)}"
                  data-completed="0"
                >
                <div class="pkg-mini-help">Editable. New plan starts from 0 completed.</div>
              </div>

              <div>
                <input
                  type="number"
                  class="pkg-conv-rate pkg-conv-rate-input pkg-rate-readonly"
                  min="0"
                  step="1"
                  value="${esc(round(row.rate))}"
                  readonly
                  tabindex="-1"
                  title="Price / Session is auto-calculated"
                >
              </div>

              <div class="pkg-conv-amount-cell">
                <strong class="pkg-row-applied-amount">
                  ₹${round(amount).toLocaleString("en-IN")}
                </strong>
              </div>

              <div class="pkg-source-plan-mini" title="${esc(sourceText)}">
                ${esc(sourceText || "—")}
              </div>

              <div>
                <button type="button" class="pkg-remove-therapy-btn" data-row-idx="${idx}">
                  Remove
                </button>
              </div>
            </div>
          `;
        }).join("")}
      </div>
    </div>
  `;

  bindP2PConversionRowEvents(container);
  recalcTotal();
  updateGoBtn();
}

  function getUsedSessions(plan) {
    var availed = 0;
    Object.keys(plan || {}).forEach(function (key) {
      if (!Array.isArray(plan[key])) return;
      plan[key].forEach(function (child) {
        availed += num(child.completed_sessions || child.availed_quantity || child.sessions_completed || 0);
      });
    });
    return availed;
  }

  function getTherapyRowsForP2PConversion(plan) {
  var rows = [];

  var possibleTables = [
    "therapy_plan_details",
    "therapy_plan_detail",
    "therapy_details",
    "plan_details",
    "services",
    "items"
  ];

  for (var i = 0; i < possibleTables.length; i++) {
    var tableRows = plan[possibleTables[i]];

    if (!Array.isArray(tableRows) || !tableRows.length) continue;

    tableRows.forEach(function (detail) {
      var therapyType =
        detail.therapy_type ||
        detail.therapy_plan_template ||
        detail.service ||
        detail.service_name ||
        detail.item_name ||
        detail.item_code ||
        detail.therapy ||
        detail.treatment ||
        "";

      var totalSessions = num(
        detail.no_of_sessions ||
        detail.sessions ||
        detail.number_of_sessions ||
        detail.qty ||
        detail.quantity ||
        detail.total_sessions ||
        detail.booked_quantity ||
        0
      );

      var completedSessions = num(
        detail.sessions_completed ||
        detail.completed_sessions ||
        detail.total_sessions_completed ||
        detail.completed_quantity ||
        detail.completed_qty ||
        detail.availed_quantity ||
        detail.availed_sessions ||
        detail.sessions_availed ||
        detail.used_sessions ||
        detail.consumed_sessions ||
        detail.no_of_sessions_completed ||
        detail.custom_sessions_completed ||
        detail.custom_completed_sessions ||
        0
      );

      var rowAmount = num(
        detail.custom_plan_amount ||
        detail.plan_amount ||
        detail.amount ||
        detail.total_amount ||
        detail.balance_amount ||
        0
      );

      var rate = num(
        detail.rate__session ||
        detail.rate_per_session ||
        detail.rate ||
        detail.session_rate ||
        0
      );

      if (!rate && totalSessions > 0 && rowAmount > 0) {
        rate = rowAmount / totalSessions;
      }

      if (!therapyType && !totalSessions) return;
      if (!totalSessions) return;

      rows.push({
        row_name: detail.name || "",
        therapy_type: therapyType || plan.therapy_plan_template || plan.name,
        current_total_sessions: totalSessions,
        completed_sessions: completedSessions,
        rate: rate,
        row_amount: rowAmount
      });
    });

    if (rows.length) return rows;
  }

  rows.push({
    row_name: "",
    therapy_type: plan.therapy_plan_template || plan.category || plan.name,
    current_total_sessions: num(plan.total_sessions || 0),
    completed_sessions: getUsedSessions(plan),
    rate: 0,
    row_amount: 0
  });

  return rows;
}

function getP2PPlanTotalSessions(plan) {
  var total = num(plan.total_sessions || 0);

  if (total > 0) {
    return total;
  }

  var rows = getTherapyRowsForP2PConversion(plan);

  total = 0;

  (rows || []).forEach(function (row) {
    total += num(row.current_total_sessions || row.no_of_sessions || row.sessions || 0);
  });

  return total;
}

function getP2PPlanRemainingSessions(plan) {
  var rows = getTherapyRowsForP2PConversion(plan);
  var remaining = 0;

  (rows || []).forEach(function (row) {
    var total = num(row.current_total_sessions || row.no_of_sessions || row.sessions || 0);
    var completed = num(row.completed_sessions || row.sessions_completed || row.availed_quantity || 0);

    remaining += Math.max(total - completed, 0);
  });

  if (remaining > 0) {
    return remaining;
  }

  return Math.max(getP2PPlanTotalSessions(plan) - getUsedSessions(plan), 0);
}



function getInvoiceItemAmountForTherapy(therapyType, invoices) {
  var target = normalizeP2PText(therapyType);
  var total = 0;
  var matched = false;

  if (!target) return 0;

  (invoices || []).forEach(function (inv) {
    (inv.items || []).forEach(function (item) {
      if (!isP2PInvoiceItemMatch(target, item)) return;

      matched = true;

      // Use actual discounted invoice value, not market/template rate.
      // GST inclusive because page label says Price / Session and previous C2C logic uses GST inclusive transfer amount.
      var taxable = num(
        item.net_amount ||
        item.base_net_amount ||
        0
      );

      var tax =
        num(item.cgst_amount || 0) +
        num(item.sgst_amount || 0) +
        num(item.igst_amount || 0) +
        num(item.cess_amount || 0);

      // If old invoice has no net_amount fields, then fall back to amount.
      if (!taxable && !tax) {
        taxable = num(item.amount || item.base_amount || 0);
      }

      total += taxable + tax;
    });
  });

  // Important:
  // If item is matched but invoice value is zero, return zero.
  // Do NOT apply average fallback to free/included items.
  return matched ? total : 0;
}

function isP2PInvoiceItemMatch(target, item) {
  target = normalizeP2PText(target);

  var parts = [
    item.therapy_type,
    item.item_code,
    item.item_name,
    item.description
  ]
    .map(function (v) {
      return normalizeP2PText(v);
    })
    .filter(Boolean);

  return parts.some(function (text) {
    return (
      text === target ||
      text.indexOf(target) !== -1 ||
      target.indexOf(text) !== -1
    );
  });
}

function hasP2PInvoiceItemMatch(therapyType, invoices) {
  var target = normalizeP2PText(therapyType);
  var found = false;

  if (!target) return false;

  (invoices || []).forEach(function (inv) {
    (inv.items || []).forEach(function (item) {
      if (isP2PInvoiceItemMatch(target, item)) {
        found = true;
      }
    });
  });

  return found;
}

function hasAnyP2PInvoiceItems(invoices) {
  return (invoices || []).some(function (inv) {
    return Array.isArray(inv.items) && inv.items.length > 0;
  });
}


function normalizeP2PText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

