function bindP2PConversionRowEvents(scope) {
  if (!scope) return;

  scope.querySelectorAll(".pkg-conv-new-total").forEach(function (input) {
    if (input.dataset.boundP2PQty === "1") return;
    input.dataset.boundP2PQty = "1";

    input.addEventListener("input", function () {
      enforceP2PNewSessionLimit(input);
      recalcTotal();
    });

    input.addEventListener("change", function () {
      enforceP2PNewSessionLimit(input);
      recalcTotal();
    });
  });

scope.querySelectorAll(".pkg-conv-rate").forEach(function (input) {
  if (input.dataset.boundP2PRateLock === "1") return;
  input.dataset.boundP2PRateLock = "1";

  input.readOnly = true;
  input.classList.add("pkg-rate-readonly");
  input.setAttribute("tabindex", "-1");
  input.setAttribute("title", "Price / Session is auto-fetched and cannot be edited");

  input.addEventListener("keydown", function (e) {
    e.preventDefault();
  });

  input.addEventListener("paste", function (e) {
    e.preventDefault();
  });

  input.addEventListener("wheel", function (e) {
    e.preventDefault();
    input.blur();
  });
});


  scope.querySelectorAll(".pkg-remove-therapy-btn").forEach(function (btn) {
    if (btn.dataset.boundP2PRemove === "1") return;
    btn.dataset.boundP2PRemove = "1";

    btn.addEventListener("click", function () {
      removeP2PConversionRow(btn);
    });
