}

function getP2PManualTherapyTypeFilters() {
  var targetCategory = getP2PTargetCategoryFullName();

  var filters = [
    ["Therapy Type", "disabled", "=", 0],
    ["Therapy Type", "is_billable", "=", 1]
  ];

  // For All, do not restrict by healthcare_service_unit
  if (targetCategory && targetCategory !== "All Healthcare Service Units - LSACPL") {
    filters.push([
      "Therapy Type",
      "healthcare_service_unit",
      "=",
      targetCategory
    ]);
  }

  return filters;
}



function searchTherapyTypeForManualRow(q, dropdown, therapyInput, rateInput, rowEl) {
  q = String(q || "").trim();

  if (!q) {
    dropdown.style.display = "none";
    dropdown.innerHTML = "";
    return;
  }

  dropdown.innerHTML = '<div class="pkg-tp-dd-item pkg-tp-dd-empty">Searching...</div>';
  dropdown.style.display = "block";

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Therapy Type",
      fields: [
        "name",
        "therapy_type",
        "rate",
        "maximum_price",
        "disabled",
        "is_billable"
      ],
      filters: getP2PManualTherapyTypeFilters(),
      or_filters: [
        ["Therapy Type", "name", "like", "%" + q + "%"],
        ["Therapy Type", "therapy_type", "like", "%" + q + "%"]
      ],
      order_by: "modified desc",
      limit_page_length: 20
    },
    callback: function (r) {
      var results = r.message || [];

      if (!results.length) {
        dropdown.innerHTML = `
          <div class="pkg-tp-dd-item pkg-tp-dd-empty">
            No enabled billable therapy type found
          </div>
        `;
        dropdown.style.display = "block";
        return;
      }

      dropdown.innerHTML = results.map(function (t) {
        var label = t.therapy_type || t.name || "";
        var rate = num(t.rate || 0);
        var maxPrice = num(t.maximum_price || 0);

        return `
          <div
            class="pkg-tp-dd-item"
            data-val="${esc(t.name || label)}"
            data-label="${esc(label)}"
            data-rate="${esc(rate)}"
            data-max="${esc(maxPrice)}"
          >
            <strong>${esc(label)}</strong>
            <div style="font-size:10.5px;color:#667085;margin-top:2px">
              Rate: ₹${round(rate).toLocaleString("en-IN")}
              · Max Price: ₹${round(maxPrice).toLocaleString("en-IN")}
            </div>
          </div>
        `;
      }).join("");

      dropdown.style.display = "block";

      dropdown.querySelectorAll(".pkg-tp-dd-item[data-val]").forEach(function (item) {
        item.addEventListener("mousedown", function (e) {
          e.preventDefault();

          var selectedName = item.dataset.val || "";
          var selectedLabel = item.dataset.label || selectedName;
          if (
              isP2PTherapyAlreadyInNewTable(selectedName, rowEl) ||
              isP2PTherapyAlreadyInNewTable(selectedLabel, rowEl)
            ) {
              frappe.msgprint({
                title: "Duplicate Therapy Type Not Allowed",
                indicator: "red",
                message:
                  "Therapy type <b>" +
                  esc(selectedLabel || selectedName) +
                  "</b> is already present in the new package table. Please edit the existing row."
              });

              dropdown.style.display = "none";
              dropdown.innerHTML = "";
              therapyInput.value = "";
              return;
            }
          var selectedRate = num(item.dataset.rate || 0);
          var selectedMax = num(item.dataset.max || 0);

          therapyInput.value = selectedName;
          therapyInput.dataset.therapyType = selectedName;
          therapyInput.dataset.therapyLabel = selectedLabel;
          therapyInput.dataset.billableOnly = "1";
          therapyInput.dataset.maximumPrice = selectedMax;

          dropdown.style.display = "none";
          dropdown.innerHTML = "";

          if (rateInput) {
            rateInput.value = selectedRate || 0;
            rateInput.placeholder = "Rate";
          }

          recalcTotal();
        });
      });
    },
    error: function () {
      dropdown.innerHTML = `
        <div class="pkg-tp-dd-item pkg-tp-dd-empty">
          Search failed
        </div>
      `;
      dropdown.style.display = "block";
    }
  });
}

function enforceP2PNewSessionLimit(input) {
  if (!input) return;

  var value = num(input.value || 0);

  if (value < 0) {
    input.value = 0;
    value = 0;
  }

  if (value % 1 !== 0) {
    input.value = Math.floor(value);
  }
}

function removeP2PConversionRow(btn) {
  if (!btn) return;

  var row = btn.closest(".pkg-conv-row");

  if (!row) return;

  var therapyInput = row.querySelector(
    ".pkg-conv-therapy"
  );

  var qtyInput = row.querySelector(
    ".pkg-conv-new-total"
  );

  var therapyName = therapyInput
    ? String(therapyInput.value || "").trim()
    : "this therapy type";

  var completedSessions = qtyInput
    ? Math.floor(
        num(
          qtyInput.dataset.completed || 0
        )
      )
    : 0;

  var confirmMessage =
    "Remove <b>" +
    esc(therapyName || "this therapy type") +
    "</b> from the converted package?";

  if (completedSessions > 0) {
    confirmMessage +=
      "<br><br>" +
      "<b>Completed Sessions:</b> " +
      esc(completedSessions) +
      "<br>" +
      "The completed session history will remain in the original Therapy Plan, but this Therapy Type will not be included in the converted package.";
  }

  frappe.confirm(
    confirmMessage,

    function () {
      row.remove();

      recalcTotal();

      frappe.show_alert({
        message:
          completedSessions > 0
            ? "Therapy Type removed from converted package. Completed history remains in the original plan."
            : "Therapy Type removed from converted package.",
        indicator: "orange"
      });
    }
  );
}

function recalcBalance() {
  state.combinedBalance = state.selectedPlans.reduce(function (s, sp) {
