  }

  if (cb) {
    cb.textContent = "₹" + round(state.combinedBalance).toLocaleString("en-IN");
  }

  setText("pkgLimitDisplay", "₹" + round(state.combinedBalance).toLocaleString("en-IN"));

  recalcTotal();
}


  // ── New Plan Rows ──

