      + '<div><label class="pkg-row-lbl">PRICE / UNIT</label><input type="number" class="pkg-tp-price" min="0" step="1" placeholder="0"></div>'
      + '<div><label class="pkg-row-lbl">ROW TOTAL</label><input type="number" class="pkg-tp-total" readonly placeholder="0"></div>'
