  function searchTherapyType(q, dropdown, searchInput, hiddenVal) {
    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Therapy Type",
        fields: ["name"],
        filters: [["Therapy Type", "name", "like", "%" + q + "%"]],
        order_by: "name asc",
        limit_page_length: 20
      },
      callback: function (r) {
        var results = r.message || [];
        if (!results.length) {
          dropdown.innerHTML = '<div class="pkg-tp-dd-item pkg-tp-dd-empty">No results for "' + esc(q) + '"</div>';
          dropdown.style.display = "block"; return;
        }
        dropdown.innerHTML = results.map(function (t) {
          return '<div class="pkg-tp-dd-item" data-val="' + esc(t.name) + '">' + esc(t.name) + '</div>';
        }).join("");
        dropdown.style.display = "block";
        dropdown.querySelectorAll(".pkg-tp-dd-item[data-val]").forEach(function (item) {
          item.addEventListener("click", function () {
            var selectedName = item.dataset.val;
            searchInput.value = selectedName;
            hiddenVal.value   = selectedName;
            dropdown.style.display = "none";
            // Auto-fetch rate from Therapy Type and fill Price/Unit
            var rowEl = dropdown.closest(".pkg-plan-row");
            if (rowEl) {
              var priceEl = rowEl.querySelector(".pkg-tp-price");
              if (priceEl) {
                priceEl.value = "";
                priceEl.placeholder = "Fetching rate...";
                frappe.call({
                  method: "frappe.client.get",
                  args: { doctype: "Therapy Type", name: selectedName },
                  callback: function (r) {
                    var doc = r.message || {};
                    var rate = num(doc.rate || doc.minimum_price || 0);
                    priceEl.value = rate;
                    priceEl.placeholder = "0";
                    calcRowTotal(rowEl);
                  },
                  error: function () { priceEl.placeholder = "₹0"; }
                });
              }
            }
            updateGoBtn();
          });
        });
      },
      error: function () {
        dropdown.innerHTML = '<div class="pkg-tp-dd-item pkg-tp-dd-empty">Search failed</div>';
        dropdown.style.display = "block";
      }
    });
  }

  function calcRowTotal(rowEl) {
    var qty   = num((rowEl.querySelector(".pkg-tp-qty")   || {}).value || 0);
    var price = num((rowEl.querySelector(".pkg-tp-price") || {}).value || 0);
    var total = round(qty * price);
    var totalEl = rowEl.querySelector(".pkg-tp-total");
    if (totalEl) totalEl.value = total;
    recalcTotal();
  }

function recalcTotal() {
  var total = 0;

  root.querySelectorAll(".pkg-conv-row").forEach(function (row) {
    var qtyInput = row.querySelector(".pkg-conv-new-total");
    var therapyInput = row.querySelector(".pkg-conv-therapy");
    var rateInput = row.querySelector(".pkg-conv-rate");
    var amountEl = row.querySelector(".pkg-row-applied-amount");

    var newSessions = qtyInput ? Math.floor(num(qtyInput.value || 0)) : 0;
    var completedSessions = qtyInput ? Math.floor(num(qtyInput.dataset.completed || 0)) : 0;
    var rate = rateInput ? num(rateInput.value || 0) : 0;

    if (newSessions < completedSessions) {
      newSessions = completedSessions;
      if (qtyInput) qtyInput.value = completedSessions;
    }

    if (newSessions < 0) {
      newSessions = 0;
      if (qtyInput) qtyInput.value = 0;
    }

    var appliedSessions = Math.max(newSessions - completedSessions, 0);
    var amount = round(appliedSessions * rate);

    total += amount;

    if (amountEl) {
      amountEl.textContent = "₹" + amount.toLocaleString("en-IN");
    }

    if (therapyInput) {
      therapyInput.dataset.appliedAmount = amount;
      therapyInput.dataset.appliedSessions = appliedSessions;
      therapyInput.dataset.completedSessions = completedSessions;
    }
  });

  state.grandTotal = round(total);

  setText("pkgGrandTotal", "₹" + round(total).toLocaleString("en-IN"));

  var bal = state.combinedBalance;
  var remaining = round(bal - total);
  var pct = bal > 0 ? Math.min((total / bal) * 100, 100) : 0;
  var over = total > bal;

  var bar = root.querySelector("#pkgProgressBar");

  if (bar) {
    bar.style.width = pct + "%";
    bar.style.background = over ? "#C00000" : "#1E7A34";
  }

  var remEl = root.querySelector("#pkgRemainingBalance");

  if (remEl) {
    if (!bal) {
      remEl.textContent = "";
    } else if (over) {
      remEl.textContent =
        "Exceeded by ₹" + Math.abs(remaining).toLocaleString("en-IN");
      remEl.style.color = "#C00000";
    } else {
      remEl.textContent =
        "Remaining Paid Pending Value: ₹" + remaining.toLocaleString("en-IN");
      remEl.style.color = "#1E7A34";
    }
  }

  updateGoBtn();
}


function updateGoBtn() {
  var terms = root.querySelector("#pkgTermsCheck");
  var btn = root.querySelector("#pkgGoConversionBtn");

  if (!btn) return;

  var rows = collectNewPlanRows();
  var attachmentValidation = validateP2PMandatoryAttachments();

  var hasSourcePlans = state.selectedPlans.length > 0;
  var hasRows = rows.length > 0;
  var termsOk = !!(terms && terms.checked);
  var categoryOk = !!getP2PTargetCategory();
  var mediaOk = !!getP2PClientMedia();
  var totalOk = state.grandTotal > 0;
  var withinValue =
    state.combinedBalance > 0 &&
    state.grandTotal <= state.combinedBalance;
  var duplicateTherapy = getDuplicateP2PTherapyName(rows);
  var attachmentsOk = !!attachmentValidation.ok;

  btn.disabled = !(
    hasSourcePlans &&
    hasRows &&
    termsOk &&
    categoryOk &&
    mediaOk &&
    totalOk &&
    withinValue &&
    !duplicateTherapy &&
    attachmentsOk
  );

  btn.title = attachmentsOk
    ? ""
    : "Upload all 4 mandatory supporting documents before submitting.";
}


function goForConversion() {
  var rows = collectNewPlanRows();

  if (!state.selectedPlans.length) {
    frappe.msgprint("Please select at least one source Therapy Plan.");
    return;
  }

  if (!rows.length) {
    frappe.msgprint("No therapy rows found for conversion.");
    return;
  }

  var targetCategory = getP2PTargetCategory();

  if (!targetCategory) {
    frappe.msgprint("Please select the category to shift the client for package conversion.");
    return;
  }

  var clientMedia = getP2PClientMedia();

  if (!clientMedia) {
    frappe.msgprint({
      title: "Client Media Required",
      indicator: "red",
      message: "Please select Client Media before submitting the package conversion."
    });
    return;
  }

  var invalidCategoryRows = getP2PInvalidTargetCategoryTherapiesFromDom();

  if (invalidCategoryRows.length) {
    frappe.msgprint({
      title: "Wrong Therapy Category",
      indicator: "red",
      message:
        "These therapy types do not belong to <b>" +
        esc(getP2PTargetCategoryFullName()) +
        "</b>: <b>" +
        esc(invalidCategoryRows.join(", ")) +
        "</b>. Please remove them or select the correct category."
    });
    return;
  }

  var duplicateTherapy = getDuplicateP2PTherapyName(rows);

  if (duplicateTherapy) {
    frappe.msgprint({
      title: "Duplicate Therapy Type Not Allowed",
      indicator: "red",
      message:
        "Therapy type <b>" +
        esc(duplicateTherapy) +
        "</b> is already present. A therapy type can appear only once in the conversion table."
    });
    return;
  }

  var invalidSessionRows = rows.filter(function (row) {
    return num(row.qty || 0) <= 0;
  });

  if (invalidSessionRows.length) {
    frappe.msgprint({
      title: "Invalid Sessions",
      indicator: "red",
      message: "New sessions must be greater than zero for every selected therapy type."
    });
    return;
  }

  var belowCompletedRows = rows.filter(function (row) {
    return num(row.qty || 0) < num(row.completed || 0);
  });

  if (belowCompletedRows.length) {
    frappe.msgprint({
      title: "Invalid Sessions",
      indicator: "red",
      message: "New Total Sessions cannot be less than Completed Sessions."
    });
    return;
  }

  if (state.grandTotal <= 0) {
    frappe.msgprint("Applied conversion amount must be greater than zero.");
    return;
  }

  var P2P_MONEY_TOLERANCE = 1;

  if (
    state.combinedBalance > 0 &&
    state.grandTotal > state.combinedBalance + P2P_MONEY_TOLERANCE
  ) {
    frappe.msgprint({
      title: "Limit Exceeded",
      indicator: "red",
      message:
        "Applied amount ₹" +
        round(state.grandTotal).toLocaleString("en-IN") +
        " exceeds available value ₹" +
        round(state.combinedBalance).toLocaleString("en-IN") +
        "."
    });
    return;
  }

  var terms = root.querySelector("#pkgTermsCheck");

  if (!terms || !terms.checked) {
    frappe.msgprint("Please confirm the terms acknowledgement.");
    return;
  }

  var attachmentValidation = validateP2PMandatoryAttachments();

  if (!attachmentValidation.ok) {
    frappe.msgprint({
      title: "Mandatory Documents Required",
      indicator: "red",
      message: attachmentValidation.message
    });
    return;
  }

  var btn = root.querySelector("#pkgGoConversionBtn");

  if (btn) {
    btn.disabled = true;
    btn.textContent = "Submitting...";
  }

  submitConversionRequest("NO_OTP");
}

function collectNewPlanRows() {
  var rows = [];

  root.querySelectorAll(".pkg-conv-row").forEach(function (row) {
    var therapyInput = row.querySelector(".pkg-conv-therapy");
    var qtyInput = row.querySelector(".pkg-conv-new-total");
    var rateInput = row.querySelector(".pkg-conv-rate");

    var therapy = therapyInput ? String(therapyInput.value || "").trim() : "";
    var newTotalSessions = qtyInput ? Math.floor(num(qtyInput.value || 0)) : 0;
    var completedSessions = qtyInput ? Math.floor(num(qtyInput.dataset.completed || 0)) : 0;
    var rate = rateInput ? num(rateInput.value || 0) : 0;

    if (newTotalSessions < completedSessions) {
      newTotalSessions = completedSessions;
