function normalizeP2PSearchValue(value) {
  value = String(
    value === null || value === undefined
      ? ""
      : value
  );

  /*
   * Remove accents where supported.
   */
  try {
    value = value
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "");
  } catch (error) {
    // Continue with original value.
  }

  return value
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}


function getP2PRequestSearchText(row) {
  row = row || {};

  var status = "";

  try {
    status = getStatus(row) || "";
  } catch (error) {
    status =
      row.approval_display_status ||
      row.approval_stage ||
      row.final_approval_status ||
      "";
  }

  var compactStatus = "";

  try {
    compactStatus =
      getP2PCompactRequestStatus(
        row,
        status
      ) || "";
  } catch (error) {
    compactStatus = status;
  }

  var sourcePlan = "";

  try {
    sourcePlan =
      getP2PCardSourcePlanOnly(row) ||
      getP2PCompactSourcePlan(row) ||
      "";
  } catch (error) {
    sourcePlan =
      row.source_therapy_plans_text ||
      row.source_therapy_plan ||
      "";
  }

  var category = "";

  try {
    category =
      getP2PCardCategory(row) ||
      getP2PCompactCategoryLabel(row) ||
      "";
  } catch (error) {
    category = "";
  }

  var values = [
    row.name,

    row.client_full_name,
    row.name1,
    row.client_name,

    row.mobile_number,
    row.mobile,
    row.contact_number,

    row.branch,
    row.client_branch,
    row.current_branch,
    row.from_branch,

    row.source_therapy_plan,
    row.source_therapy_plans_text,
    sourcePlan,

    category,

    status,
    compactStatus,

    row.approval_stage,
    row.approval_display_status,
    row.automation_status,
    row.final_approval_status,

    row.approved_by_name,
    row.authorised_name,
    row.coo_management_name
  ];

  return normalizeP2PSearchValue(
    values
      .filter(function (value) {
        return (
          value !== null &&
          value !== undefined &&
          String(value).trim() !== ""
        );
      })
      .join(" ")
  );
}


function doesP2PRequestMatchSearch(row, query) {
  query = normalizeP2PSearchValue(query);

  if (!query) {
    return true;
  }

  var searchableText =
    getP2PRequestSearchText(row);

  /*
   * Every typed word must occur somewhere in the request.
   *
   * Example:
   * "yaswanth madhapur"
   * matches client Yaswanth from Madhapur.
   */
  var words = query
    .split(" ")
    .filter(Boolean);

  return words.every(function (word) {
    return searchableText.indexOf(word) !== -1;
  });
}


function debounceP2PSearch(callback, delay) {
  var timeoutId = null;

  return function () {
    var context = this;
    var args = arguments;

    window.clearTimeout(timeoutId);

    timeoutId = window.setTimeout(
      function () {
        callback.apply(context, args);
      },
      delay || 180
    );
  };
}


function bindP2PSearchControl(
  inputSelector,
  clearSelector,
  onSearch
) {
  var input =
    root.querySelector(inputSelector);

  var clearButton =
    root.querySelector(clearSelector);

  if (!input) {
    return;
  }

  function updateClearButton() {
    if (!clearButton) {
      return;
    }

    clearButton.style.display =
      String(input.value || "").trim()
        ? "inline-flex"
        : "none";
  }

  var runSearch = debounceP2PSearch(
    function () {
      updateClearButton();
      onSearch();
    },
    180
  );

  input.addEventListener(
    "input",
    function () {
      updateClearButton();
      runSearch();
    }
  );

  /*
   * Press Escape to clear.
   */
  input.addEventListener(
    "keydown",
    function (event) {
      if (
        event.key === "Escape" &&
        input.value
      ) {
        input.value = "";

        updateClearButton();
        onSearch();

        input.focus();
      }
    }
  );

  if (clearButton) {
    clearButton.addEventListener(
      "click",
      function () {
        input.value = "";

        updateClearButton();
        onSearch();

        input.focus();
      }
    );
  }

  updateClearButton();
}

