function getP2PApprovalTargetStage(role) {
  if (role === "ops") return STAGE.OPS;
  if (role === "coo") return STAGE.COO;
  return STAGE.CM;
}

function getValidP2PPendingApprovals(role) {
  role = role || getCurrentP2PApprovalRole();

  // If user is not allowed for selected role, show 0
  if (role === "ops" && !isAllowedOpsUser()) return [];
  if (role === "coo" && !isAllowedCooUser()) return [];

  var targetStage = getP2PApprovalTargetStage(role);

  return (state.allRequests || []).filter(function (r) {
    var finalStatus = String(r.final_approval_status || "");
    var automationStatus = String(r.automation_status || "");
    var approvalStage = String(r.approval_stage || "");
    var displayStatus = String(r.approval_display_status || "");

    var isClosed =
      finalStatus === "Approved" ||
      finalStatus === "Rejected" ||
      automationStatus === "Process Completed" ||
      automationStatus === "Skipped";

    if (isClosed) return false;

    return approvalStage === targetStage || displayStatus === targetStage;
  });
}

