function p2pDisplayText(value) {
  value = String(value || "");

  return value
    .replace(/Operations Head Approval Pending/g, "Audit Team Approval Pending")
    .replace(/Operations Head/g, "Audit Team")
    .replace(/Operations Final Remarks/g, "Audit Team Remarks")
    .replace(/Operations approval/g, "Audit Team approval")
    .replace(/operations approval/g, "audit team approval");
}

function p2pRemarksHtml(value) {
  var text = p2pDisplayText(value || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .trim();

  if (!text) return "";

  text = text.replace(/\n{3,}/g, "\n\n");

  return (
    '<div class="pkg-remarks-rendered">' +
    esc(text).replace(/\n/g, "<br>") +
    "</div>"
  );
}

function p2pTimelineDescriptionHtml(entry) {
  entry = entry || {};

  var text = p2pDisplayText(entry.desc || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .trim();

  if (!text) return "";

  text = text.replace(/\n{3,}/g, "\n\n");

  // Prevent duplicate label when older data already contains it.
  text = text.replace(
    /^\s*Remarks\s*:-\s*/i,
    ""
  );

  var action = getP2PTimelineActionLabel(entry);

  var isApprovalRemark =
    /Approved|Rejected/i.test(action);

  return (
    '<div class="pkg-remarks-rendered">' +
      (
        isApprovalRemark
          ? '<span class="pkg-timeline-remarks-label">Remarks:-</span> '
          : ''
      ) +
      esc(text).replace(/\n/g, "<br>") +
    "</div>"
  );
}

function p2pRowValue(row, fieldnames) {
  row = row || {};

  for (var i = 0; i < fieldnames.length; i++) {
    var f = fieldnames[i];

    if (
      row[f] !== undefined &&
      row[f] !== null &&
      String(row[f]).trim() !== ""
    ) {
      return row[f];
    }
  }

  return "";
}

function p2pShortText(value, maxLen) {
  value = String(value || "").trim();
  maxLen = maxLen || 40;

  if (value.length <= maxLen) return value;
  return value.slice(0, maxLen - 1) + "…";
}

function p2pCleanCategoryLabel(value) {
  value = String(value || "").trim();

  value = value
    .replace(/\s*[-–]\s*LSACPL\s*$/i, "")
    .replace(/\s+/g, " ")
    .trim();

  if (value === "All Healthcare Service Units") {
    return "All";
  }

  return value;
}

function getP2PCardCategoryFromSourceText(value) {
  value = String(value || "").trim();

  var match = value.match(
    /\s*(?:→|->)\s*(All Healthcare Service Units|Darmat|Hair|Laser|Physiotherapy|Skin|Slimming|LifeRise|HT)(?:\s*[-–]\s*LSACPL)?\s*$/i
  );

  return match ? p2pCleanCategoryLabel(match[1]) : "";
}

function getP2PCardSourcePlanOnly(row) {
  row = row || {};

  var sourcePlan = String(
    row.source_therapy_plans_text ||
    row.source_therapy_plan ||
    "—"
  ).trim();

  // Remove old "→ Skin" / "-> Skin" style if any old data has it
  sourcePlan = sourcePlan.replace(
    /\s*(?:→|->)\s*(All Healthcare Service Units|Darmat|Hair|Laser|Physiotherapy|Skin|Slimming|LifeRise|HT)(?:\s*[-–]\s*LSACPL)?\s*$/i,
    ""
  ).trim();

  return sourcePlan || "—";
}


function getP2PCardCategory(row) {
