function isP2PRejectedCard(row, status) {
  row = row || {};

  var displayStatus = String(row.approval_display_status || "");
  var finalStatus = String(row.final_approval_status || "");
  status = String(status || "");

  return (
    finalStatus === "Rejected" ||
    status === "Rejected" ||
    displayStatus.indexOf("Rejected") !== -1
  );
}

function getP2PCompactRequestStatus(row, status) {
  row = row || {};

  var displayStatus = String(row.approval_display_status || status || "");
  var autoStatus = String(row.automation_status || "");

  if (isP2PRejectedCard(row, status)) {
    return "Rejected";
  }

  if (/Process Completed/i.test(autoStatus) || /Process Completed/i.test(displayStatus)) {
    return "Process Completed";
  }

  if (/Approved\s*\/\s*Pending Therapy/i.test(displayStatus) || /Processing/i.test(autoStatus)) {
    return "Processing";
  }

  if (/COO|Management/i.test(displayStatus)) {
    return "COO Pending";
  }

  if (/Audit Team|Operations Head/i.test(displayStatus)) {
    return "Audit Pending";
  }

  if (/Centre Manager/i.test(displayStatus)) {
    return "CM Pending";
  }

  if (/Approved/i.test(displayStatus)) {
    return "Approved";
  }

  return p2pDisplayText(status || displayStatus || "—");
}

