function p2pParseDateTime(value) {
  value = String(value || "").trim();

  if (!value) return null;

  // Frappe datetime usually comes as:
  // 2026-07-09 16:44:17.459402
  // JS Date handles milliseconds, so trim microseconds.
  value = value.replace(" ", "T");
  value = value.replace(/(\.\d{3})\d+/, "$1");

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    value += "T00:00:00";
  }

  var d = new Date(value);

  if (isNaN(d.getTime())) return null;

  return d;
}

function p2pFormatDuration(ms) {
  ms = Math.max(Number(ms || 0), 0);

  var totalMinutes = Math.floor(ms / 60000);

  if (totalMinutes < 1) {
    return "<1m";
  }

  var minutesInMonth = 30 * 24 * 60;
  var minutesInDay = 24 * 60;

  var months = Math.floor(totalMinutes / minutesInMonth);
  var remainingAfterMonths = totalMinutes % minutesInMonth;

  var days = Math.floor(remainingAfterMonths / minutesInDay);
  var remainingAfterDays = remainingAfterMonths % minutesInDay;

  var hours = Math.floor(remainingAfterDays / 60);
  var minutes = remainingAfterDays % 60;

  var parts = [];

  if (months > 0) {
    parts.push(months + "m");
  }

  if (days > 0) {
    parts.push(days + "d");
  }

  if (hours > 0) {
    parts.push(hours + "h");
  }

  /*
   * Show minutes when:
   * 1. Duration is below one hour, or
   * 2. Duration is below one day.
   */
  if (
    minutes > 0 &&
    months === 0 &&
    days === 0
  ) {
    parts.push(minutes + "m");
  }

  return parts.length ? parts.join(" ") : "<1m";
}
function getP2PProcessEndTime(row, status) {
  row = row || {};
  status = String(status || getStatus(row) || "");

  var autoStatus = String(row.automation_status || "");
  var displayStatus = String(row.approval_display_status || "");

  // Final rejection end time
  if (isP2PRejectedCard(row, status)) {
    var rej = getP2PRejectionInfo(row);

    return (
      p2pParseDateTime(rej.time) ||
      p2pParseDateTime(row.coo_management_date) ||
      p2pParseDateTime(row.authorised_date) ||
      p2pParseDateTime(row.approved_date) ||
      p2pParseDateTime(row.modified)
    );
  }

  // Final process completed end time
  if (
    /Process Completed/i.test(autoStatus) ||
    /Process Completed/i.test(displayStatus) ||
    Number(row.package_conversion_applied || 0) === 1
  ) {
    return (
      p2pParseDateTime(row.process_completed_on) ||
      p2pParseDateTime(row.coo_management_date) ||
      p2pParseDateTime(row.modified)
    );
  }

  // Still pending / running
  return null;
}


