function getP2PProcessTimeInfo(row, status) {
  row = row || {};
  status = String(status || getStatus(row) || "");

  var start = p2pParseDateTime(row.creation);
  var end = getP2PProcessEndTime(row, status);

  if (!start) {
    return {
      label: "",
      cls: "is-unknown",
      title: ""
    };
  }

  var isRejected = isP2PRejectedCard(row, status);
  var isClosed = !!end;
  var endForDuration = end || new Date();

  var elapsedMs = Math.max(
    endForDuration.getTime() - start.getTime(),
    0
  );

  var duration = p2pFormatDuration(elapsedMs);

  if (isRejected) {
    return {
      label: "Process closed in " + duration,
      cls: "is-rejected",
      title: "From request submission to final rejection"
    };
  }

  if (isClosed) {
    return {
      label: "Process completed in " + duration,
      cls: "is-completed",
      title: "From request submission to process completion"
    };
  }

  var oneDayMs = 24 * 60 * 60 * 1000;
  var twoDaysMs = 2 * oneDayMs;
  var pendingClass = "";

  /*
   * Automatic pending-duration color:
   * 0–24 hours    = green
   * Over 24–48 h = yellow
   * Over 48 h    = red
   */
  if (elapsedMs <= oneDayMs) {
    pendingClass = "is-pending-green";
  } else if (elapsedMs <= twoDaysMs) {
    pendingClass = "is-pending-yellow";
  } else {
    pendingClass = "is-pending-red";
  }

  return {
    label: "⏳ Approval Pending: " + duration,
    cls: pendingClass,
    title: "Time pending since request submission"
  };
}
