  var pageEl = root.querySelector("#pkgRequestPagination");
  if (!pageEl) return;

  var total = rows.length;
  var totalPages = Math.ceil(total / state.PER_PAGE);

  if (totalPages <= 1) {
    pageEl.innerHTML = "";
    return;
  }

  pageEl.innerHTML = `
    <div class="pkg-pagination-info">
      Page ${state.currentPage} of ${totalPages}
      <span>${total} requests</span>
    </div>

    <div class="pkg-pagination-actions">
      <button type="button" class="pkg-page-btn" id="pkgPrevPageBtn" ${state.currentPage <= 1 ? "disabled" : ""}>
        ‹ Prev
      </button>
      <button type="button" class="pkg-page-btn" id="pkgNextPageBtn" ${state.currentPage >= totalPages ? "disabled" : ""}>
        Next ›
      </button>
    </div>
  `;

  var prev = root.querySelector("#pkgPrevPageBtn");
  var next = root.querySelector("#pkgNextPageBtn");

  if (prev) {
    prev.addEventListener("click", function () {
      if (state.currentPage <= 1) return;
      state.currentPage--;
      renderAllRequests();
    });
  }

  if (next) {
    next.addEventListener("click", function () {
      if (state.currentPage >= totalPages) return;
      state.currentPage++;
      renderAllRequests();
    });
  }
}

