var P2P_SALES_INVOICE_PRINT_FORMAT =
  "Consultaion Patient Sales Invoice";

/*
 * One P2P detail view uses the linked Sales Invoices in
 * three places: bill buttons, Booked By, and original-plan
 * value calculations. Keep one shared request/cache so a
 * redirected page does not fire the same heavy query three
 * times at once.
 */
var p2pLinkedInvoiceCache = {};
var p2pLinkedInvoicePending = {};

function getP2PLinkedInvoiceCacheKey(doc) {
  var sourcePlans = getP2PSourcePlanList(doc)
    .map(function (planName) {
      return String(planName || "").trim();
    })
    .filter(Boolean)
    .sort();

  return sourcePlans.join("||");
}


function getP2PSalesInvoicePrintUrl(invoiceName) {
  invoiceName = String(invoiceName || "").trim();

  if (!invoiceName) return "";

  return (
    window.location.origin +
    "/printview" +
    "?doctype=" + encodeURIComponent("Sales Invoice") +
    "&name=" + encodeURIComponent(invoiceName) +
    "&format=" + encodeURIComponent(
      P2P_SALES_INVOICE_PRINT_FORMAT
    ) +
    "&no_letterhead=0"
  );
}


function fetchP2PLinkedSalesInvoices(doc, options) {
  doc = doc || {};
  options = options || {};

  var forceReload = options.forceReload === true;

  var sourcePlans = getP2PSourcePlanList(doc);

  sourcePlans = (sourcePlans || [])
    .map(function (planName) {
      return String(planName || "").trim();
    })
    .filter(Boolean);

  if (!sourcePlans.length) {
    return Promise.resolve([]);
  }

  var cacheKey = getP2PLinkedInvoiceCacheKey(doc);

  if (
    !forceReload &&
    cacheKey &&
    Object.prototype.hasOwnProperty.call(
      p2pLinkedInvoiceCache,
      cacheKey
    )
  ) {
    return Promise.resolve(
      p2pLinkedInvoiceCache[cacheKey]
    );
  }

  if (
    !forceReload &&
    cacheKey &&
    p2pLinkedInvoicePending[cacheKey]
  ) {
    return p2pLinkedInvoicePending[cacheKey];
  }

  var requestPromise = new Promise(function (resolve, reject) {
    var settled = false;

    /*
     * Never leave the redirected request permanently showing
     * "Loading linked bill(s)..." when a server callback is
     * delayed or lost.
     */
    var timeoutId = window.setTimeout(function () {
      if (settled) return;
      settled = true;

      reject(
        new Error(
          "Linked Sales Invoice request timed out."
        )
      );
    }, 20000);

    frappe.call({
      method: "frappe.client.get_list",

      args: {
        doctype: "Sales Invoice",

        filters: [
          ["Sales Invoice", "docstatus", "=", 1],
          ["Sales Invoice", "is_return", "=", 0],
          [
            "Sales Invoice",
            "therapy_plan_reference_id",
            "in",
            sourcePlans
          ]
        ],

        fields: [
          "name",
          "posting_date",
          "therapy_plan_reference_id",

          "patient",
          "patient_name",
          "customer",
          "customer_name",

          "custom_referring_name",
          "ref_practitioner",
          "custom_healthcare_practitioner",
          "custom_doctor_name",
          "custom_doctor_id",

          "grand_total",
          "rounded_total",
          "outstanding_amount",
          "status"
        ],

        order_by: "posting_date desc, creation desc",
        limit_page_length: 500
      },

      callback: function (r) {
        if (settled) return;
        settled = true;
        window.clearTimeout(timeoutId);

        var invoices = r.message || [];
        var seen = {};
        var uniqueInvoices = [];

        invoices.forEach(function (invoice) {
          var invoiceName = String(
            invoice.name || ""
          ).trim();

          if (
            !invoiceName ||
            seen[invoiceName]
          ) {
            return;
          }

          seen[invoiceName] = true;
          uniqueInvoices.push(invoice);
        });

        if (cacheKey) {
          p2pLinkedInvoiceCache[cacheKey] =
            uniqueInvoices;
        }

        resolve(uniqueInvoices);
      },

      error: function (error) {
        if (settled) return;
        settled = true;
        window.clearTimeout(timeoutId);

        ("Unable to fetch linked Sales Invoices:", error, void 0);

        reject(
          error ||
          new Error(
            "Unable to fetch linked Sales Invoices."
          )
        );
      }
    });
  });

  if (cacheKey) {
    p2pLinkedInvoicePending[cacheKey] =
      requestPromise;
  }

  requestPromise.then(
    function () {
      if (cacheKey) {
        delete p2pLinkedInvoicePending[cacheKey];
      }
    },
    function () {
      if (cacheKey) {
        delete p2pLinkedInvoicePending[cacheKey];
      }
    }
  );

  return requestPromise;
}


