function p2pPickFirstValue(obj, keys) {
  obj = obj || {};

  for (var i = 0; i < keys.length; i++) {
    var value = obj[keys[i]];
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
    ) {
      return String(value).trim();
    }
  }

  return "";
}

function p2pContainsText(text, pattern) {
  return new RegExp(pattern, "i").test(String(text || ""));
}

function getP2PApprovalMiniFlowStages(doc) {
  doc = doc || {};

  var currentStatus = String(
    getStatus(doc) || ""
  ).trim();

  var displayStatus = String(
    doc.approval_display_status || ""
  ).trim();

  var approvalStage = String(
    doc.approval_stage || ""
  ).trim();

  var finalStatus = String(
    doc.final_approval_status || ""
  ).trim();

  var automationStatus = String(
    doc.automation_status || ""
  ).trim();

  var statusText = [
    currentStatus,
    displayStatus,
    approvalStage,
    finalStatus,
    automationStatus
  ].join(" | ");

  var cmApprovedBy = p2pPickFirstValue(
    doc,
    [
      "approved_by_name",
      "centre_manager_approved_by",
      "branch_manager_approved_by",
      "cm_approved_by",
      "centre_manager_name"
    ]
  );

  var auditApprovedBy = p2pPickFirstValue(
    doc,
    [
      "authorised_name",
      "audit_team_approved_by",
      "audit_approved_by",
      "authorised_by"
    ]
  );

  var cooApprovedBy = p2pPickFirstValue(
    doc,
    [
      "coo_management_name",
      "coo_approved_by",
      "final_approved_by",
      "management_approved_by"
    ]
  );

  var isRejected =
    finalStatus === "Rejected" ||
    approvalStage === "Rejected" ||
    currentStatus === "Rejected" ||
    /Rejected/i.test(displayStatus);

  var rejectionInfo = null;

  if (isRejected) {
    try {
      rejectionInfo =
        getP2PRejectionInfo(doc);
    } catch (error) {
      rejectionInfo = null;
    }
  }

  var rejectedStage = "";

  // Primary detection: use the same function
  // already used by the request-list card.
  if (
    rejectionInfo &&
    rejectionInfo.stage
  ) {
    if (rejectionInfo.stage === "cm") {
      rejectedStage = "cm";
    } else if (
      rejectionInfo.stage === "ops" ||
      rejectionInfo.stage === "audit"
    ) {
      rejectedStage = "audit";
    } else if (
      rejectionInfo.stage === "coo"
    ) {
      rejectedStage = "coo";
    }
  }

  // Fallback for records where the rejection
  // stage is available only in status text.
  if (!rejectedStage && isRejected) {
    if (
      /Centre Manager Rejected/i.test(
        statusText
      )
    ) {
      rejectedStage = "cm";
    } else if (
      /Audit Team Rejected|Operations Head Rejected/i.test(
        statusText
      )
    ) {
      rejectedStage = "audit";
    } else if (
      /COO.*Rejected|Management.*Rejected/i.test(
        statusText
      )
    ) {
      rejectedStage = "coo";
    }
  }

  var rejectedBy =
    rejectionInfo &&
    rejectionInfo.by
      ? String(
          rejectionInfo.by
        ).trim()
      : p2pPickFirstValue(
          doc,
          [
            "rejected_by",
            "rejected_user",
            "modified_by"
          ]
        );

  function stageObj(
    key,
    label,
    actor,
    state
  ) {
    return {
      key: key,
      label: label,
      actor: actor || "",
      state: state || "upcoming"
    };
  }

  var cmState = "upcoming";
  var auditState = "upcoming";
  var cooState = "upcoming";

  if (rejectedStage === "cm") {
    cmState = "rejected";
    auditState = "stopped";
    cooState = "stopped";

  } else if (
    rejectedStage === "audit"
  ) {
    cmState = "approved";
    auditState = "rejected";
    cooState = "stopped";

  } else if (
    rejectedStage === "coo"
  ) {
    cmState = "approved";
    auditState = "approved";
    cooState = "rejected";

  } else if (
    /Centre Manager Approval Pending/i.test(
      statusText
    )
  ) {
    cmState = "pending";
    auditState = "upcoming";
    cooState = "upcoming";

  } else if (
    /Audit Team Approval Pending|Audit Pending|Operations Head Approval Pending/i.test(
      statusText
    )
  ) {
    cmState = "approved";
    auditState = "pending";
    cooState = "upcoming";

  } else if (
    /COO.*Approval Pending|Management.*Approval Pending|Final Approval Pending/i.test(
      statusText
    )
  ) {
    cmState = "approved";
    auditState = "approved";
    cooState = "pending";

  } else if (
    /Process Completed/i.test(
      automationStatus
    ) ||
    finalStatus === "Approved" ||
    approvalStage === "Approved"
  ) {
    cmState = "approved";
    auditState = "approved";
    cooState = "approved";

  } else if (cooApprovedBy) {
    cmState = "approved";
    auditState = "approved";
    cooState = "approved";

  } else if (auditApprovedBy) {
    cmState = "approved";
    auditState = "approved";
    cooState = "pending";

  } else if (cmApprovedBy) {
    cmState = "approved";
    auditState = "pending";
    cooState = "upcoming";

  } else {
    cmState = "pending";
    auditState = "upcoming";
    cooState = "upcoming";
  }

  return [
    stageObj(
      "cm",
      "Centre Manager",
      cmState === "rejected"
        ? rejectedBy
        : cmApprovedBy,
      cmState
    ),

    stageObj(
      "audit",
      "Audit Team",
      auditState === "rejected"
        ? rejectedBy
        : auditApprovedBy,
      auditState
    ),

    stageObj(
      "coo",
      "COO / Management",
      cooState === "rejected"
        ? rejectedBy
        : cooApprovedBy,
      cooState
    )
  ];
}


function renderP2PApprovalMiniFlow(doc) {
  var stages = getP2PApprovalMiniFlowStages(doc);

  return `
