      ${stages.map(function (stage, index) {
        var icon = "•";
        var actorText = "Waiting";

        if (stage.state === "approved") {
          icon = "✓";

          actorText = stage.actor
            ? stage.actor + " · Approved"
            : "Approved";

        } else if (stage.state === "rejected") {
          icon = "✕";

          actorText = stage.actor
            ? stage.actor + " · Rejected"
            : "Rejected";

        } else if (stage.state === "pending") {
          icon = "…";
          actorText = stage.actor
            ? stage.actor + " · Pending"
            : "Pending";

        } else if (
  stage.state === "stopped"
