function getP2POriginalRowPlanName(row, fallbackPlan) {
  row = row || {};

  return String(
    row.therapy_plan ||
    row.seserp_entry ||
    row.ses_erp_entry ||
    row.source_therapy_plan ||
    row.therapy_plan_no ||
    fallbackPlan ||
    "Unmapped Source Plan"
  ).trim();
}

function getP2PSourcePlanList(doc) {
  var rows = doc && doc.complete_package_details ? doc.complete_package_details : [];
  var plans = [];

  rows.forEach(function (row) {
    var plan = getP2POriginalRowPlanName(row, "");

    if (plan && plan !== "Unmapped Source Plan" && plans.indexOf(plan) === -1) {
      plans.push(plan);
    }
  });

  if (!plans.length && doc && doc.source_therapy_plans_text) {
    String(doc.source_therapy_plans_text || "")
      .split(",")
      .map(function (p) {
        return String(p || "").trim();
      })
      .filter(Boolean)
      .forEach(function (p) {
        if (plans.indexOf(p) === -1) plans.push(p);
      });
  }

  if (!plans.length && doc && doc.source_therapy_plan) {
    plans.push(doc.source_therapy_plan);
  }

  return plans;
}


