      ${planNames.map(function (planName, planIndex) {
        var planRows = groups[planName] || [];

        var totalSessionsSum =
          planRows.reduce(function (sum, row) {
            return (
              sum +
              num(
                row.booked_quantity ||
                row.no_of_sessions ||
                row.total_sessions ||
                0
              )
            );
          }, 0);

        var usedSessionsSum =
          planRows.reduce(function (sum, row) {
            return (
              sum +
              num(
                row.availed_quantity ||
                row.sessions_completed ||
                row.used_quantity ||
                row.total_sessions_completed ||
                0
              )
            );
          }, 0);

        var storedPlanBalanceValue =
          planRows.reduce(function (sum, row) {
            return (
              sum +
              num(
                row.balance_quantity_amount ||
                0
              )
            );
          }, 0);

        return `
