                  ${esc(usedSessionsSum)}
                  &nbsp;|&nbsp;

                  Balance Sessions:
                  ${esc(
                    Math.max(
                      totalSessionsSum -
                      usedSessionsSum,
                      0
                    )
                  )}
                </div>
              </div>
            </div>

            <div class="pkg-mini-table-wrap pkg-p2p-original-table-wrap">

              <table class="pkg-mini-table pkg-p2p-original-group-table">

                <colgroup>
                  <col style="width:38%">
                  <col style="width:14%">
                  <col style="width:17%">
