                  <tr>
                    <th>Therapy Type</th>
                    <th>Used / Total</th>
                    <th>Total Value</th>
                    <th>Per Session</th>
                    <th>Balance Value</th>
                  </tr>
                </thead>

                <tbody>

                  ${planRows.map(function (row, rowIndex) {
                    var therapyType =
                      row.complete_package_details_therapy_plans ||
                      row.therapy_type ||
                      row.service_name ||
                      row.package_name ||
                      "—";

                    var totalSessions = num(
                      row.booked_quantity ||
                      row.no_of_sessions ||
                      row.total_sessions ||
                      0
                    );

                    var usedSessions = num(
                      row.availed_quantity ||
                      row.sessions_completed ||
                      row.used_quantity ||
                      row.total_sessions_completed ||
                      0
                    );

                    var balanceSessions = Math.max(
                      totalSessions -
                      usedSessions,
                      0
                    );

                    var storedBalanceValue = num(
                      row.balance_quantity_amount ||
                      0
                    );

                    var initialValuePerSession =
                      balanceSessions > 0
                        ? storedBalanceValue /
                          balanceSessions
                        : 0;

                    var initialTotalValue =
                      initialValuePerSession *
                      totalSessions;

                    return `
                      <tr
                        data-original-plan-index="${planIndex}"
                        data-original-row-index="${rowIndex}"
                      >
