                </tfoot>

              </table>
            </div>
          </div>
        `;
      }).join("")}

    </div>
  `;
}

function hydrateP2POriginalPlanValues(
  doc,
  panel
) {
  if (!doc || !panel) return;

  var requestRows =
    doc.complete_package_details || [];

  if (!requestRows.length) return;

  fetchP2PLinkedSalesInvoices(doc)
    .then(function (invoiceRows) {
      // Fetch complete invoices because get_list
      // does not return the Sales Invoice items table.
      return fetchFullInvoices(
        invoiceRows || []
      );
    })
    .then(function (invoices) {
      invoices = invoices || [];

      var groups = {};

      requestRows.forEach(function (row) {
        var planName =
          getP2POriginalRowPlanName(
            row,
            doc.source_therapy_plan || ""
          );

        if (!groups[planName]) {
          groups[planName] = [];
        }

        groups[planName].push(row);
      });

      var planNames = Object.keys(groups);

      planNames.forEach(function (
        planName,
        planIndex
      ) {
        var planRows =
          groups[planName] || [];

        var normalizedPlanName = String(
          planName || ""
        ).trim();

        var linkedInvoices =
          invoices.filter(function (invoice) {
            var invoicePlanName = String(
              getInvoiceTherapyPlanReference(
                invoice
              ) || ""
            ).trim();

            return (
              invoicePlanName ===
              normalizedPlanName
            );
          });

        var planTotalSessions =
          planRows.reduce(function (sum, row) {
            return (
              sum +
              num(
                row.booked_quantity ||
                row.no_of_sessions ||
                row.total_sessions ||
                0
              )
            );
          }, 0);

        var planPaidAmount =
          linkedInvoices.reduce(function (
            sum,
            invoice
          ) {
            return (
              sum +
              getP2PInvoicePaidAmount(
                invoice
              )
            );
          }, 0);

        var fallbackValuePerSession =
          planTotalSessions > 0
            ? planPaidAmount /
              planTotalSessions
            : 0;

        var planBalanceValue = 0;

        planRows.forEach(function (
          row,
          rowIndex
        ) {
          var therapyType =
            row.complete_package_details_therapy_plans ||
            row.therapy_type ||
            row.service_name ||
            row.package_name ||
            "—";

          var totalSessions = num(
            row.booked_quantity ||
            row.no_of_sessions ||
            row.total_sessions ||
            0
          );

          var usedSessions = num(
            row.availed_quantity ||
            row.sessions_completed ||
            row.used_quantity ||
            row.total_sessions_completed ||
            0
          );

          var balanceSessions = Math.max(
            totalSessions -
            usedSessions,
            0
          );

          var storedBalanceValue = num(
            row.balance_quantity_amount ||
            0
          );

          var paidItemResult =
            getP2PPaidItemAmountForTherapy(
              therapyType,
              linkedInvoices
            );

          var valuePerSession = 0;

          if (
            paidItemResult &&
            paidItemResult.matched &&
            totalSessions > 0
          ) {
            valuePerSession =
              num(
                paidItemResult.amount || 0
              ) / totalSessions;
          } else if (
            fallbackValuePerSession > 0
          ) {
            valuePerSession =
              fallbackValuePerSession;
          } else if (
            balanceSessions > 0 &&
            storedBalanceValue > 0
          ) {
            valuePerSession =
              storedBalanceValue /
              balanceSessions;
          }

          var totalSessionsValue =
            totalSessions *
            valuePerSession;

          var balanceValue =
            balanceSessions *
            valuePerSession;

          planBalanceValue +=
            balanceValue;

          var rowElement =
            panel.querySelector(
              '[data-original-plan-index="' +
              planIndex +
              '"][data-original-row-index="' +
              rowIndex +
              '"]'
            );

          if (!rowElement) return;

          var totalValueElement =
            rowElement.querySelector(
              ".pkg-original-total-value"
            );

          var sessionValueElement =
            rowElement.querySelector(
              ".pkg-original-session-value"
            );

          var balanceValueElement =
            rowElement.querySelector(
              ".pkg-original-balance-value"
            );

          if (totalValueElement) {
            totalValueElement.textContent =
              p2pMoney(
                totalSessionsValue
              );
          }

          if (sessionValueElement) {
            sessionValueElement.textContent =
              p2pMoney(
                valuePerSession
              );
          }

          if (balanceValueElement) {
            balanceValueElement.textContent =
              p2pMoney(
                balanceValue
              );
          }
        });

        var planCard =
          panel.querySelector(
            '.pkg-original-plan-card' +
            '[data-original-plan-index="' +
            planIndex +
            '"]'
          );

        if (!planCard) return;

        var planBalanceElement =
          planCard.querySelector(
            ".pkg-original-plan-balance-total"
          );

        if (planBalanceElement) {
          planBalanceElement.textContent =
            p2pMoney(
              planBalanceValue
            );
        }
      });
    })
    .catch(function (error) {
      ("Unable to calculate original plan values:", error, void 0);
    });
}

var P2P_PACKAGE_VERSION_CHILD_DOCTYPE =
  "Therapy Plan Conversion Snapshot Row";


function getP2PPackageVersionService(row) {
  return String(
    p2pRowValue(row || {}, [
      "therapy_type",
      "converted_package__service_name",
      "service_package_name",
      "service_name",
      "package_name"
    ]) || ""
  ).trim();
}


function getP2PPackageVersionQty(row) {
  return num(
    p2pRowValue(row || {}, [
      "no_of_sessions",
      "converted_quantity",
      "qty",
      "quantity"
    ]) || 0
  );
}


function getP2PPackageVersionCompleted(row) {
  return num(
    p2pRowValue(row || {}, [
      "sessions_completed",
      "completed_sessions",
      "availed_quantity",
      "completed"
    ]) || 0
  );
}


function getP2PPackageVersionAmount(row) {
  return num(
    p2pRowValue(row || {}, [
      "amount",
      "balance_amount",
      "total_amount"
    ]) || 0
  );
}


function getP2PPackageVersionRate(row) {
  row = row || {};

  var savedRate = num(
    p2pRowValue(row, [
      "rate",
      "price",
      "rate_per_session"
    ]) || 0
  );

  if (savedRate > 0) {
    return savedRate;
  }

  var qty = getP2PPackageVersionQty(row);
  var amount = getP2PPackageVersionAmount(row);

  return qty > 0 ? amount / qty : 0;
}


function buildP2PPackageVersionRows(rows) {
  return (rows || [])
    .map(function (row) {
      row = row || {};

      var therapyType =
        getP2PPackageVersionService(row);

      var qty =
        getP2PPackageVersionQty(row);

      var completed =
        getP2PPackageVersionCompleted(row);

      var amount =
        getP2PPackageVersionAmount(row);

      var rate =
        getP2PPackageVersionRate(row);

      if (!therapyType || qty <= 0) {
        return null;
      }

      return {
        doctype: P2P_PACKAGE_VERSION_CHILD_DOCTYPE,

        therapy_type: therapyType,
        no_of_sessions: Math.floor(qty),
        sessions_completed: Math.floor(completed),

        rate: round(rate),
        amount: round(amount),

        source_row_name:
          row.source_row_name ||
          row.name ||
          ""
      };
    })
    .filter(Boolean);
}

function buildP2PActiveConvertedRows(rows) {
  return (rows || [])
    .map(function (row) {
      var therapyType =
        getP2PPackageVersionService(row);

      var qty =
        Math.floor(
          getP2PPackageVersionQty(row)
        );

      var completed =
        Math.floor(
          getP2PPackageVersionCompleted(row)
        );

      var amount =
        round(
          getP2PPackageVersionAmount(row)
        );

      if (!therapyType || qty <= 0) {
        return null;
      }

      var appliedSessions = Math.max(
        qty - completed,
        0
      );

      var rate =
        appliedSessions > 0
          ? amount / appliedSessions
          : 0;

      return {
        doctype: "Conversion Package Details",

        converted_package__service_name: therapyType,
        service_package_name: therapyType,
        therapy_type: therapyType,
        service_name: therapyType,
        package_name: therapyType,

        converted_quantity: qty,
        no_of_sessions: qty,
        quantity: qty,

        completed_sessions: completed,
        sessions_completed: completed,
        availed_quantity: completed,

        applied_sessions: appliedSessions,
        balance_quantity: appliedSessions,

        rate: rate,
        price: rate,

        balance_amount: amount,
        amount: amount,
        total_amount: amount,

        source_row_name:
          row.source_row_name || ""
      };
    })
    .filter(Boolean);
}


function getP2PPackageVersionComparableRows(rows) {
  return buildP2PPackageVersionRows(rows).map(function (row) {
    return {
      therapy_type: String(row.therapy_type || "").trim().toLowerCase(),
      no_of_sessions: Math.floor(num(row.no_of_sessions || 0)),
      sessions_completed: Math.floor(num(row.sessions_completed || 0)),
      amount: round(num(row.amount || 0))
    };
  });
}


function areP2PPackageVersionsDifferent(firstRows, secondRows) {
  var first =
    getP2PPackageVersionComparableRows(firstRows);

  var second =
    getP2PPackageVersionComparableRows(secondRows);

  return JSON.stringify(first) !== JSON.stringify(second);
}


function getP2PBranchRequestedRows(doc) {
  doc = doc || {};

  if (
    Array.isArray(doc.branch_requested_package) &&
    doc.branch_requested_package.length
  ) {
    return doc.branch_requested_package;
  }

  /*
   * Legacy fallback:
   * For records created before package-version history was added,
   * use the current converted table.
   */
  return doc.converted_package__service_name || [];
}


function getP2PAuditApprovedRows(doc) {
  doc = doc || {};

  if (
    Array.isArray(doc.audit_team_requested_package) &&
    doc.audit_team_requested_package.length
  ) {
    return doc.audit_team_requested_package;
  }

  return [];
}


function getP2PCooFinalRows(doc) {
  doc = doc || {};

  if (
    Array.isArray(doc.coo_management_final_package) &&
    doc.coo_management_final_package.length
  ) {
    return doc.coo_management_final_package;
  }

  return [];
}


function getP2PApprovalEditableBaseRows(doc, role) {
  doc = doc || {};

  /*
   * Audit edits a copy of the Branch request.
   */
  if (role === "ops") {
    return getP2PBranchRequestedRows(doc);
  }

  /*
   * COO edits a copy of the Audit-approved package.
   */
  if (role === "coo") {
    var auditRows = getP2PAuditApprovedRows(doc);

    if (auditRows.length) {
      return auditRows;
    }
  }

  return doc.converted_package__service_name || [];
}


