    "therapy_type",
    "service_name",
    "package_name"
  ]);

  var qty = p2pRowValue(r, [
    "converted_quantity",
    "no_of_sessions",
    "qty",
    "quantity"
  ]);

  var amount = p2pRowValue(r, [
    "balance_amount",
    "amount",
    "total_amount"
  ]);

  var completed = p2pRowValue(r, [
    "completed_sessions",
    "sessions_completed",
    "availed_quantity",
    "completed"
  ]);

  completed = p2pCleanApprovalSessionValue(completed || 0, 0);
  qty = p2pCleanApprovalSessionValue(qty || 1, completed);

  return `
    <div
      class="pkg-approval-conv-row"
      data-row-idx="${esc(idx)}"
