          pattern="[0-9]*"
          class="pkg-approval-qty-input"
          value="${esc(qty || 1)}"
          data-min="${esc(completed || 0)}"
        >
        <div class="pkg-mini-help">
          ${completed > 0 ? "Min completed: " + esc(completed) : "Whole number only"}
        </div>
      </div>

      <div>
        <input
          type="text"
