function bindP2PApprovalConvertedTableEvents(panel, doc, role) {
  if (!(role === "ops" || role === "coo")) return;
  if (!panel) return;

  panel.dataset.p2pApprovalEditEnabled = "0";

  var enableBtn = panel.querySelector("#pkgEnableApprovalEditBtn");
  var editArea = panel.querySelector("#pkgApprovalEditArea");

  if (!enableBtn || !editArea) {
    ("P2P approval edit toggle elements not found", {
      enableBtn: !!enableBtn,
      editArea: !!editArea,
      role: role
    }, void 0);
    return;
  }

  if (enableBtn.dataset.bound === "1") return;
  enableBtn.dataset.bound = "1";

  enableBtn.addEventListener("click", function (e) {
    e.preventDefault();
    e.stopPropagation();

    var message =
      "Are you sure you want to edit the final converted package table?\n\n" +
      "The originally submitted final table will remain visible above for comparison.\n\n" +
      "Any change you make will be recorded against your approval.";

    var confirmed = window.confirm(message);

    if (!confirmed) return;

    panel.dataset.p2pApprovalEditEnabled = "1";

    editArea.style.display = "block";
    enableBtn.style.display = "none";

    frappe.show_alert({
      message: "Final table editing enabled for this approval.",
      indicator: "orange"
    });

    bindP2PApprovalRowEvents(panel, doc, role);

    var addBtn = panel.querySelector("#pkgApprovalAddTherapyBtn");

    if (addBtn && addBtn.dataset.bound !== "1") {
      addBtn.dataset.bound = "1";

      addBtn.addEventListener("click", function () {
        addP2PApprovalTherapyRow(panel, doc, role);
      });
    }

    updateP2PApprovalOverrideSummary(panel, doc);

    var tableEditRemarksEl = panel.querySelector("#pkgApprovalTableEditRemarks");
    var tableEditRemarksErrorEl = panel.querySelector("#pkgTableEditRemarksError");

    if (tableEditRemarksEl && tableEditRemarksEl.dataset.bound !== "1") {
      tableEditRemarksEl.dataset.bound = "1";
      tableEditRemarksEl.addEventListener("input", function () {
        tableEditRemarksEl.style.borderColor = "#cbd5e1";
        tableEditRemarksEl.style.background = "#fff";
        if (tableEditRemarksErrorEl) tableEditRemarksErrorEl.textContent = "";
      });
    }
  });
}


function bindP2PApprovalRowEvents(panel, doc, role) {
  var table = panel.querySelector(".pkg-approval-conv-table");
  if (!table) return;

  table.querySelectorAll(".pkg-approval-conv-row").forEach(function (rowEl) {
    if (rowEl.dataset.boundApprovalRow === "1") return;
    rowEl.dataset.boundApprovalRow = "1";

    var serviceInput = rowEl.querySelector(".pkg-approval-service-input");
    var qtyInput = rowEl.querySelector(".pkg-approval-qty-input");
    var amountInput = rowEl.querySelector(".pkg-approval-amount-input");
    var removeBtn = rowEl.querySelector(".pkg-approval-remove-row-btn");
    var dropdown = rowEl.querySelector(".pkg-tp-dropdown");

    if (serviceInput) {
      serviceInput.addEventListener("input", function () {
        rowEl.dataset.therapySelected = "0";
        var q = String(serviceInput.value || "").trim();

        if (q.length < 2) {
          if (dropdown) dropdown.style.display = "none";
          return;
        }

        searchP2PApprovalTherapyType(q, dropdown, serviceInput, rowEl, panel, doc);
      });

      serviceInput.addEventListener("change", function () {
        updateP2PApprovalOverrideSummary(panel, doc);
      });
    }

    if (qtyInput) {
      qtyInput.addEventListener("input", function () {
        var min = num(qtyInput.dataset.min || 0);
        qtyInput.value = p2pCleanApprovalSessionValue(qtyInput.value, min);
        updateP2PApprovalOverrideSummary(panel, doc);
      });

      qtyInput.addEventListener("blur", function () {
        var min = num(qtyInput.dataset.min || 0);
        qtyInput.value = p2pCleanApprovalSessionValue(qtyInput.value, min || 1);
        updateP2PApprovalOverrideSummary(panel, doc);
      });
    }

    if (amountInput) {
      amountInput.addEventListener("input", function () {
        amountInput.value = p2pCleanApprovalAmountValue(amountInput.value);
        updateP2PApprovalOverrideSummary(panel, doc);
      });

      amountInput.addEventListener("blur", function () {
        amountInput.value = round(num(amountInput.value || 0));
        updateP2PApprovalOverrideSummary(panel, doc);
      });
    }

    if (removeBtn) {
      removeBtn.addEventListener("click", function () {
        rowEl.remove();
        updateP2PApprovalOverrideSummary(panel, doc);
      });
    }
  });
}


function addP2PApprovalTherapyRow(panel, doc, role) {
  var body = panel.querySelector(".pkg-approval-conv-body");

  if (!body) return;

  var idx = Date.now();

  var rowEl = document.createElement("div");
  rowEl.innerHTML = buildP2PApprovalEditableRow({
    converted_package__service_name: "",
    converted_quantity: 1,
    balance_amount: 0,
    completed_sessions: 0
  }, idx);

  var row = rowEl.firstElementChild;
  body.appendChild(row);

  bindP2PApprovalRowEvents(panel, doc, role);

  var input = row.querySelector(".pkg-approval-service-input");
  if (input) input.focus();

  updateP2PApprovalOverrideSummary(panel, doc);
}


function searchP2PApprovalTherapyType(q, dropdown, input, rowEl, panel, doc) {
  if (!dropdown || !input || !rowEl) return;

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Therapy Type",
      fields: ["name"],
      filters: [["Therapy Type", "name", "like", "%" + q + "%"]],
      order_by: "name asc",
      limit_page_length: 20
    },
    callback: function (r) {
      var rows = r.message || [];

      if (!rows.length) {
        dropdown.innerHTML =
          '<div class="pkg-tp-dd-item pkg-tp-dd-empty">No results for "' + esc(q) + '"</div>';
        dropdown.style.display = "block";
        return;
      }

      dropdown.innerHTML = rows.map(function (t) {
        return '<div class="pkg-tp-dd-item" data-val="' + esc(t.name) + '">' + esc(t.name) + '</div>';
      }).join("");

      dropdown.style.display = "block";

      dropdown.querySelectorAll(".pkg-tp-dd-item[data-val]").forEach(function (item) {
        item.addEventListener("click", function () {
          var selectedName = item.dataset.val || "";

          input.value = selectedName;
          rowEl.dataset.therapySelected = "1";
          dropdown.style.display = "none";

          fetchP2PApprovalTherapyRate(selectedName, rowEl, panel, doc);
        });
      });
    },
    error: function () {
      dropdown.innerHTML = '<div class="pkg-tp-dd-item pkg-tp-dd-empty">Search failed</div>';
      dropdown.style.display = "block";
    }
  });
}


function fetchP2PApprovalTherapyRate(therapyName, rowEl, panel, doc) {
  if (!therapyName || !rowEl) return;

  var amountInput = rowEl.querySelector(".pkg-approval-amount-input");
  var qtyInput = rowEl.querySelector(".pkg-approval-qty-input");

  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: "Therapy Type",
      name: therapyName
    },
    callback: function (r) {
      var t = r.message || {};

      var rate = num(
        t.rate ||
        t.minimum_price ||
        t.custom_min_amount ||
        t.custom_plan_amount ||
        0
      );

      var qty = num(qtyInput ? qtyInput.value : 1);

      if (amountInput && rate > 0) {
        amountInput.value = round(rate * qty);
      }

      updateP2PApprovalOverrideSummary(panel, doc);
    }
  });
}


function p2pCleanApprovalSessionValue(value, minValue) {
  value = String(value == null ? "" : value);

  // Only digits. This blocks -1, 000.3, 5.5, spaces, symbols.
  value = value.replace(/[^\d]/g, "");

  // Remove leading zeros.
  value = value.replace(/^0+/, "");

  if (!value) value = "0";

  var n = parseInt(value, 10);

  if (isNaN(n)) n = 0;

  minValue = num(minValue || 0);

  if (minValue > 0 && n < minValue) {
    n = minValue;
  }

  return String(n);
}


function p2pCleanApprovalAmountValue(value) {
  value = String(value == null ? "" : value);

  // Block negative and alphabets. Allow only one decimal.
  value = value.replace(/[^\d.]/g, "");

  var parts = value.split(".");
  var whole = parts[0] || "";
  var decimal = parts.length > 1 ? parts.slice(1).join("") : "";

  whole = whole.replace(/^0+(?=\d)/, "");

  if (decimal.length > 2) {
    decimal = decimal.slice(0, 2);
  }

  if (parts.length > 1) {
    return whole + "." + decimal;
  }

  return whole;
}


function updateP2PApprovalOverrideSummary(panel, doc) {
  if (!panel || !doc) return;

  var total = 0;

  panel.querySelectorAll(".pkg-approval-amount-input").forEach(function (input) {
    total += num(input.value || 0);
  });

  var availableValue = num(doc.current_package__residual__balance_value_rs || 0);
  var overrideAmount = Math.max(total - availableValue, 0);

  var totalEl = panel.querySelector("#pkgApprovalEditedTotal");
  var overrideEl = panel.querySelector("#pkgApprovalOverrideAmount");
  var bannerEl = panel.querySelector("#pkgApprovalOverrideBanner");

  if (totalEl) {
    totalEl.textContent = "₹" + round(total).toLocaleString("en-IN");
  }

  if (overrideEl) {
    overrideEl.textContent = "₹" + round(overrideAmount).toLocaleString("en-IN");
    overrideEl.style.color = overrideAmount > 0 ? "#C00000" : "#1E7A34";
  }

  if (bannerEl) {
    bannerEl.style.display = overrideAmount > 0 ? "block" : "none";
  }
}


function collectP2PApprovalConvertedTable(panel, doc, role) {
  var result = {
    ok: true,
    message: "",
    rows: [],
    total: 0,
    overrideAmount: 0,
    changed: false
  };

  var editEnabled =
    panel &&
    panel.dataset &&
    panel.dataset.p2pApprovalEditEnabled === "1";

  // If edit was not intentionally enabled, keep the originally submitted table.
  if (!(role === "ops" || role === "coo") || !editEnabled) {
  var baseRows =
    getP2PApprovalEditableBaseRows(
      doc,
      role
    );

  result.rows = baseRows || [];

  result.total = round(
    result.rows.reduce(function (sum, row) {
      return (
        sum +
        getP2PPackageVersionAmount(row)
      );
    }, 0)
  );

  result.overrideAmount = Math.max(
    result.total -
      num(
        doc.current_package__residual__balance_value_rs ||
        0
      ),
    0
  );

  return result;
}

    var table = panel ? panel.querySelector(".pkg-approval-conv-table") : null;

    if (!table) {
      result.ok = false;
      result.message = "Editable converted package table not found.";
      return result;
    }

    var trs = table.querySelectorAll(".pkg-approval-conv-row");

    if (!trs.length) {
        result.ok = false;
        result.message = "Converted package table must have at least one therapy row.";
        return result;
      }

  var seen = {};

  trs.forEach(function (tr, idx) {
    if (!result.ok) return;

    var serviceInput = tr.querySelector(".pkg-approval-service-input");
    var qtyInput = tr.querySelector(".pkg-approval-qty-input");
    var amountInput = tr.querySelector(".pkg-approval-amount-input");

    var service = serviceInput ? String(serviceInput.value || "").trim() : "";
    var qtyText = qtyInput ? String(qtyInput.value || "").trim() : "";
    var amountText = amountInput ? String(amountInput.value || "").trim() : "";

    var completed = num(tr.dataset.completed || 0);
    var qty = num(qtyText || 0);
    var amount = num(amountText || 0);

    if (!service) {
      result.ok = false;
      result.message = "Row " + (idx + 1) + ": Therapy Type is required.";
      if (serviceInput) serviceInput.focus();
      return;
    }

    if (!/^[1-9]\d*$/.test(qtyText)) {
      result.ok = false;
      result.message = "Row " + (idx + 1) + ": Sessions must be a whole number greater than 0.";
      if (qtyInput) qtyInput.focus();
      return;
    }

    if (qty < completed) {
      result.ok = false;
      result.message =
        "Row " + (idx + 1) +
        ": Sessions cannot be below completed sessions (" + completed + ").";
      if (qtyInput) qtyInput.focus();
      return;
    }

    if (amountText === "" || amount < 0) {
      result.ok = false;
      result.message = "Row " + (idx + 1) + ": Amount must be valid and cannot be negative.";
      if (amountInput) amountInput.focus();
      return;
    }

    var key = p2pTherapyKey(service);

    if (seen[key]) {
      result.ok = false;
      result.message = "Duplicate Therapy Type found: " + service;
      if (serviceInput) serviceInput.focus();
      return;
    }

    seen[key] = true;

    var originalService = String(tr.dataset.originalService || "").trim();
    var originalQty = num(tr.dataset.originalQty || 0);
    var originalAmount = num(tr.dataset.originalAmount || 0);

    if (
      service !== originalService ||
      round(qty) !== round(originalQty) ||
      round(amount) !== round(originalAmount)
    ) {
      result.changed = true;
    }

    var appliedSessions = Math.max(qty - completed, 0);
    var rate = appliedSessions > 0 ? amount / appliedSessions : 0;

    result.total += amount;

    result.rows.push({
      doctype: "Conversion Package Details",
      name: tr.dataset.childName || undefined,

      converted_package__service_name: service,
      service_package_name: service,
      therapy_type: service,
      service_name: service,
      package_name: service,

      converted_quantity: qty,
      no_of_sessions: qty,
      quantity: qty,

      completed_sessions: completed,
      sessions_completed: completed,
      availed_quantity: completed,

      applied_sessions: appliedSessions,
      balance_quantity: appliedSessions,

      rate: rate,
      price: rate,

      balance_amount: amount,
      amount: amount,
      total_amount: amount,

      source_row_name: tr.dataset.sourceRowName || "",
      source_plan: tr.dataset.sourcePlan || "",
      is_protected: tr.dataset.isProtected || 0
    });
  });

  result.total = round(result.total);
  result.overrideAmount = Math.max(
    result.total - num(doc.current_package__residual__balance_value_rs || 0),
    0
  );

  return result;
}






