  function getP2PRejectionInfo(doc) {
  doc = doc || {};

  var displayStatus = String(doc.approval_display_status || "");

  var stage = "";
  var stageLabel = "Approver";
  var by = "";
  var remarks = "";
  var time = doc.modified || "";

  if (displayStatus.indexOf("Centre Manager Rejected") !== -1) {
    stage = "cm";
  } else if (displayStatus.indexOf("Audit Team Rejected") !== -1) {
    stage = "ops";
  } else if (displayStatus.indexOf("COO / Management Rejected") !== -1) {
    stage = "coo";
  }

  // Fallback for old records where approval_display_status was only "Rejected / Skipped"
  if (!stage) {
    if (doc.coo_management_name || doc.coo_management_date || doc.coo_management_remarks) {
      stage = "coo";
    } else if (doc.authorised_name || doc.authorised_date || doc.operations_final_remarks || doc.authorised_remarks) {
      stage = "ops";
    } else if (doc.approved_by_name || doc.approved_date || doc.centre_manager_remarks || doc.approved_remarks) {
      stage = "cm";
    }
  }

  if (stage === "cm") {
    stageLabel = "Centre Manager";
    by = doc.approved_by_name || "";
    remarks = doc.centre_manager_remarks || doc.approved_remarks || "";
    time = doc.approved_date || doc.modified || "";
  } else if (stage === "ops") {
    stageLabel = "Audit Team";
    by = doc.authorised_name || "";
    remarks = doc.operations_final_remarks || doc.authorised_remarks || "";
    time = doc.authorised_date || doc.modified || "";
  } else if (stage === "coo") {
    stageLabel = "COO / Management";
    by = doc.coo_management_name || "";
    remarks = doc.coo_management_remarks || "";
    time = doc.coo_management_date || doc.modified || "";
  }

  return {
    stage: stage,
    stageLabel: stageLabel,
    by: by || "Approver",
    remarks: remarks || "",
    time: time || doc.modified || ""
  };
}

function getP2PTimelineActionLabel(entry) {
  entry = entry || {};

  if (entry.action) {
    return String(entry.action || "").trim();
  }

  var title = String(entry.title || "");

  if (/Rejected/i.test(title)) {
    return "Rejected";
  }

  if (/Approved|Authorised/i.test(title)) {
    return "Approved";
  }

  if (/Request Submitted/i.test(title)) {
    return "Submitted";
  }

  if (/Process Completed/i.test(title)) {
    return "Completed";
  }

  if (/Processing/i.test(title)) {
    return "Processing";
  }

  if (/Automation Failed/i.test(title)) {
    return "Failed";
  }

  return "";
}

function getP2PTimelineActionClass(action) {
  action = String(action || "");

  if (/Rejected|Failed/i.test(action)) {
    return "is-rejected";
  }

  if (/Approved|Authorised|Completed/i.test(action)) {
    return "is-approved";
  }

  if (/Submitted/i.test(action)) {
    return "is-submitted";
  }

  if (/Processing/i.test(action)) {
    return "is-processing";
  }

  return "";
}

/* ============================================================
   APPROVAL / REJECTION TIME TAKEN
   ============================================================ */

function getP2PActionTakenDuration(startValue, endValue) {
  var startDate = p2pParseDateTime(startValue);
  var endDate = p2pParseDateTime(endValue);

  if (!startDate || !endDate) {
    return "";
  }

  var elapsedMs =
    endDate.getTime() -
    startDate.getTime();

  if (
    !Number.isFinite(elapsedMs) ||
    elapsedMs < 0
  ) {
    return "";
  }

  return p2pFormatDuration(elapsedMs);
}


function getP2PApprovalStageStartTime(doc, stage) {
  doc = doc || {};
  stage = String(stage || "")
    .trim()
    .toLowerCase();

  /*
   * Centre Manager pending time starts
   * when the request was submitted.
   */
  if (stage === "cm") {
    return (
      doc.creation ||
      doc.date ||
      ""
    );
  }

  /*
   * Audit Team pending time starts
   * when Centre Manager approved.
   */
  if (
    stage === "ops" ||
    stage === "audit"
  ) {
    return doc.approved_date || "";
  }

  /*
   * COO pending time starts
   * when Audit Team approved.
   */
  if (stage === "coo") {
    return doc.authorised_date || "";
  }

  return "";
}


function loadTimeline(docname, container) {
  if (!container) return;

  container.innerHTML =
    '<div style="color:#8C8C8C;font-size:11px;padding:6px">Loading...</div>';

  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: DOCTYPE,
      name: docname
    },
    callback: function (r) {
      if (!r || !r.message) {
        container.innerHTML =
          '<div style="color:#C00000;font-size:12px">Could not load record.</div>';
        return;
      }

      var doc = r.message;

      var autoStatus = String(doc.automation_status || "");
      var finalStatus = String(doc.final_approval_status || "");
      var approvalStage = String(doc.approval_stage || "");
      var displayStatus = String(doc.approval_display_status || "");

      var finalApproved =
        finalStatus === "Approved" ||
        approvalStage === STAGE.APPROVED ||
        approvalStage === "Approved";

      var rejected =
        finalStatus === "Rejected" ||
        approvalStage === STAGE.REJECTED ||
        approvalStage === "Rejected";

        var rejectionInfo = rejected ? getP2PRejectionInfo(doc) : null;

      var processCompleted =
        autoStatus === "Process Completed" ||
        Number(doc.package_conversion_applied || 0) === 1;

      var isProcessing =
        autoStatus === "Processing" ||
        displayStatus.indexOf("Processing") !== -1;

      var isFailed =
        autoStatus === "Failed" ||
        displayStatus.indexOf("Failed") !== -1;

      var entries = [];

      // -------------------------------------------------------
      // Converted package summary
      // -------------------------------------------------------
      var newTypes = (doc.converted_package__service_name || [])
        .map(function (row) {
          var service =
            row.converted_package__service_name ||
            row.service_package_name ||
            row.therapy_type ||
            row.service_name ||
            row.package_name ||
            "-";

          var qty =
            row.converted_quantity ||
            row.no_of_sessions ||
            row.qty ||
            row.quantity ||
            0;

          return service + " x" + qty;
        })
        .join(", ") || "—";

      var newAmount = round(num(doc.new_package_total_price_rs || 0));

      // -------------------------------------------------------
      // 1. Request Submitted
      // -------------------------------------------------------
      entries.push({
        icon: "📋",
        color: "#0D2B4E",
        title: "Request Submitted",
        action: "Submitted",
        desc:
          "Source: " +
          (
              doc.source_therapy_plans_text ||
              doc.source_therapy_plan ||
              getP2PSourcePlanList(doc).join(", ") ||
              "—"
            ) +
          " → New: " +
          newTypes +
          " | ₹" +
          newAmount.toLocaleString("en-IN"),
        by: doc.owner || "Staff",
        time: doc.creation || doc.date || doc.modified
      });

      // -------------------------------------------------------
      // 2. Centre Manager Approval
      // -------------------------------------------------------
      if ((!rejected || !rejectionInfo || rejectionInfo.stage !== "cm") && (doc.approved_date || doc.approved_by_name)) {
        entries.push({
          icon: "🏢",
          color: "#1E7A34",

          title:
            "Centre Manager — Approved" +
            (
              doc.approved_by_name
                ? " by " + doc.approved_by_name
                : ""
            ),

          action: "Approved",

          desc:
            doc.centre_manager_remarks ||
            doc.approved_remarks ||
            "",

          by:
            doc.approved_by_name ||
            "Centre Manager",

          time:
            doc.approved_date ||
            doc.modified,

          taken:
            getP2PActionTakenDuration(
              getP2PApprovalStageStartTime(
                doc,
                "cm"
              ),
              doc.approved_date
            ),

          takenFor: "approval"
        });
      }

      // -------------------------------------------------------
      // 3. Operations Head Approval
      // -------------------------------------------------------
      if ((!rejected || !rejectionInfo || rejectionInfo.stage !== "ops") && (doc.authorised_date || doc.authorised_name)) {
        entries.push({
          icon: "✅",
          color: "#1E7A34",

          title:
            "Audit Team — Approved" +
            (
              doc.authorised_name
                ? " by " + doc.authorised_name
                : ""
            ),

          action: "Approved",

          desc:
            doc.operations_final_remarks ||
            doc.authorised_remarks ||
            "",

          by:
            doc.authorised_name ||
            "Audit Team",

          time:
            doc.authorised_date ||
            doc.modified,

          taken:
            getP2PActionTakenDuration(
              getP2PApprovalStageStartTime(
                doc,
                "ops"
              ),
              doc.authorised_date
            ),

          takenFor: "approval"
        });
      }

      // -------------------------------------------------------
      // 4. COO / Management Approval
      // IMPORTANT:
      // Show this when final approval is completed.
      // This prevents old "Awaiting COO" from showing after COO approval.
      // -------------------------------------------------------
      if ((!rejected || !rejectionInfo || rejectionInfo.stage !== "coo") && (doc.coo_management_date || doc.coo_management_name || finalApproved)) {
        entries.push({
          icon: "👑",
          color: "#1E7A34",

          title:
            "COO / Management — Approved" +
            (
              doc.coo_management_name
                ? " by " +
                  doc.coo_management_name
                : ""
            ),

          action: "Approved",

          desc:
            doc.coo_management_remarks ||
            "",

          by:
            doc.coo_management_name ||
            "COO / Management",

          time:
            doc.coo_management_date ||
            doc.modified,

          taken:
            getP2PActionTakenDuration(
              getP2PApprovalStageStartTime(
                doc,
                "coo"
              ),
              doc.coo_management_date
            ),

          takenFor: "approval"
        });
      }

      // -------------------------------------------------------
      // 5. Automation / Final State
      // -------------------------------------------------------
      if (processCompleted) {
        var completedLog = String(doc.package_conversion_log || "")
          .replace(/[\r\n][\s\S]*/, "");

        entries.push({
          icon: "🏁",
          color: "#0D2B4E",
          title: "Process Completed",
          desc: completedLog || "Therapy Plan update completed successfully.",
          by: "System",
          time: doc.modified
        });
      } else if (isProcessing) {
        var processingLog = String(doc.package_conversion_log || "")
          .replace(/[\r\n][\s\S]*/, "");

        entries.push({
          icon: "⚙️",
          color: "#B8860B",
          title: "Processing Therapy Plan Update",
          desc: processingLog || "Automation is updating the Therapy Plan.",
          by: "System",
          time: doc.modified
        });
      } else if (isFailed) {
        var failedLog = String(doc.package_conversion_log || "")
          .replace(/[\r\n][\s\S]*/, "");

        entries.push({
          icon: "⚠️",
          color: "#C00000",
          title: "Automation Failed",
          desc: failedLog || "Therapy Plan update failed. Please check server logs.",
          by: "System",
          time: doc.modified
        });
      } else if (rejected) {
        var rj = rejectionInfo || getP2PRejectionInfo(doc);

      entries.push({
  icon: "❌",
  color: "#C00000",

  title:
    rj.stageLabel +
    " — Rejected" +
    (
      rj.by
        ? " by " + rj.by
        : ""
    ),

  action: "Rejected",

  desc:
    rj.remarks ||
    "",

  by:
    rj.by ||
    "Approver",

  time:
    rj.time ||
    doc.modified,

  taken:
    getP2PActionTakenDuration(
      getP2PApprovalStageStartTime(
        doc,
        rj.stage
      ),
      rj.time
    ),

  takenFor: "rejection"
});
    } else if (finalApproved) {
        entries.push({
          icon: "⏳",
          color: "#B8860B",
          title: "Waiting for Therapy Plan Update",
          desc: "Final approval is completed. Automation will update the Therapy Plan.",
          by: "System",
          time: doc.modified
        });
      } else if (approvalStage === STAGE.COO) {
        entries.push({
          icon: "⏳",
          color: "#B8860B",
          title: "Awaiting: COO / Management Approval Pending",
          desc: "",
          by: "System",
          time: doc.modified
        });
      } else if (approvalStage === STAGE.OPS) {
        entries.push({
          icon: "⏳",
          color: "#B8860B",
          title: "Awaiting: Audit Team Approval Pending",
          desc: "",
          by: "System",
          time: doc.modified
        });
      } else if (approvalStage === STAGE.CM) {
        entries.push({
          icon: "⏳",
          color: "#B8860B",
          title: "Awaiting: Centre Manager Approval Pending",
          desc: "",
          by: "System",
          time: doc.modified
        });
      } else if (approvalStage) {
        entries.push({
          icon: "⏳",
          color: "#B8860B",
          title: "Awaiting: " + approvalStage,
          desc: "",
          by: "System",
          time: doc.modified
        });
      }

      if (!entries.length) {
        container.innerHTML =
          '<div style="color:#8C8C8C;font-size:12px;padding:8px">No activity yet.</div>';
        return;
      }

      // -------------------------------------------------------
      // Render timeline
      // -------------------------------------------------------
      container.innerHTML =
        '<div class="pkg-timeline">' +
        entries
          .map(function (e) {
            return (
              '<div class="pkg-timeline-item">' +
                '<div class="pkg-timeline-dot" style="background:' + esc(e.color || "#0D2B4E") + ';"></div>' +
                '<div class="pkg-timeline-content">' +
                  '<div class="pkg-timeline-title" style="color:' + esc(e.color || "#0D2B4E") + ';">' +
                      '<span style="margin-right:6px">' + esc(e.icon || "•") + '</span>' +
                      esc(p2pDisplayText(e.title || "")) +
                    '</div>' +
                    (e.desc ? p2pTimelineDescriptionHtml(e) : "") +
                    '<div class="pkg-timeline-by">' +
                      '<span class="pkg-timeline-person">' +
                        esc(p2pDisplayText(e.by || "System")) +
                      '</span>' +
                      (
                        getP2PTimelineActionLabel(e)
                          ? ' <span class="pkg-timeline-action ' +
                              esc(getP2PTimelineActionClass(getP2PTimelineActionLabel(e))) +
                            '">' +
                              esc(getP2PTimelineActionLabel(e)) +
                            '</span>'
                          : ''
                      ) +
                      ' <span class="pkg-timeline-sep">·</span> ' +
                      '<span class="pkg-timeline-time-text">' +
                          esc(fmtDateTime(e.time || "")) +
                        '</span>' +

                        (
  e.taken
    ? (
        ' <span class="pkg-timeline-taken ' +
          (
            e.takenFor === "rejection"
              ? "is-rejection"
              : "is-approval"
          ) +
        '">' +
          '[taken ' +
          esc(e.taken) +
          ' for ' +
          (
            e.takenFor === "rejection"
              ? "rejection"
              : "approval"
          ) +
          ']' +
        '</span>'
      )
    : ""
) +

'</div>' +
'</div>' +
'</div>'
            );
          })
          .join("") +
        '</div>';
    },
    error: function (err) {
      ("P2P timeline load failed:", err, void 0);

      container.innerHTML =
        '<div style="color:#C00000;font-size:12px;padding:8px">' +
        'Failed to load approval timeline. Please refresh and try again.' +
        '</div>';
    }
  });
}

  function refreshApprovalTimelineAfterSave(docname) {
  var approvalPanel = root.querySelector("#pkgApprovalDetail");
  var timelineBox = approvalPanel
    ? approvalPanel.querySelector(".pkg-ad-tl-container[data-doc]")
    : null;

  if (timelineBox) {
    loadTimeline(docname, timelineBox);
  }

  // Run one delayed refresh also because After Save automation may update status after the first save response
  setTimeout(function () {
    var panelAgain = root.querySelector("#pkgApprovalDetail");
    var timelineAgain = panelAgain
      ? panelAgain.querySelector(".pkg-ad-tl-container[data-doc]")
      : null;

    if (timelineAgain) {
      loadTimeline(docname, timelineAgain);
    }

    loadAllRequests(function () {
      updateApprovalBadge();
    });
  }, 1500);
}

