var p2pApprovalRefreshSequence = 0;

function refreshP2PApprovalDashboard(options) {
  options = options || {};

  var currentSequence =
    ++p2pApprovalRefreshSequence;

  var refreshBtn =
    root.querySelector(
      "#pkgRefreshApprovalBtn"
    );

  var listEl =
    root.querySelector(
      "#pkgApprovalList"
    );

  var detailEl =
    root.querySelector(
      "#pkgApprovalDetail"
    );

  if (options.resetPage !== false) {
    state.approvalPage = 1;
  }

  if (
    options.showLoading !== false &&
    listEl
  ) {
    listEl.innerHTML = `
      <div
        class="pkg-approval-loading"
        style="
          text-align:center;
          color:#64748B;
          padding:30px 15px;
          font-size:12px;
          font-weight:600;
        "
      >
        Loading approval requests...
      </div>
    `;
  }

  if (
    options.clearDetail !== false &&
    detailEl
  ) {
    detailEl.innerHTML = `
      <div
        class="pkg-detail-empty"
        style="
          text-align:center;
          color:#8C8C8C;
          padding:40px;
        "
      >
        Select a request to view approval details.
      </div>
    `;
  }

  if (refreshBtn) {
    refreshBtn.disabled = true;
    refreshBtn.dataset.originalText =
      refreshBtn.dataset.originalText ||
      refreshBtn.innerHTML;

    refreshBtn.innerHTML =
      "Loading...";
  }

  loadAllRequests(function () {
    /*
     * Ignore an older response when another role
     * change or refresh happened afterward.
     */
    if (
      currentSequence !==
      p2pApprovalRefreshSequence
    ) {
      return;
    }

    if (refreshBtn) {
      refreshBtn.disabled = false;
      refreshBtn.innerHTML =
        refreshBtn.dataset.originalText ||
        "&#9654; Refresh";
    }

    renderApprovalDash();
  });
}

