function parseReportViewRows(message) {
  var payload = message && message.message ? message.message : (message || {});
  var keys = Array.isArray(payload.keys) ? payload.keys : [];
  var values = payload.values;

  if (!Array.isArray(values)) {
    if (values && typeof values === "object") {
      values = Object.keys(values).map(function (key) {
        return values[key];
      });
    } else if (Array.isArray(payload)) {
      values = payload;
    } else {
      values = [];
    }
  }

  return values.map(function (row) {
    if (row && !Array.isArray(row) && typeof row === "object") {
      return row;
    }

    var obj = {};

    keys.forEach(function (key, idx) {
      obj[key] = Array.isArray(row) ? row[idx] : undefined;
    });

    return obj;
  });
}

function searchCentreManagerEmployees(q, branch, resultBox, approverEl) {
  if (!branch) {
    resultBox.innerHTML =
      '<div class="pkg-ac-item">' +
      '<span style="color:#C00000;font-weight:700">Request branch is missing. Cannot filter Centre Manager employees.</span>' +
      '</div>';
    resultBox.classList.add("show");
    return;
  }

  var filters = [
    ["Employee", "status", "=", "Active"],
    ["Employee", "designation", "in", CM_APPROVER_DESIGNATIONS],
    ["Employee", "branch", "=", branch]
  ];

  if (q) {
    filters.push(["Employee", "employee_name", "like", "%" + q + "%"]);
  }

  resultBox.innerHTML =
    '<div class="pkg-ac-item"><div class="pkg-ac-sub">Searching active CM / ACM employees in ' +
    esc(branch) +
    '...</div></div>';
  resultBox.classList.add("show");

  frappe.call({
    method: "frappe.desk.reportview.get",
    args: {
      doctype: "Employee",
      fields: [
        "`tabEmployee`.`name`",
        "`tabEmployee`.`employee_name`",
        "`tabEmployee`.`status`",
        "`tabEmployee`.`department`",
        "`tabEmployee`.`designation`",
        "`tabEmployee`.`branch`"
      ],
      filters: filters,
      order_by: "`tabEmployee`.`employee_name` asc",
      start: 0,
      page_length: 50,
      view: "List",
      group_by: null,
      with_comment_count: 0
    },
    callback: function (r) {
      var rows = parseReportViewRows(r.message || {});

      rows = rows.filter(function (e) {
        return String(e.status || "") === "Active"
          && CM_APPROVER_DESIGNATIONS.indexOf(String(e.designation || "")) !== -1
          && String(e.branch || "") === branch;
      });

      if (!rows.length) {
        resultBox.innerHTML =
          '<div class="pkg-ac-item">' +
          '<span class="pkg-ac-sub">No active ACM / CM employees found for branch: <b>' +
          esc(branch) +
          '</b></span>' +
          '</div>';
        resultBox.classList.add("show");
        return;
      }

      resultBox.innerHTML = rows.map(function (e) {
        var label = e.employee_name || e.name || "";
        var sub = [
          e.designation || "",
          e.branch || "",
          e.name || ""
        ].filter(Boolean).join(" · ");

        return ''
          + '<div class="pkg-ac-item" data-name="' + esc(label) + '" data-emp="' + esc(e.name || "") + '">'
          + '<div class="pkg-ac-name">' + esc(label) + '</div>'
          + '<div class="pkg-ac-sub">' + esc(sub) + '</div>'
          + '</div>';
      }).join("");

      resultBox.classList.add("show");

      resultBox.querySelectorAll(".pkg-ac-item[data-name]").forEach(function (item) {
        item.addEventListener("click", function () {
          var selectedName = String(item.dataset.name || "").trim();
          var selectedEmployeeId = String(item.dataset.emp || "").trim();

          approverEl.value = selectedName;
          approverEl.dataset.employeeId = selectedEmployeeId;
          approverEl.dataset.approverSelected = "1";
          approverEl.readOnly = true;
          approverEl.classList.add("pkg-search-locked");

          var approvalDetailPanel =
            approverEl.closest("#pkgApprovalDetail") ||
            approverEl.closest(".pkg-detail-panel");

          if (approvalDetailPanel && approvalDetailPanel.dataset) {
            approvalDetailPanel.dataset.cmApproverName = selectedName;
            approvalDetailPanel.dataset.cmApproverEmployeeId = selectedEmployeeId;
          }

          var actionStatus = approvalDetailPanel
            ? approvalDetailPanel.querySelector("#pkgApprovalActionStatus")
            : null;

          if (actionStatus) {
            actionStatus.textContent = "";
            actionStatus.style.color = "";
          }

          resultBox.classList.remove("show");
          resultBox.innerHTML = "";
        });
      });
    },
    error: function () {
      resultBox.innerHTML =
        '<div class="pkg-ac-item">' +
        '<span style="color:#C00000">Could not load ACM / CM employees.</span>' +
        '</div>';
      resultBox.classList.add("show");
    }
  });
}

