function getP2PCompactCategoryLabel(row) {
  row = row || {};

  var fullCategory = "";

  if (typeof getP2PApprovalTargetCategoryFullName === "function") {
    fullCategory = getP2PApprovalTargetCategoryFullName(row);
  }

  var label = p2pCleanCategoryLabel(
    fullCategory ||
    row.target_category ||
    row.shift_client_to_category ||
    row.conversion_category ||
    row.new_category ||
    row.category ||
    ""
  );

  if (label) return label;

  if (num(row.skin || 0)) return "Skin";
  if (num(row.hair || 0)) return "Hair";
  if (num(row.laser || 0)) return "Laser";
  if (num(row.slimming || 0)) return "Slimming";
  if (num(row.cs || 0)) return "LifeRise";
  if (num(row.ht || 0)) return "HT";

  return "";
}

function findP2PApprovalCategoryChip(docname) {
  var chips = root.querySelectorAll(".pkg-approval-category-chip[data-p2p-category-doc]");

  for (var i = 0; i < chips.length; i++) {
    if (chips[i].getAttribute("data-p2p-category-doc") === docname) {
      return chips[i];
    }
  }

  return null;
}

function hydrateP2PApprovalCategoryChips(rows) {
  (rows || []).forEach(function (row) {
    var docname = row.name || "";
    if (!docname) return;

    // Already available from get_list, no need to fetch full doc.
    if (getP2PCompactCategoryLabel(row)) return;

    frappe.call({
      method: "frappe.client.get",
      args: {
        doctype: DOCTYPE,
        name: docname
      },
      callback: function (r) {
        var fullDoc = r.message || {};
        var category = getP2PCompactCategoryLabel(fullDoc);

        if (!category) return;

        var chip = findP2PApprovalCategoryChip(docname);

        if (chip) {
          chip.textContent = category;
          chip.style.display = "inline-flex";
        }
      }
    });
  });
}


function getP2PCompactSourcePlan(row) {
