function p2pCompactSourceText(value, maxLen) {
  value = String(value || "").trim();
  maxLen = maxLen || 44;

  if (value.length <= maxLen) return value;
  return value.slice(0, maxLen - 1) + "…";
}

function renderP2PApprovalPagination(rows) {
  var pageEl = root.querySelector(
    "#pkgApprovalPagination"
  );

  if (!pageEl) return;

  rows = rows || [];

  var total = rows.length;

  var totalPages = Math.ceil(
    total /
    state.APPROVAL_PER_PAGE
  );

  if (totalPages <= 1) {
    pageEl.innerHTML = "";
    return;
  }

  if (state.approvalPage > totalPages) {
    state.approvalPage = totalPages;
  }

  if (state.approvalPage < 1) {
    state.approvalPage = 1;
  }

  pageEl.innerHTML = `
    <div class="pkg-pagination-info">
      Page ${state.approvalPage} of ${totalPages}

      <span>
        ${total} pending requests
      </span>
    </div>

    <div class="pkg-pagination-actions">

      <button
        type="button"
        class="pkg-page-btn"
        id="pkgApprovalPrevPageBtn"
        ${
          state.approvalPage <= 1
            ? "disabled"
            : ""
        }
      >
        ‹ Prev
      </button>

      <button
        type="button"
        class="pkg-page-btn"
        id="pkgApprovalNextPageBtn"
        ${
          state.approvalPage >= totalPages
            ? "disabled"
            : ""
        }
      >
        Next ›
      </button>

    </div>
  `;

  var prevButton = root.querySelector(
    "#pkgApprovalPrevPageBtn"
  );

  var nextButton = root.querySelector(
    "#pkgApprovalNextPageBtn"
  );

  if (prevButton) {
    prevButton.addEventListener(
      "click",
      function () {
        if (state.approvalPage <= 1) {
          return;
        }

        state.approvalPage--;

        renderApprovalDash();

        var listEl = root.querySelector(
          "#pkgApprovalList"
        );

        if (listEl) {
          listEl.scrollTop = 0;
        }
      }
    );
  }

  if (nextButton) {
    nextButton.addEventListener(
      "click",
      function () {
        if (
          state.approvalPage >=
          totalPages
        ) {
          return;
        }

        state.approvalPage++;

        renderApprovalDash();

        var listEl = root.querySelector(
          "#pkgApprovalList"
        );

        if (listEl) {
          listEl.scrollTop = 0;
        }
      }
    );
  }
}

  function renderApprovalDash() {
