  normalizeP2PSearchValue(
    approvalSearchQuery
  )
) {
  pending = pending.filter(
    function (request) {
      return doesP2PRequestMatchSearch(
        request,
        approvalSearchQuery
      );
    }
  );
}

var approvalTotal = pending.length;

    var approvalTotalPages = Math.max(
      1,
      Math.ceil(
        approvalTotal /
        state.APPROVAL_PER_PAGE
      )
    );

    if (state.approvalPage > approvalTotalPages) {
      state.approvalPage = approvalTotalPages;
    }

    if (state.approvalPage < 1) {
      state.approvalPage = 1;
    }

    var approvalStart =
      (state.approvalPage - 1) *
      state.APPROVAL_PER_PAGE;

    var approvalPageRows = pending.slice(
      approvalStart,
      approvalStart + state.APPROVAL_PER_PAGE
