function getP2PSelectedApprover(panel, role, actionText) {
  role = String(role || "").trim().toLowerCase();

  var approverNameEl = panel
    ? panel.querySelector("#pkgApproverName")
    : null;

  var approverName = approverNameEl
    ? String(approverNameEl.value || "").trim()
    : "";

  var employeeId = approverNameEl && approverNameEl.dataset
    ? String(approverNameEl.dataset.employeeId || "").trim()
    : "";

  var selectedFlag = approverNameEl && approverNameEl.dataset
    ? String(approverNameEl.dataset.approverSelected || "").trim()
    : "";

  var storedName = panel && panel.dataset
    ? String(panel.dataset.cmApproverName || "").trim()
    : "";

  var storedEmployeeId = panel && panel.dataset
    ? String(panel.dataset.cmApproverEmployeeId || "").trim()
    : "";

  if (!approverName && storedName) {
    approverName = storedName;

    if (approverNameEl) {
      approverNameEl.value = storedName;
    }
  }

  if (!employeeId && storedEmployeeId) {
    employeeId = storedEmployeeId;
  }

  if (!approverName) {
    return {
      ok: false,
      message: "Please select your name before " + actionText + "."
    };
  }

  if (role === "cm") {
    var selectedFromSearch = !!employeeId && (
      selectedFlag === "1" ||
      !!(approverNameEl && approverNameEl.readOnly) ||
      !!(storedName && storedName === approverName)
    );

    if (!selectedFromSearch) {
      return {
        ok: false,
        message: "Please select Centre Manager / ACM from the search result before " + actionText + ". Manual typing is not allowed."
      };
    }
  }

  return {
    ok: true,
    name: approverName,
    employeeId: employeeId
  };
}

function p2pUniqueTextList(list) {
  var out = [];
  var seen = {};

  (list || []).forEach(function (value) {
    value = String(value || "").trim();
    if (!value) return;

    var key = value.toLowerCase();

    if (!seen[key]) {
      seen[key] = 1;
      out.push(value);
    }
  });

  return out;
}

function p2pGetInvoiceBookedByName(inv) {
  inv = inv || {};

  return String(
    inv.custom_referring_name ||
    inv.referring_name ||
    inv.ref_practitioner ||
    inv.custom_healthcare_practitioner ||
    inv.custom_doctor_name ||
    inv.custom_doctor_id ||
