  ).trim();
}

function p2pFetchBookedByFromSourcePlans(doc) {
  return fetchP2PLinkedSalesInvoices(doc)
    .then(function (rows) {
      rows = rows || [];

      var bookedByNames = rows
        .map(function (invoice) {
          return p2pGetInvoiceBookedByName(
            invoice
          );
        })
        .filter(Boolean);

      bookedByNames =
        p2pUniqueTextList(bookedByNames);

      var invoices = rows.map(function (invoice) {
        return {
          name: String(
            invoice.name || ""
          ).trim(),

          plan: String(
            invoice.therapy_plan_reference_id ||
            invoice.custom_therapy_plan_reference_id ||
            invoice.therapy_plan ||
            "No Therapy Plan"
          ).trim(),

          date: invoice.posting_date
            ? fmtDate(invoice.posting_date)
            : "—"
        };
      }).filter(function (invoice) {
        return !!invoice.name;
      });

      return {
        bookedBy:
          bookedByNames.join(", "),

        invoices:
          invoices
      };
    })
    .catch(function (error) {
      ("Unable to load Booked By and invoice details:", error, void 0);

      return {
        bookedBy: "",
        invoices: []
      };
    });
}

function updateP2PBookedByInDetailHeader(
  doc,
  panel
) {
  if (!doc || !panel) return;

