/* ============================================================
   CURRENT PENDING STAGE + TIME SINCE PREVIOUS APPROVAL
   ============================================================ */

function getP2PCurrentPendingStageInfo(doc) {
  doc = doc || {};

  var currentStatus = String(
    getStatus(doc) || ""
  ).trim();

  var statusText = [
    currentStatus,
    doc.approval_display_status,
    doc.approval_stage
  ]
    .filter(Boolean)
    .join(" | ");

  var stageLabel = "";
  var pendingFrom = "";
  var pendingFromLabel = "";

  /*
   * COO / Management becomes pending after
   * Audit Team approval.
   */
  if (
    /COO\s*\/\s*Management|COO|Management/i.test(
      statusText
    ) &&
    /Pending/i.test(statusText)
  ) {
    stageLabel =
      "COO / Management Approval Pending";

    pendingFrom =
      doc.authorised_date ||
      doc.audit_approved_date ||
      doc.operations_approved_date ||
      doc.approved_date ||
      doc.creation;

    pendingFromLabel =
      "Pending since Audit Team approval";
  }

  /*
   * Audit Team becomes pending after
   * Centre Manager approval.
   */
  else if (
    /Audit Team|Operations Head/i.test(
      statusText
    ) &&
    /Pending/i.test(statusText)
  ) {
    stageLabel =
      "Audit Team Approval Pending";

    pendingFrom =
      doc.approved_date ||
      doc.centre_manager_approved_date ||
      doc.cm_approved_date ||
      doc.creation;

    pendingFromLabel =
      "Pending since Centre Manager approval";
  }

  /*
   * Centre Manager is the first approval.
   * Its pending time starts from request creation.
   */
  else if (
    /Centre Manager/i.test(statusText) &&
    /Pending/i.test(statusText)
  ) {
    stageLabel =
      "Centre Manager Approval Pending";

    pendingFrom =
      doc.creation ||
      doc.date ||
      doc.modified;

    pendingFromLabel =
      "Pending since request submission";
  }

  /*
   * Completed, rejected, processing or any
   * status that is not an approval-pending stage.
   */
  if (!stageLabel) {
    return {
      text: p2pDisplayText(currentStatus),
      title: p2pDisplayText(currentStatus),
      duration: ""
    };
  }

  var startDate =
    p2pParseDateTime(pendingFrom);

  var duration = "";

  if (startDate) {
    duration = p2pFormatDuration(
      Math.max(
        Date.now() - startDate.getTime(),
        0
      )
    );
  }

  return {
    text:
      stageLabel +
      (duration ? " · " + duration : ""),

    title:
      pendingFromLabel +
      (
        pendingFrom
          ? " — " + fmtDateTime(pendingFrom)
          : ""
      ),

    duration: duration
  };
}

