function getP2PServerErrorMessage(errorValue) {
  if (!errorValue) {
    return "Unknown server error.";
  }

  if (typeof errorValue === "string") {
    return stripHtml(errorValue);
  }

  if (
    errorValue.message &&
    typeof errorValue.message === "string"
  ) {
    return stripHtml(errorValue.message);
  }

  if (
    errorValue.message &&
    typeof errorValue.message === "object" &&
    errorValue.message.message
  ) {
    return stripHtml(
      String(errorValue.message.message)
    );
  }

  if (errorValue._server_messages) {
    try {
      var parsedMessages =
        JSON.parse(errorValue._server_messages);

      if (
        Array.isArray(parsedMessages) &&
        parsedMessages.length
      ) {
        var firstMessage =
          JSON.parse(parsedMessages[0]);

        if (
          firstMessage &&
          firstMessage.message
        ) {
          return stripHtml(
            String(firstMessage.message)
          );
        }
      }
    } catch (messageParseError) {
      return stripHtml(
        String(errorValue._server_messages)
      );
    }
  }

  if (
    errorValue.responseJSON &&
    errorValue.responseJSON._server_messages
  ) {
    try {
      var responseMessages =
        JSON.parse(
          errorValue.responseJSON._server_messages
        );

      if (
        Array.isArray(responseMessages) &&
        responseMessages.length
      ) {
        var responseFirst =
          JSON.parse(responseMessages[0]);

        if (
          responseFirst &&
          responseFirst.message
        ) {
          return stripHtml(
            String(responseFirst.message)
          );
        }
      }
    } catch (responseParseError) {
      return stripHtml(
        String(
          errorValue.responseJSON._server_messages
        )
      );
    }
  }

  if (errorValue.exception) {
    return stripHtml(
      String(errorValue.exception)
    );
  }

  if (
    errorValue.responseJSON &&
    errorValue.responseJSON.exception
  ) {
    return stripHtml(
      String(
        errorValue.responseJSON.exception
      )
    );
  }

  if (errorValue.exc) {
    return stripHtml(
      String(errorValue.exc)
    );
  }

  try {
    return stripHtml(
      JSON.stringify(errorValue)
    );
  } catch (jsonError) {
    return "Unknown server error.";
  }
}


function sanitizeP2PTemporalFields(doc) {
  doc = doc || {};

  var temporalFields = [
    "date",
    "approved_date",
    "authorised_date",
    "coo_management_date",
    "final_table_edited_on",
    "client_signature_date",
    "conversion_date"
  ];

  temporalFields.forEach(function (fieldname) {
    if (
      Object.prototype.hasOwnProperty.call(
        doc,
        fieldname
      ) &&
      String(
        doc[fieldname] == null
          ? ""
          : doc[fieldname]
      ).trim() === ""
    ) {
      /*
       * MariaDB Date / Datetime columns cannot
       * receive an empty string.
       */
      doc[fieldname] = null;
    }
  });

  return doc;
}


function runP2PFinalAutomation(
  requestName,
  done
) {
  var finished = false;
  var timeoutId = null;

  function finish(ok, result) {
    if (finished) return;

    finished = true;

    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }

    if (typeof done === "function") {
      done(
        !!ok,
        result || {}
      );
    }
  }

  /*
   * Avoid leaving buttons permanently locked if
   * the request never returns.
   */
  timeoutId = setTimeout(function () {
    finish(false, {
      ok: false,
      code: "CLIENT_TIMEOUT",
      message:
        "The final automation did not return a response. " +
        "The approval buttons were restored. Refresh the request and verify its current status before retrying."
    });
  }, 120000);

  try {
    frappe.call({
      method: "p2p_run_final_automation",

      args: {
        request_name: requestName
      },

      callback: function (res) {
        var result =
          res && res.message
            ? res.message
            : {
                ok: false,
                code:
                  "EMPTY_AUTOMATION_RESPONSE",
                message:
                  "The final automation returned an empty response."
              };

        finish(
          !!result.ok,
          result
        );
      },

