function getP2PApprovalTherapyDoc(therapyName) {
  therapyName = String(therapyName || "").trim();

  return new Promise(function (resolve) {
    if (!therapyName) {
      resolve(null);
      return;
    }

    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Therapy Type",
        fields: ["name", "therapy_type", "healthcare_service_unit", "disabled"],
        filters: [["Therapy Type", "name", "=", therapyName]],
        limit_page_length: 1
      },
      callback: function (r1) {
        var rows1 = r1.message || [];

        if (rows1.length) {
          resolve(rows1[0]);
          return;
        }

        frappe.call({
          method: "frappe.client.get_list",
          args: {
            doctype: "Therapy Type",
            fields: ["name", "therapy_type", "healthcare_service_unit", "disabled"],
            filters: [["Therapy Type", "therapy_type", "=", therapyName]],
            limit_page_length: 1
          },
          callback: function (r2) {
            var rows2 = r2.message || [];
            resolve(rows2.length ? rows2[0] : null);
          },
          error: function () {
            resolve(null);
          }
        });
      },
      error: function () {
        resolve(null);
      }
    });
  });
}


function validateP2PApprovalTherapyRowsBeforeSave(doc, rows) {
  rows = rows || [];

  var targetCategory = getP2PApprovalTargetCategoryFullName(doc);

  if (!targetCategory) {
    return Promise.resolve({
      ok: false,
      message: "Target category is missing. Approval cannot be completed."
    });
  }

  if (!rows.length) {
    return Promise.resolve({
      ok: false,
      message: "Converted final table must have at least one therapy row."
    });
  }

  var chain = Promise.resolve({
    ok: true,
    message: ""
  });

  rows.forEach(function (row, idx) {
    chain = chain.then(function (previous) {
      if (!previous.ok) return previous;

      var therapy =
        row.converted_package__service_name ||
        row.service_package_name ||
        row.therapy_type ||
        row.service_name ||
        row.package_name ||
        "";

      therapy = String(therapy || "").trim();

      if (!therapy) {
        return {
          ok: false,
          message: "Row " + (idx + 1) + ": Therapy Type is required."
        };
      }

      return getP2PApprovalTherapyDoc(therapy).then(function (therapyDoc) {
        if (!therapyDoc) {
          return {
            ok: false,
            message: "Row " + (idx + 1) + ": Therapy Type does not exist: " + therapy
          };
        }

        if (num(therapyDoc.disabled || 0)) {
          return {
            ok: false,
            message: "Row " + (idx + 1) + ": Therapy Type is disabled: " + therapyDoc.name
          };
        }

        var unit = String(therapyDoc.healthcare_service_unit || "").trim();

        if (
          targetCategory !== "All Healthcare Service Units - LSACPL" &&
          unit !== targetCategory
        ) {
          return {
            ok: false,
            message:
              "Row " + (idx + 1) + ": Therapy Type " + therapyDoc.name +
              " belongs to " + (unit || "blank category") +
              ". Only " + targetCategory + " is allowed."
          };
        }

        // Store canonical Therapy Type name so backend receives clean value.
        row.converted_package__service_name = therapyDoc.name;
        row.service_package_name = therapyDoc.name;
        row.therapy_type = therapyDoc.name;
        row.service_name = therapyDoc.name;
        row.package_name = therapyDoc.name;

        return {
          ok: true,
          message: ""
        };
      });
    });
  });

  return chain;
}


function getP2PAutomationErrorMessage(result) {
  if (!result) return "Unknown automation error.";

  if (typeof result === "string") return result;

  if (result.message) return String(result.message);

  if (result._server_messages) return String(result._server_messages);

  try {
    return JSON.stringify(result);
  } catch (e) {
    return "Unknown automation error.";
  }
}


function resetP2PCooApprovalAfterAutomationFailure(
  requestName,
  result,
  done
) {
  var errorMessage =
    getP2PAutomationErrorMessage(result);

  frappe.call({
    method: "frappe.client.get",

    args: {
      doctype: DOCTYPE,
      name: requestName
    },

    callback: function (r) {
      var doc = r.message || {};

      if (!doc.name) {
        if (typeof done === "function") {
          done(false);
        }

        return;
      }

      /*
       * Reopen the request at COO approval.
       */
      doc.current_tab_step = 4;
      doc.approval_stage = STAGE.COO;
      doc.final_approval_status = "";
      doc.approval_display_status = STAGE.COO;
      doc.automation_status =
        "Pending Final Approval";

      doc.package_conversion_applied = 0;

      /*
       * Remove the failed COO approval information.
       */
      doc.coo_management_name = "";
      doc.coo_management_date = "";
      doc.coo_management_remarks = "";

      /*
       * Remove the failed COO version snapshot.
       */
      doc.coo_management_final_package = [];
      doc.coo_management_package_edited = 0;
      doc.coo_table_edit_remarks = "";

      /*
       * Restore the active converted-package table
       * to the Audit-approved version.
       */
      var auditRows =
        getP2PAuditApprovedRows(doc);

      if (auditRows.length) {
        doc.converted_package__service_name =
          buildP2PActiveConvertedRows(
            auditRows
          );

        var auditTotal =
          auditRows.reduce(function (sum, row) {
            return (
              sum +
              getP2PPackageVersionAmount(row)
            );
          }, 0);

        doc.new_package_total_price_rs =
          round(auditTotal);
      }

      /*
       * Remove metadata belonging to the failed
       * COO table edit. Audit history remains available
       * in audit_team_requested_package.
       */
      if (
        String(
          doc.final_table_edited_stage || ""
        ).indexOf("COO") !== -1
      ) {
        doc.final_table_edited_during_approval =
          num(
            doc.audit_team_package_edited || 0
          ) === 1
            ? 1
            : 0;

        doc.final_table_edited_stage =
          num(
            doc.audit_team_package_edited || 0
          ) === 1
            ? "Audit Team Approval"
            : "";

        doc.final_table_edited_by =
          num(
            doc.audit_team_package_edited || 0
          ) === 1
            ? (
                doc.authorised_name ||
                ""
              )
            : "";

        doc.final_table_edited_on =
          num(
            doc.audit_team_package_edited || 0
          ) === 1
            ? (
                doc.authorised_date ||
                ""
              )
            : "";

        var availableValue =
          num(
            doc.current_package__residual__balance_value_rs ||
            0
          );

        var restoredTotal =
          num(
            doc.new_package_total_price_rs ||
            0
          );

        var restoredOverride =
          Math.max(
            restoredTotal - availableValue,
            0
          );

        doc.approval_override_amount =
          restoredOverride;

        if (
          num(
            doc.audit_team_package_edited || 0
          ) === 1
        ) {
          doc.approval_override_note =
            "Audit Team approved package restored " +
            "after COO final automation failure. " +
            "Restored Package Total: ₹" +
            round(restoredTotal)
              .toLocaleString("en-IN") +
            (
              restoredOverride > 0
                ? ", Override Amount: ₹" +
                  round(restoredOverride)
                    .toLocaleString("en-IN") +
                  "."
                : "."
            );
        } else {
          doc.approval_override_note = "";
        }
      }

      doc.package_conversion_log =
        "Automation blocked before final completion.\n\n" +
        errorMessage;

        sanitizeP2PTemporalFields(doc);

      frappe.call({
        method: "frappe.client.save",

        args: {
          doc: doc
        },

        callback: function () {
          if (typeof done === "function") {
            done(true);
          }
        },

        error: function () {
          if (typeof done === "function") {
            done(false);
          }
        }
      });
    },

    error: function () {
      if (typeof done === "function") {
        done(false);
      }
    }
  });
}


