function getUsedSessions(plan) {
  var availed = Number(plan.total_sessions_completed || 0);

  if (availed > 0) return availed;

  Object.keys(plan || {}).forEach(function (key) {
    if (!Array.isArray(plan[key])) return;

    plan[key].forEach(function (child) {
      availed += num(
        child.completed_sessions ||
        child.availed_quantity ||
        child.sessions_completed ||
        0
      );
    });
  });

  return availed;
}

function p2pTherapyKey(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function getP2PInvoiceGrossTotal(inv) {
  return num(
    inv.rounded_total ||
    inv.grand_total ||
    inv.base_rounded_total ||
    inv.base_grand_total ||
    0
  );
}

function getP2PInvoicePaidAmount(inv) {
  var grossTotal = getP2PInvoiceGrossTotal(inv);
  var outstanding = num(inv.outstanding_amount || 0);

  // IMPORTANT:
  // Do not depend on inv.paid_amount.
  // In ERPNext, paid_amount may remain 0 even when invoice status is Paid.
  var paid = Math.max(grossTotal - outstanding, 0);

  if (paid <= 0 && String(inv.status || "") === "Paid" && grossTotal > 0) {
    paid = grossTotal;
  }

  return paid;
}

function getP2PInvoicePaidRatio(inv) {
  var grossTotal = getP2PInvoiceGrossTotal(inv);
  var paid = getP2PInvoicePaidAmount(inv);

  if (!grossTotal) return 0;

  var ratio = paid / grossTotal;

  if (ratio < 0) ratio = 0;
  if (ratio > 1) ratio = 1;

  return ratio;
}

function getP2PPaidItemAmountForTherapy(therapyType, invoices) {
  var target = normalizeP2PText(therapyType);
  var total = 0;
  var matched = false;

  if (!target) return {
    matched: false,
    amount: 0
  };

  (invoices || []).forEach(function (inv) {
    var paidRatio = getP2PInvoicePaidRatio(inv);

    (inv.items || []).forEach(function (item) {
      if (!isP2PInvoiceItemMatch(target, item)) return;

      matched = true;

      var taxable = num(
        item.net_amount ||
        item.base_net_amount ||
        item.amount ||
        item.base_amount ||
        0
      );

      var tax =
        num(item.cgst_amount || 0) +
        num(item.sgst_amount || 0) +
        num(item.igst_amount || 0) +
        num(item.cess_amount || 0);

      total += (taxable + tax) * paidRatio;
    });
  });

  return {
    matched: matched,
    amount: total
  };
}

function getP2PPlanPaidAvailableBalance(plan, linkedInvoices) {
  var therapyRows = getTherapyRowsForP2PConversion(plan);
  var totalAvailable = 0;

  (therapyRows || []).forEach(function (row) {
    var therapyType = String(row.therapy_type || "").trim();

    var totalSessions = num(
      row.current_total_sessions ||
      row.no_of_sessions ||
      row.sessions ||
      0
    );

    var completedSessions = num(
      row.completed_sessions ||
      row.sessions_completed ||
      row.availed_quantity ||
      0
    );

    var remainingSessions = Math.max(
      totalSessions - completedSessions,
      0
    );

    if (!therapyType || totalSessions <= 0 || remainingSessions <= 0) {
      return;
    }

    /*
     * P2P MONEY RULE
     * Conversion entitlement comes ONLY from the unused portion of a
     * therapy value that is actually present in the linked Sales Invoice
     * and actually paid.
     *
     * Complimentary / unbilled / invoice-unmatched therapy rows contribute
     * ZERO monetary value. This prevents the full invoice payment from being
     * redistributed to free/unbilled sessions when the package is converted.
     */
    var itemResult = getP2PPaidItemAmountForTherapy(
      therapyType,
      linkedInvoices
    );

    if (!itemResult || !itemResult.matched) {
      return;
    }

    var paidBilledAmount = Math.max(
      num(itemResult.amount || 0),
      0
    );

    if (paidBilledAmount <= 0) {
      return;
    }

    var paidValuePerSession =
      paidBilledAmount / totalSessions;

    var pendingPaidValue =
      paidValuePerSession * remainingSessions;

    totalAvailable += pendingPaidValue;
  });

  return round(totalAvailable);
}

function p2pBuildSelectedPlanObject(plan, invoices) {
  var linked = (invoices || []).filter(function (inv) {
    return getInvoiceTherapyPlanReference(inv) === plan.name;
  });

  var invoiceTotal = linked.reduce(function (s, inv) {
    return s + getP2PInvoiceGrossTotal(inv);
  }, 0);

  var outstanding = linked.reduce(function (s, inv) {
    return s + num(inv.outstanding_amount || 0);
  }, 0);

  var paidAmount = linked.reduce(function (s, inv) {
    return s + getP2PInvoicePaidAmount(inv);
  }, 0);

  var balValue = getP2PPlanPaidAvailableBalance(plan, linked);

  return {
    name: plan.name,
    balValue: balValue,
    invoiceTotal: invoiceTotal,
    paidAmount: paidAmount,
    outstanding: outstanding,
    linked: linked,
    branch: getPlanBranch(plan, linked),
    plan: plan
  };
}

