                getP2PFileTypeFromUrl(fileUrl) ||
                "File";

              var mandatory = cintSafe(r.is_mandatory) ? "Yes" : "No";

              var fileHtml = fileUrl
                ? `
                  <a
                    href="${esc(fileUrl)}"
                    target="_blank"
                    class="pkg-doc-open-link"
                     title="${esc(fileName)}"
                  >
                    ${esc(fileName)}
                  </a>
                `
                : `<span style="color:#C00000;font-weight:700">Missing file</span>`;

              return `
                <tr>
                  <td>${idx + 1}</td>
                  <td><strong>${esc(r.document_name || "-")}</strong></td>
                  <td>${esc(mandatory)}</td>
                  <td>${fileHtml}</td>
                  <td>${esc(fileType)}</td>
                  <td>${esc(r.remarks || "—")}</td>
                </tr>
              `;
            }).join("")
          }
        </tbody>
      </table>
    </div>
  `;
}

function getP2PFileNameFromUrl(url) {
  url = String(url || "").split("?")[0];

  if (!url) return "";

  var parts = url.split("/");
  return decodeURIComponent(parts[parts.length - 1] || "");
}

function getP2PFileTypeFromUrl(url) {
  url = String(url || "").split("?")[0].toLowerCase();

  if (url.endsWith(".pdf")) return "PDF";
  if (
    url.endsWith(".jpg") ||
    url.endsWith(".jpeg") ||
    url.endsWith(".png") ||
    url.endsWith(".webp")
  ) {
    return "Image";
  }

  return "File";
}

function cintSafe(value) {
  value = Number(value || 0);
  return isNaN(value) ? 0 : parseInt(value, 10);
}

  function hideAcList(box) { if (box) { box.innerHTML = ""; box.classList.remove("show"); } }
  function setText(id, val) { var el = root.querySelector("#" + id); if (el) el.textContent = val || "—"; }
  function num(v) { var n = parseFloat(v); return isNaN(n) ? 0 : n; }
  function round(v) { return Math.round(num(v) * 100) / 100; }
  function fmtDate(v) { if (!v) return "—"; var d = String(v).slice(0, 10).split("-"); if (d.length !== 3) return v; var m = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"]; return d[2] + "-" + (m[Number(d[1]) - 1] || d[1]) + "-" + d[0].slice(2); }

    function fmtDateTime(value) {
  if (!value) return "—";

  try {
    var s = String(value || "").trim();

    // Date only value from old records
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
      return fmtDate(s);
    }

    // Frappe datetime: YYYY-MM-DD HH:mm:ss
    var d = new Date(s.replace(" ", "T"));

    if (!d || isNaN(d.getTime())) {
      return fmtDate(value);
    }

    var day = String(d.getDate()).padStart(2, "0");
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    var month = months[d.getMonth()];
    var year = String(d.getFullYear()).slice(-2);

    var hours = d.getHours();
    var minutes = String(d.getMinutes()).padStart(2, "0");
    var ampm = hours >= 12 ? "PM" : "AM";

    hours = hours % 12;
    if (hours === 0) hours = 12;

    return day + "-" + month + "-" + year + " " + hours + ":" + minutes + " " + ampm;
  } catch (e) {
    return String(value || "—");
  }
}

function getP2PStagePillClass(value) {
  value = String(value || "");

  if (/Rejected/i.test(value)) {
    return "pkg-pill-rejected";
  }

  if (/Process Completed|Approved$/i.test(value)) {
    return "pkg-pill-completed";
  }

  if (/Centre Manager/i.test(value)) {
    return "pkg-pill-cm-pending";
  }

  if (/Audit Team|Operations Head/i.test(value)) {
    return "pkg-pill-audit-pending";
  }

  if (/COO|Management/i.test(value)) {
    return "pkg-pill-coo-pending";
  }

  return "";
}

function stripHtml(v) { return String(v || "").replace(/<[^>]*>/g, "").trim(); }
  function esc(v) { return String(v === undefined || v === null ? "" : v).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#039;"); }
  function getToday() { var d = new Date(); return d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0") + "-" + String(d.getDate()).padStart(2,"0"); }
  function getErrorMsg(err) {
    if (err && err._server_messages) { try { return JSON.parse(JSON.parse(err._server_messages)[0]).message || "Error"; } catch(e){} }
    if (err && err.message) return err.message;
    return "An error occurred";
  }

  function getSafeErrorMsg(err) {
  try {
    if (!err) return "Unknown error occurred.";

    if (typeof err === "string") {
      return stripHtml(err);
    }

    if (err.message) {
      return stripHtml(err.message);
    }

    if (err._server_messages) {
      var messages = JSON.parse(err._server_messages || "[]");

      if (messages.length) {
        var first = JSON.parse(messages[0]);
        return stripHtml(first.message || messages[0]);
      }
    }

    if (err.responseJSON && err.responseJSON._server_messages) {
      var serverMessages = JSON.parse(err.responseJSON._server_messages || "[]");

      if (serverMessages.length) {
        var firstServerMsg = JSON.parse(serverMessages[0]);
        return stripHtml(firstServerMsg.message || serverMessages[0]);
      }
    }

    if (err.exc) {
      return stripHtml(err.exc);
    }

    return stripHtml(JSON.stringify(err));
  } catch (e) {
    return "Unexpected error occurred. Please refresh and try again.";
  }
}

// ============================================================
// P2P FIELD VALIDATIONS
// ============================================================

function p2pWordCount(value) {
  return String(value || "").trim().split(/\s+/).filter(Boolean).length;
}

function p2pIsValidAmount(value) {
  value = String(value || "").trim();

  if (!value) return false;
  if (!/^\d+(\.\d{1,2})?$/.test(value)) return false;
  if (Number(value) < 0) return false;

  return true;
}

function p2pIsValidPositiveQty(value) {
  value = String(value || "").trim();

  if (!value) return false;
  if (!/^\d+$/.test(value)) return false;
  if (Number(value) <= 0) return false;

  return true;
}

function p2pValidateRemarks(value, label, required) {
  value = String(value || "").trim();

  if (required && !value) {
    frappe.msgprint(label + " is required.");
    return false;
  }

  if (p2pWordCount(value) > 400) {
    frappe.msgprint(label + " cannot exceed 400 words.");
    return false;
  }

  return true;
}

function validateP2PConversionBeforeSubmit() {
  if (!state.clientDoc) {
    frappe.msgprint("Please select a client first.");
    return false;
  }

  if (!state.clientSignatureDataURL && !(typeof sigState !== "undefined" && sigState.hasSignature)) {
    frappe.msgprint("Client signature is required before submitting conversion.");
    return false;
  }

  if (!state.selectedPlans || !state.selectedPlans.length) {
    frappe.msgprint("Please select one source Therapy Plan.");
    return false;
  }

  if (!state.newPlanRows || !state.newPlanRows.length) {
    frappe.msgprint("Please add at least one converted package row.");
    return false;
  }

  var hasValidRow = false;

  for (var i = 0; i < state.newPlanRows.length; i++) {
    var row = state.newPlanRows[i] || {};

    var therapyName =
      row.converted_package__service_name ||
      row.service_package_name ||
      row.therapy_type ||
      row.item_code ||
      "";

    var sessions =
      row.no_of_sessions ||
      row.converted_quantity ||
      row.qty ||
      row.quantity ||
      "";

    var amount =
      row.total_amount ||
      row.amount ||
      row.balance_amount ||
      "";

    if (!therapyName) {
      frappe.msgprint("Converted package row " + (i + 1) + ": Therapy / package name is required.");
      return false;
    }

    if (!p2pIsValidPositiveQty(sessions)) {
      frappe.msgprint("Converted package row " + (i + 1) + ": Sessions must be greater than 0.");
      return false;
    }

    if (!p2pIsValidAmount(amount)) {
      frappe.msgprint("Converted package row " + (i + 1) + ": Amount must be valid.");
      return false;
    }

    hasValidRow = true;
  }

  if (!hasValidRow) {
    frappe.msgprint("Please add at least one valid converted package row.");
    return false;
  }

  var availableValue = Number(state.combinedBalance || 0);
  var newPackageTotal = Number(state.grandTotal || 0);

  if (newPackageTotal <= 0) {
    frappe.msgprint("New package total amount must be greater than 0.");
    return false;
  }

  if (availableValue > 0 && newPackageTotal > availableValue) {
    frappe.msgprint(
      "New package amount cannot exceed available value. Available: ₹" +
      availableValue.toLocaleString("en-IN") +
      ", New Package: ₹" +
      newPackageTotal.toLocaleString("en-IN")
    );
    return false;
  }

  var termsCheck = root.querySelector("#pkgTermsCheck");
  if (termsCheck && !termsCheck.checked) {
    frappe.msgprint("Please accept the terms and conditions before submitting.");
    return false;
  }

  return true;
}

function validateP2PApproval(action, role, panel) {
  var remarksEl = panel ? panel.querySelector("textarea") : null;
  var remarks = remarksEl ? String(remarksEl.value || "").trim() : "";

  if (!p2pValidateRemarks(remarks, "Approval / Rejection Remarks", true)) {
    if (remarksEl) remarksEl.focus();
    return false;
  }

  if (role === "cm") {
    var approverInput = panel ? panel.querySelector("input, select") : null;

    if (!approverInput || !String(approverInput.value || "").trim()) {
      frappe.msgprint("Please select Centre Manager / ACM approver.");
      return false;
    }
  }

  return true;
}


function initP2PSupportingDocsState() {
  state.supportingAttachments = [];

  P2P_REQUIRED_DOCUMENTS.forEach(function (row) {
    state.supportingAttachments.push({
      id: row.key,
      document_name: row.document_name,
      is_mandatory: 1,
      fixed: true,
      file: null,
      file_name: "",
      file_size: 0,
      file_type: "",
      remarks: ""
    });
  });

  state.currentAttachmentRowId = "";
}

function bindP2PSupportingDocs() {
  var fileInput = root.querySelector("#pkgAttachmentInput");
  var rowsBox = root.querySelector("#pkgAttachmentRows");
  var addBtn = root.querySelector("#pkgAddOptionalAttachmentBtn");

  if (addBtn && addBtn.dataset.boundP2POptionalAttach !== "1") {
    addBtn.dataset.boundP2POptionalAttach = "1";

    addBtn.addEventListener("click", function () {
      addP2POptionalAttachmentRow();
    });
  }

  if (fileInput && fileInput.dataset.boundP2PAttachInput !== "1") {
    fileInput.dataset.boundP2PAttachInput = "1";

    fileInput.addEventListener("change", function () {
      var file = fileInput.files && fileInput.files[0] ? fileInput.files[0] : null;
      fileInput.value = "";

      if (!file || !state.currentAttachmentRowId) return;

      setP2PAttachmentFile(state.currentAttachmentRowId, file);
    });
  }

  if (rowsBox && rowsBox.dataset.boundP2PAttachRows !== "1") {
    rowsBox.dataset.boundP2PAttachRows = "1";

    rowsBox.addEventListener("click", function (e) {
      var uploadBtn = e.target.closest(".pkg-attachment-upload");
      var removeBtn = e.target.closest(".pkg-attachment-remove");

      if (uploadBtn) {
        state.currentAttachmentRowId = uploadBtn.dataset.id || "";

        if (fileInput) {
          fileInput.click();
        }

        return;
      }

      if (removeBtn) {
        var removeId = removeBtn.dataset.id || "";

        state.supportingAttachments = (state.supportingAttachments || []).filter(function (item) {
          return item.fixed || item.id !== removeId;
        });

        renderP2PSupportingDocs();
      }
    });

    rowsBox.addEventListener("input", function (e) {
      var id = e.target.dataset.id || "";

      if (e.target.classList.contains("pkg-attachment-remarks")) {
        updateP2PAttachmentRow(id, "remarks", e.target.value || "");
      }

      if (e.target.classList.contains("pkg-attachment-document-name")) {
        updateP2PAttachmentRow(id, "document_name", e.target.value || "");
      }
    });
  }

  renderP2PSupportingDocs();
}

function addP2POptionalAttachmentRow() {
  state.supportingAttachments = state.supportingAttachments || [];

  if (state.supportingAttachments.length >= P2P_ATTACHMENT_MAX_TOTAL_ROWS) {
    frappe.msgprint("Maximum " + P2P_ATTACHMENT_MAX_TOTAL_ROWS + " document rows are allowed.");
    return;
  }

  state.supportingAttachments.push({
    id: "optional_" + Date.now() + "_" + Math.floor(Math.random() * 100000),
    document_name: "",
    is_mandatory: 0,
    fixed: false,
    file: null,
    file_name: "",
    file_size: 0,
    file_type: "",
    remarks: ""
  });

  renderP2PSupportingDocs();
}

function updateP2PAttachmentRow(rowId, fieldname, value) {
  (state.supportingAttachments || []).forEach(function (item) {
    if (item.id === rowId) {
      item[fieldname] = value;
    }
  });

  // Recheck submit eligibility when an optional document name changes.
  updateGoBtn();
}

function setP2PAttachmentFile(rowId, file) {
  var error = validateP2PAttachmentFile(file);

  if (error) {
    frappe.msgprint({
      title: "Invalid Attachment",
      indicator: "red",
      message: error
    });
    return;
  }

  var found = false;

  (state.supportingAttachments || []).forEach(function (item) {
    if (item.id === rowId) {
      item.file = file;
      item.file_name = file.name || "";
      item.file_size = file.size || 0;
      item.file_type = getP2PAttachmentType(file);
      found = true;
    }
  });

  if (!found) {
    frappe.msgprint("Attachment row not found. Please refresh and try again.");
    return;
  }

  renderP2PSupportingDocs();
}

function validateP2PMandatoryAttachments() {
  var rows = state.supportingAttachments || [];
  var missing = [];

  P2P_REQUIRED_DOCUMENTS.forEach(function (requiredRow) {
    var row = rows.find(function (item) {
      return item.id === requiredRow.key;
    });

    if (!row || !row.file) {
      missing.push(requiredRow.document_name);
    }
  });

  if (missing.length) {
    return {
      ok: false,
      message:
        "Please attach these mandatory documents:<br><br>" +
        missing.map(function (name) {
          return "• " + esc(name);
        }).join("<br>")
    };
  }

  var optionalWithoutName = [];

  rows.forEach(function (row, idx) {
    if (!row.is_mandatory && row.file && !String(row.document_name || "").trim()) {
      optionalWithoutName.push(idx + 1);
    }
  });

  if (optionalWithoutName.length) {
    return {
      ok: false,
      message: "Please enter Document Name for extra attachment row(s): " + optionalWithoutName.join(", ")
    };
  }

  return {
    ok: true,
    message: ""
  };
}

function validateP2PAttachmentFile(file) {
  var name = String(file.name || "").toLowerCase();
  var type = String(file.type || "").toLowerCase();

  var allowedExt = /\.(pdf|jpg|jpeg|png|webp)$/i.test(name);
  var allowedMime = [
    "application/pdf",
    "image/jpeg",
    "image/jpg",
    "image/png",
    "image/webp"
  ].indexOf(type) !== -1;

  if (!allowedExt && !allowedMime) {
    return "Only PDF, JPG, JPEG, PNG, or WEBP files are allowed.";
  }

  var maxBytes = P2P_ATTACHMENT_MAX_SIZE_MB * 1024 * 1024;

  if (file.size > maxBytes) {
    return "File size cannot exceed " + P2P_ATTACHMENT_MAX_SIZE_MB + " MB.";
  }

  return "";
}

function getP2PAttachmentType(file) {
  var name = String(file.name || "").toLowerCase();
  var type = String(file.type || "").toLowerCase();

  if (type === "application/pdf" || name.endsWith(".pdf")) {
    return "PDF";
  }

  return "Image";
}

function renderP2PSupportingDocs() {
  var rowsBox = root.querySelector("#pkgAttachmentRows");
  var countBox = root.querySelector("#pkgAttachmentCount");

  if (!rowsBox) return;

  var rows = state.supportingAttachments || [];
  var pending = 0;

  P2P_REQUIRED_DOCUMENTS.forEach(function (requiredRow) {
    var row = rows.find(function (item) {
      return item.id === requiredRow.key;
    });

    if (!row || !row.file) {
      pending++;
    }
  });

  if (countBox) {
    if (pending > 0) {
      countBox.textContent = pending + " mandatory file(s) pending";
      countBox.style.color = "#C00000";
    } else {
      countBox.textContent = "All mandatory files attached";
      countBox.style.color = "#1E7A34";
    }
  }

  rowsBox.innerHTML = rows.map(function (item, idx) {
    var documentNameHtml = item.fixed
      ? `<strong>${esc(item.document_name)}</strong>`
      : `
        <input
          type="text"
          class="pkg-attachment-document-name"
          data-id="${esc(item.id)}"
          value="${esc(item.document_name || "")}"
          maxlength="80"
          placeholder="Enter document name"
        >
      `;

    var fileHtml = item.file
      ? `
        <div class="pkg-attachment-file-name">${esc(item.file_name || "-")}</div>
        <div class="pkg-attachment-file-size">${esc(formatP2PFileSize(item.file_size || 0))}</div>
      `
      : `<span class="pkg-empty">No file attached</span>`;

    var mandatoryHtml = item.is_mandatory
      ? `<span class="pkg-mandatory-badge">Yes</span>`
      : `<span class="pkg-optional-badge">No</span>`;

    var removeButton = item.fixed
      ? ""
      : `
        <button
          type="button"
          class="pkg-attachment-remove"
          data-id="${esc(item.id)}"
        >
          Remove
        </button>
      `;

    return `
      <tr>
        <td>${idx + 1}</td>
        <td>${documentNameHtml}</td>
        <td>${mandatoryHtml}</td>
        <td>${fileHtml}</td>
        <td>
          ${
            item.file_type
              ? `<span class="pkg-attachment-pill">${esc(item.file_type)}</span>`
              : "—"
          }
        </td>
        <td>
          <textarea
            class="pkg-attachment-remarks"
            data-id="${esc(item.id)}"
            maxlength="300"
            placeholder="Remarks, optional"
          >${esc(item.remarks || "")}</textarea>
        </td>
        <td>
          <button
            type="button"
            class="pkg-attachment-upload"
            data-id="${esc(item.id)}"
          >
            ${item.file ? "Replace" : "Upload"}
          </button>
          ${removeButton}
        </td>
      </tr>
    `;
  }).join("");

  // Upload, replace, remove, and reset actions all pass through this
  // renderer, so refresh the Submit button after every attachment change.
  updateGoBtn();
}

function formatP2PFileSize(bytes) {
  bytes = Number(bytes || 0);

  if (bytes < 1024) return bytes + " B";
  if (bytes < 1024 * 1024) return Math.round(bytes / 1024) + " KB";

  return Math.round((bytes / (1024 * 1024)) * 10) / 10 + " MB";
}

function uploadP2PSupportingDocs(docname) {
  var rows = (state.supportingAttachments || []).filter(function (item) {
    return item && item.file;
  });

  if (!rows.length) {
    return Promise.resolve([]);
  }

  /*
   * Upload files one-by-one instead of all at once.
   *
   * Benefits:
   * 1. Easier to identify the exact file that failed.
   * 2. Avoids multiple simultaneous File inserts in Frappe.
   * 3. Makes retry behaviour predictable.
   */
  var uploaded = [];

  return rows.reduce(function (chain, item) {
    return chain.then(function () {
      return uploadSingleP2PAttachment(docname, item).then(function (result) {
        uploaded.push(result);
      });
    });
  }, Promise.resolve()).then(function () {
    return uploaded;
  });
}

function makeP2PUniqueUploadFileName(file, docname) {
  var originalName = String(
    (file && file.name) || "attachment"
  ).trim();

  var dotIndex = originalName.lastIndexOf(".");

  var baseName =
    dotIndex > 0
      ? originalName.substring(0, dotIndex)
      : originalName;

  var extension =
    dotIndex > 0
      ? originalName.substring(dotIndex)
      : "";

  // Remove characters that can create unsafe or awkward file paths.
  baseName = baseName
    .replace(/[^\w\- ]+/g, "")
    .replace(/\s+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");

  if (!baseName) {
    baseName = "attachment";
  }

  var requestPart = String(docname || "P2P")
    .replace(/[^\w\-]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "")
    .substring(0, 50);

  if (!requestPart) {
    requestPart = "P2P";
  }

  var timestamp = Date.now();

  var randomPart = Math.random()
    .toString(36)
    .substring(2, 8);

  return (
    requestPart +
    "_" +
    timestamp +
    "_" +
    randomPart +
    "_" +
    baseName +
    extension.toLowerCase()
  );
}

function getP2PFileTypeFromFile(file) {
  if (!file) return "";

  var name = String(file.name || "").toLowerCase();

  if (name.endsWith(".pdf")) return "PDF";
  if (name.endsWith(".jpg") || name.endsWith(".jpeg")) return "JPG";
  if (name.endsWith(".png")) return "PNG";
  if (name.endsWith(".webp")) return "WEBP";

  return file.type || "File";
}

function extractP2PUploadError(response) {
  response = response || {};

  /*
   * Frappe frequently returns _server_messages as a JSON encoded array,
   * where every array item may itself be another JSON encoded object.
   */
  if (response._server_messages) {
    try {
      var messages = JSON.parse(response._server_messages);

      if (Array.isArray(messages)) {
        var cleaned = messages
          .map(function (message) {
            try {
              var parsed = JSON.parse(message);

              return (
                parsed.message ||
                parsed.title ||
                String(message || "")
              );
            } catch (e) {
              return String(message || "");
            }
          })
          .filter(Boolean);

        if (cleaned.length) {
          return cleaned.join("<br>");
        }
      }
    } catch (e) {
      // Fall through to the remaining Frappe error properties.
    }
  }

  if (response.exception) {
    return String(response.exception);
  }

  if (response.exc_type) {
    return String(response.exc_type);
  }

  if (response.exc) {
    return String(response.exc);
  }

  if (typeof response.message === "string") {
    return response.message;
  }

  return "Server returned HTTP 500.";
}

function uploadSingleP2PAttachment(docname, item) {
  return new Promise(function (resolve, reject) {
    if (!item || !item.file) {
      reject("No file selected.");
      return;
    }

    var file = item.file;
    var maxBytes = P2P_ATTACHMENT_MAX_SIZE_MB * 1024 * 1024;

    if (Number(file.size || 0) > maxBytes) {
      reject(
        (file.name || "File") +
        " exceeds " +
        P2P_ATTACHMENT_MAX_SIZE_MB +
        " MB."
      );
      return;
    }

    var originalFileName =
      item.file_name ||
      file.name ||
      "attachment";

    var uploadFileName = makeP2PUniqueUploadFileName(
      file,
      docname
    );

    var formData = new FormData();

    /*
     * IMPORTANT:
     * Send a unique physical filename to Frappe.
     * This prevents FileExistsError when the same client document name
     * was uploaded previously or when a failed request is retried.
     */
    formData.append(
      "file",
      file,
      uploadFileName
    );

    formData.append("is_private", "0");

    /*
     * Do NOT send doctype/docname here.
     *
     * The uploaded File URL is stored in the P2P supporting_documents
     * child table immediately after all uploads finish. Avoiding direct
     * attachment during upload prevents parent attachment side-effects
     * and keeps this flow controlled by the child table.
     */

    var xhr = new XMLHttpRequest();

    xhr.open(
      "POST",
      "/api/method/upload_file",
      true
    );

    xhr.withCredentials = true;

    var csrfToken =
      (window.frappe && frappe.csrf_token) ||
      window.csrf_token ||
      "";

    if (csrfToken) {
      xhr.setRequestHeader(
        "X-Frappe-CSRF-Token",
        csrfToken
      );
    }

    xhr.onload = function () {
      var response = {};

      try {
        response = JSON.parse(
          xhr.responseText || "{}"
        );
      } catch (e) {
        ("[P2P Upload] Invalid server response:", {
            status: xhr.status,
            raw: xhr.responseText,
            file: originalFileName,
            upload_file_name: uploadFileName,
            request: docname
          }, void 0);

        reject(
          "Server returned an invalid response while uploading " +
          originalFileName +
          ". HTTP " +
          xhr.status
        );
        return;
      }

      if (
        xhr.status >= 200 &&
        xhr.status < 300 &&
        response.message
      ) {
        var uploadedFile = response.message || {};

        ("[P2P Upload] Success:", uploadedFile, void 0);

        resolve({
          document_name: item.document_name || "",
          is_mandatory: item.is_mandatory ? 1 : 0,
          file_url: uploadedFile.file_url || "",

          // Keep the user's original filename in the child-table UI.
          file_name: originalFileName,

          // Useful for debugging; ignored by the child table if no field exists.
          stored_file_name:
            uploadedFile.file_name ||
            uploadFileName,

          file_type:
            item.file_type ||
            getP2PFileTypeFromFile(file),

          remarks: item.remarks || "",
          file_docname: uploadedFile.name || ""
        });

        return;
      }

      ("[P2P Upload] Server error:", {
          status: xhr.status,
          response: response,
          raw: xhr.responseText,
          file: originalFileName,
          upload_file_name: uploadFileName,
          request: docname
        }, void 0);

      reject(
        "Unable to upload " +
        originalFileName +
        ". " +
        extractP2PUploadError(response)
      );
    };

    xhr.onerror = function () {
      ("[P2P Upload] Network error:", {
          file: originalFileName,
          upload_file_name: uploadFileName,
          request: docname
        }, void 0);

      reject(
        "Network error while uploading " +
        originalFileName
      );
    };

    xhr.onabort = function () {
      reject(
        "Upload cancelled for " +
        originalFileName
      );
    };

    xhr.send(formData);
  });
}

function saveP2PAttachmentChildRows(docname, uploadedDocs) {
  uploadedDocs = uploadedDocs || [];

  if (!uploadedDocs.length) {
    return Promise.resolve([]);
  }

  return new Promise(function (resolve, reject) {
    frappe.call({
      method: "frappe.client.get",
      args: {
        doctype: DOCTYPE,
        name: docname
      },
      callback: function (r) {
        var savedDoc = r.message;

        if (!savedDoc) {
          reject("Unable to reload saved request for attachment update.");
          return;
        }

        savedDoc[P2P_ATTACHMENT_CHILD_FIELD] = [];

        uploadedDocs.forEach(function (fileRow) {
          savedDoc[P2P_ATTACHMENT_CHILD_FIELD].push({
            doctype: P2P_ATTACHMENT_CHILD_DOCTYPE,
            document_name: fileRow.document_name,
            attachment: fileRow.file_url,
            file_name: fileRow.file_name,
            file_type: fileRow.file_type,
            is_mandatory: fileRow.is_mandatory ? 1 : 0,
            remarks: fileRow.remarks || "",
            uploaded_by: frappe.session && frappe.session.user ? frappe.session.user : "",
            uploaded_on: frappe.datetime && frappe.datetime.now_datetime
              ? frappe.datetime.now_datetime()
              : ""
          });
        });

        frappe.call({
          method: "frappe.client.save",
          args: {
            doc: savedDoc
          },
          callback: function () {
            resolve(uploadedDocs);
          },
          error: function (err) {
            reject(getErrorMsg(err) || "Attachment child table save failed.");
          }
        });
      },
      error: function (err) {
        reject(getErrorMsg(err) || "Unable to reload saved request.");
      }
    });
  });
}


/* ============================================================
   LIFE APPROVALS REPORT — RETURN AFTER APPROVAL
   Supports links opened with:
   ?tab=approval&role=...&request=...&return_to=/approvals-report-test
   ============================================================ */
function lifeP2PReturnToApprovalsReport(docname, action, role) {
  var returnTo = getP2PUrlParam("return_to");
  if (!returnTo) return;

  var targetUrl = null;
  try {
    targetUrl = new URL(returnTo, window.location.origin);
    if (targetUrl.origin !== window.location.origin) return;
  } catch (e) {
    return;
  }

  window.setTimeout(function () {
    var payload = {
      type: "LIFE_APPROVAL_RESULT",
      module: "P2P",
      request: String(docname || ""),
      action: String(action || ""),
      role: String(role || "")
    };

    try {
      if (window.opener && !window.opener.closed) {
        window.opener.postMessage(payload, window.location.origin);
        window.opener.focus();
        window.close();
        if (window.closed) return;
      }
    } catch (e) {
      ("Unable to return to LIFE Approvals Report opener:", e, void 0);
    }

    window.location.href = targetUrl.href;
  }, 700);
}


