  printFrame.style.opacity = "0";
  printFrame.style.pointerEvents = "none";
  document.body.appendChild(printFrame);

  var frameDocument =
    printFrame.contentDocument ||
    (printFrame.contentWindow && printFrame.contentWindow.document);

  if (!frameDocument || !printFrame.contentWindow) {
    printFrame.remove();
    frappe.msgprint({
      title: "Print Unable to Start",
      indicator: "red",
      message: "The print document could not be prepared. Please refresh the page and try again."
    });
    return;
  }

  frameDocument.open();
  frameDocument.write(buildP2PConversionPrintDocument(doc));
  frameDocument.close();

  window.setTimeout(function () {
    try {
      printFrame.contentWindow.focus();
      printFrame.contentWindow.print();
    } catch (error) {
      ("P2P print failed:", error, void 0);
      frappe.msgprint({
        title: "Print Failed",
        indicator: "red",
        message: "Unable to open the print screen. Please refresh and try again."
      });
    }

    window.setTimeout(function () {
      if (printFrame && printFrame.parentNode) {
        printFrame.parentNode.removeChild(printFrame);
      }
    }, 30000);
  }, autoPrint ? 500 : 300);
}

function renderP2PCompletedPrintActions(doc) {
  if (!isP2PConversionPrintReady(doc)) return "";

  return (
    "<div class='pkg-completed-print-card'>" +
      "<div><div class='pkg-completed-print-title'>Client Conversion Document</div>" +
      "<div class='pkg-completed-print-help'>All approvals and Therapy Plan conversion are completed. The final document can now be printed or saved as PDF.</div></div>" +
      "<div class='pkg-completed-print-buttons'>" +
        "<button type='button' class='pkg-btn-outline pkg-p2p-print-btn'>🖨 Print</button>" +
        "<button type='button' class='pkg-btn-primary pkg-p2p-pdf-btn'>⬇ Download PDF</button>" +
      "</div>" +
    "</div>"
  );
}

function bindP2PCompletedPrintActions(doc, panel) {
  if (!panel || !isP2PConversionPrintReady(doc)) return;

  var printBtn = panel.querySelector(".pkg-p2p-print-btn");
  var pdfBtn = panel.querySelector(".pkg-p2p-pdf-btn");

  if (printBtn) {
    printBtn.addEventListener("click", function () {
      openP2PCompletedConversionPrint(doc, true);
    });
  }

  if (pdfBtn) {
    pdfBtn.addEventListener("click", function () {
      openP2PCompletedConversionPrint(doc, true);
    });
  }
}


init();

})();
